-- Easy Professions (Forever): guide texts in zhCN (translated from wow-professions.com/forever)
local _, ns = ...
ns.AddTranslation("zhCN", {
  ["This WoW Forever Alchemy leveling guide will show you the fastest and cheapest way to level your Alchemy skill from 1 to 300. You will also find every trainer location and where to train Alchemy past 75, 150 and 225."] = "这份 WoW Forever 炼金术升级指南将告诉你把炼金术技能从 1 升到 300 的最快、最省钱的方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习炼金术。",
  ["Below you will find the full shopping list, the Alchemy trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Alchemy is best combined with Herbalism, with these two you can save a lot of gold because you don't have to buy the herbs from the Auction House."] = "下面是完整的购物清单、按新手区和主城列出的炼金术训练师，以及从学徒到大师每个技能区间最便宜的配方。炼金术最好搭配草药学，这样你不必从拍卖行购买草药，可以省下很多金币。",
  ["This is based on the Forever beta. Leveling takes a long time, so testing the higher levels on live will take a while. If you find something that's off, send me feedback."] = "本指南基于 Forever 测试服。升级需要很长时间，所以在正式服上测试高等级部分还需要一段时间。如果发现有不对的地方，请给我反馈。",
  ["Shopping List"] = "购物清单",
  ["These numbers are estimates. Once a recipe turns yellow you won't get a skill point from every craft, so you might need a few more or a few less."] = "这些数字是估算值。配方变黄后，并不是每次制作都能获得技能点，所以你可能需要多做或少做几个。",
  ["Alchemy Trainer Locations"] = "炼金术训练师位置",
  ["Apprentice Alchemy has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中学习学徒级炼金术没有等级要求，所以新建的角色也能学。",
  ["Every capital city has a trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "每座主城都有训练师。你也可以询问卫兵，训练师的位置会以红旗标记在你的地图上。",
  ["Horde"] = "部落",
  ["Alliance"] = "联盟",
  ["Capital Cities"] = "主城",
  ["Orgrimmar: {n:0:horde:Whuut}"] = "奥格瑞玛：{n:0:horde:Whuut}",
  ["Undercity: {n:0:horde:Doctor Martin Felben}"] = "幽暗城：{n:0:horde:Doctor Martin Felben}",
  ["Thunder Bluff: {n:0:horde:Kray}"] = "雷霆崖：{n:0:horde:Kray}",
  ["Starting Zones"] = "新手区",
  ["Not every zone has a trainer, the table shows the closest one for each race."] = "并不是每个区域都有训练师，下表列出了每个种族最近的训练师。",
  ["Race"] = "种族",
  ["Zone"] = "区域",
  ["Closest trainer"] = "最近的训练师",
  ["Orc, Troll"] = "兽人、巨魔",
  ["Durotar"] = "杜隆塔尔",
  ["{n:0:horde:Miao'zan} in Sen'jin Village"] = "森金村的 {n:0:horde:Miao'zan}",
  ["Tauren"] = "牛头人",
  ["Mulgore"] = "莫高雷",
  ["There is no Alchemy trainer in Mulgore, go to {n:0:horde:Kray} on the middle rise in Thunder Bluff"] = "莫高雷没有炼金术训练师，请前往雷霆崖中层平台的 {n:0:horde:Kray}",
  ["Undead"] = "亡灵",
  ["Tirisfal Glades"] = "提瑞斯法林地",
  ["{n:0:horde:Carolai Anise} in the small house at the north-west end of Brill"] = "布瑞尔西北端小屋里的 {n:0:horde:Carolai Anise}",
  ["{n:0::Iaadaria Bitterwind} or {n:0::Valiena Swiftgale} in Valanaar, {n:0::Nyassa Swiftdraught} in Shen'dar Village"] = "Valanaar 的 {n:0::Iaadaria Bitterwind} 或 {n:0::Valiena Swiftgale}，Shen'dar Village 的 {n:0::Nyassa Swiftdraught}",
  ["Stormwind City: {n:0:alliance:Tel'Athir}"] = "暴风城：{n:0:alliance:Tel'Athir}",
  ["Ironforge: {n:0:alliance:Vosur Brakthel}"] = "铁炉堡：{n:0:alliance:Vosur Brakthel}",
  ["Darnassus: {n:0:alliance:Milla Fairancora}"] = "达纳苏斯：{n:0:alliance:Milla Fairancora}",
  ["Human"] = "人类",
  ["Elwynn Forest"] = "艾尔文森林",
  ["{n:0:alliance:Alchemist Mallory} in a cottage in the hills between Stormwind and Northshire"] = "暴风城与北郡之间山丘上小屋里的 {n:0:alliance:Alchemist Mallory}",
  ["Dwarf, Gnome"] = "矮人、侏儒",
  ["Dun Morogh"] = "丹莫罗",
  ["There is no Alchemy trainer in Dun Morogh, go to {n:0:alliance:Vosur Brakthel} in Tinker Town in Ironforge"] = "丹莫罗没有炼金术训练师，请前往铁炉堡侏儒区的 {n:0:alliance:Vosur Brakthel}",
  ["Night Elf"] = "暗夜精灵",
  ["Teldrassil"] = "泰达希尔",
  ["{n:0:alliance:Cyndra Kindwhisper} in a small house east of the inn in Dolanaar"] = "多兰纳尔旅店东边小屋里的 {n:0:alliance:Cyndra Kindwhisper}",
  ["You can find every Alchemy trainer for Horde and Alliance on my WoW Forever Alchemy Trainers page."] = "你可以在我的 WoW Forever 炼金术训练师页面找到部落和联盟的所有炼金术训练师。",
  ["Apprentice Alchemy (1-55)"] = "学徒炼金术 (1-55)",
  ["9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 Silverleaf, 9 Empty Vial"] = "9x {s:1245250:inv_potion_77:Elixir of Minor Force} - 9 银叶草，9 空瓶",
  ["The vials are sold by Alchemy Supply and Trade Supply vendors, most trainers have one nearby. In Undercity the closest one is {n:0:horde:Algernon}, in Dolanaar it's {n:0:alliance:Narret Shadowgrove}."] = "空瓶由炼金供应商和商业供应商出售，大多数训练师附近都有一个。在幽暗城最近的是 {n:0:horde:Algernon}，在多兰纳尔是 {n:0:alliance:Narret Shadowgrove}。",
  ["45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 Silverleaf, 45 Peacebloom, 45 Empty Vial"] = "45x {s:7183:inv_potion_63:Elixir of Minor Defense} - 45 银叶草，45 宁神花，45 空瓶",
  ["Journeyman Alchemy (55-150)"] = "熟练炼金术 (55-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Alchemy. You need {b}Alchemy 50{/b} and {b}level 10{/b}:"] = "要突破 75，请拜访以下训练师之一学习熟练炼金术。你需要 {b}炼金术 50{/b} 和 {b}10 级{/b}：",
  ["{b}Horde trainers:{/b}"] = "{b}部落训练师：{/b}",
  ["Orgrimmar: {n:0:horde:Yelmak}"] = "奥格瑞玛：{n:0:horde:Yelmak}",
  ["Undercity: {n:0:horde:Doctor Marsh}"] = "幽暗城：{n:0:horde:Doctor Marsh}",
  ["Thunder Bluff: {n:0:horde:Bena Winterhoof}"] = "雷霆崖：{n:0:horde:Bena Winterhoof}",
  ["{b}Alliance trainers:{/b}"] = "{b}联盟训练师：{/b}",
  ["Stormwind City: {n:0:alliance:Lilyssia Nightbreeze}"] = "暴风城：{n:0:alliance:Lilyssia Nightbreeze}",
  ["Ironforge: {n:0:alliance:Tally Berryfizz}"] = "铁炉堡：{n:0:alliance:Tally Berryfizz}",
  ["Darnassus: {n:0:alliance:Sylvanna Forestmoon}"] = "达纳苏斯：{n:0:alliance:Sylvanna Forestmoon}",
  ["10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 Mageroyal, 10 Peacebloom, 10 Empty Vial"] = "10x {s:2331:inv_potion_70:Minor Mana Potion} - 10 魔皇草，10 宁神花，10 空瓶",
  ["28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 Earthroot, 28 Peacebloom, 28 Empty Vial"] = "28x {s:2334:inv_potion_42:Elixir of Minor Fortitude} - 56 地根草，28 宁神花，28 空瓶",
  ["30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 Mageroyal, 60 Briarthorn, 30 Empty Vial"] = "30x {s:3171:inv_potion_06:Elixir of Wisdom} - 30 魔皇草，60 石南草，30 空瓶",
  ["Keep the elixirs if you also level Tailoring, you will need them for the Gloves of Meditation."] = "如果你同时在练裁缝，请留着这些药剂，制作冥想手套时会用到。",
  ["10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 Mageroyal, 10 Stranglekelp, 10 Empty Vial"] = "10x {s:3173:inv_potion_71:Lesser Mana Potion} - 10 魔皇草，10 荆棘藻，10 空瓶",
  ["20x {s:7837:inv_potion_38:Fire Oil} - 40 Firefin Snapper, 20 Empty Vial"] = "20x {s:7837:inv_potion_38:Fire Oil} - 40 火鳞鳗，20 空瓶",
  ["You get 2 oils from every craft. Keep 30 of them, you will need them for the Elixir of Fire Power in the next part."] = "每次制作可获得 2 瓶火焰油。留下 30 瓶，下一部分制作火力药剂时需要用到。",
  ["Expert Alchemy (150-225)"] = "专家炼金术 (150-225)",
  ["To train past 150, visit {n:0:horde:Doctor Herbert Halsey} in Undercity (Horde) or {n:0:alliance:Ainethil} in Darnassus (Alliance) and learn Expert Alchemy. You need {b}Alchemy 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要突破 150，请拜访幽暗城的 {n:0:horde:Doctor Herbert Halsey}（部落）或达纳苏斯的 {n:0:alliance:Ainethil}（联盟）学习专家炼金术。你需要 {b}炼金术 125{/b} 和 {b}20 级{/b}，费用为 50 银币。",
  ["15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 Fire Oil, 15 Kingsblood, 15 Leaded Vial"] = "15x {s:7845:inv_potion_55:Elixir of Fire Power} - 30 火焰油，15 皇血草，15 铅瓶",
  ["These are the Fire Oils you kept."] = "这些就是你之前留下的火焰油。",
  ["36x {s:3452:inv_potion_72:Mana Potion} - 36 Stranglekelp, 36 Kingsblood, 36 Leaded Vial"] = "36x {s:3452:inv_potion_72:Mana Potion} - 36 荆棘藻，36 皇血草，36 铅瓶",
  ["36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 Liferoot, 36 Stranglekelp, 36 Leaded Vial"] = "36x {s:7259:inv_potion_06:Nature Protection Potion} - 36 活根草，36 荆棘藻，36 铅瓶",
  ["{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} is sold by these vendors, it's bind on pickup, so buy it with the character that levels Alchemy:"] = "{i:6057:inv_scroll_03:Recipe: Nature Protection Potion} 由以下商人出售，它是拾取后绑定的，所以请用练炼金术的角色购买：",
  ["{n:0:horde:Bronk} in Feralas"] = "菲拉斯的 {n:0:horde:Bronk}",
  ["{n:0:alliance:Logannas} in Feralas"] = "菲拉斯的 {n:0:alliance:Logannas}",
  ["{n:0::Glyx Brewright} in Stranglethorn Vale"] = "荆棘谷的 {n:0::Glyx Brewright}",
  ["{n:0::Alchemist Pestlezugg} in Tanaris"] = "塔纳利斯的 {n:0::Alchemist Pestlezugg}",
  ["Artisan Alchemy (225-300)"] = "大师炼金术 (225-300)",
  ["To train past 225, visit {n:0:horde:Rogvar} in Stonard, Swamp of Sorrows (Horde) or {n:0:alliance:Kylanna Windwhisper} in Feathermoon Stronghold, Feralas (Alliance) and learn Artisan Alchemy. You need {b}Alchemy 200{/b} and {b}level 35{/b}."] = "要突破 225，请拜访悲伤沼泽斯通纳德的 {n:0:horde:Rogvar}（部落）或菲拉斯羽月要塞的 {n:0:alliance:Kylanna Windwhisper}（联盟）学习大师炼金术。你需要 {b}炼金术 200{/b} 和 {b}35 级{/b}。",
  ["26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 Liferoot, 26 Stranglekelp, 26 Leaded Vial"] = "26x {s:7259:inv_potion_06:Nature Protection Potion} - 26 活根草，26 荆棘藻，26 铅瓶",
  ["15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 Blindweed, 15 Khadgar's Whisker, 15 Crystal Vial"] = "15x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 15 盲目草，15 卡德加的胡须，15 水晶瓶",
  ["47x {s:17551:inv_potion_68:Stonescale Oil} - 47 Stonescale Eel, 47 Leaded Vial"] = "47x {s:17551:inv_potion_68:Stonescale Oil} - 47 石鳞鳗，47 铅瓶",
  ["{b}Keep all of them{/b}, one craft makes 2 and the elixirs at 265 need all 94."] = "{b}全部留着{/b}，每次制作产出 2 瓶，265 的药剂需要全部 94 瓶。",
  ["Alternative recipe"] = "替代配方",
  ["If {i:13422:inv_misc_fish_11:Stonescale Eel} is expensive, skip this and keep making the Elixir of Greater Intellect until 265 (about 21), then make the Superior Mana Potions under 265-300."] = "如果 {i:13422:inv_misc_fish_11:Stonescale Eel} 很贵，就跳过这一步，继续制作强效智力药剂直到 265（大约 21 个），然后在 265-300 制作超级法力药水。",
  ["10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 Blindweed, 10 Khadgar's Whisker, 10 Crystal Vial"] = "10x {s:11465:inv_potion_10:Elixir of Greater Intellect} - 10 盲目草，10 卡德加的胡须，10 水晶瓶",
  ["47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 Stonescale Oil, 47 Sungrass, 47 Crystal Vial"] = "47x {s:17554:inv_potion_66:Elixir of Greater Defense} - 94 石鳞油，47 太阳草，47 水晶瓶",
  ["{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} is sold by {n:0:horde:Kor'geld} in Orgrimmar and {n:0:alliance:Soolie Berryfizz} in Ironforge."] = "{i:13478:inv_scroll_03:Recipe: Elixir of Superior Defense} 由奥格瑞玛的 {n:0:horde:Kor'geld} 和铁炉堡的 {n:0:alliance:Soolie Berryfizz} 出售。",
  ["If you skipped the Stonescale Oil, make this:"] = "如果你跳过了石鳞油，就做这个：",
  ["55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 Sungrass, 110 Blindweed, 55 Crystal Vial."] = "55x {s:17553:inv_potion_74:Superior Mana Potion} - 110 太阳草，110 盲目草，55 水晶瓶。",
  ["{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} is sold by {n:0:horde:Algernon} in Undercity and {n:0:alliance:Ulthir} in Darnassus."] = "{i:13477:inv_scroll_03:Recipe: Superior Mana Potion} 由幽暗城的 {n:0:horde:Algernon} 和达纳苏斯的 {n:0:alliance:Ulthir} 出售。",
  ["This WoW Forever Blacksmithing leveling guide will show you the fastest and cheapest way to level your Blacksmithing skill from 1 to 300. You will also find every trainer location and where to train Blacksmithing past 75, 150 and 225."] = "这份 WoW Forever 锻造升级指南将告诉你把锻造技能从 1 升到 300 的最快、最省钱的方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习锻造。",
  ["Below you will find the full shopping list, the Blacksmithing trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Blacksmithing uses a lot of ore, so I recommend leveling it together with Mining, you will need a lot of gold if you want to buy everything from the Auction House."] = "下面是完整的购物清单、按新手区和主城列出的锻造训练师，以及从学徒到大师每个技能区间最便宜的配方。锻造需要大量矿石，所以我建议和采矿一起练，如果所有材料都从拍卖行购买，你会需要很多金币。",
  ["The Thorium Bars include the 140 you need for the four quests."] = "瑟银锭数量已包含四个任务所需的 140 块。",
  ["Blacksmithing Trainer Locations"] = "锻造训练师位置",
  ["Apprentice Blacksmithing has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中学习学徒级锻造没有等级要求，所以新建的角色也能学。",
  ["Every capital city has a trainer except Darnassus. You can also ask a guard, then it will be marked with a red flag on your map."] = "除达纳苏斯外，每座主城都有训练师。你也可以询问卫兵，训练师的位置会以红旗标记在你的地图上。",
  ["Orgrimmar: {n:0:horde:Ug'thok}"] = "奥格瑞玛：{n:0:horde:Ug'thok}",
  ["Undercity: {n:0:horde:Basil Frye}"] = "幽暗城：{n:0:horde:Basil Frye}",
  ["Thunder Bluff: {n:0:horde:Thrag Stonehoof}"] = "雷霆崖：{n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Dwukk} at the forge in Razor Hill"] = "剃刀岭熔炉旁的 {n:0:horde:Dwukk}",
  ["There is no Blacksmithing trainer in Mulgore, go to {n:0:horde:Thrag Stonehoof} on the lower rise in Thunder Bluff"] = "莫高雷没有锻造训练师，请前往雷霆崖下层平台的 {n:0:horde:Thrag Stonehoof}",
  ["{n:0:horde:Angus Hammerhand} at Bandarion Keep. Nobody near him sells a {i:5956:inv_hammer_20:Blacksmith Hammer}, {b}buy one before you go{/b} from {n:0:horde:Walter Mason} in Deathknell or {n:0:horde:Abigail Shiel} in Brill."] = "Bandarion Keep 的 {n:0:horde:Angus Hammerhand}。他附近没有人出售 {i:5956:inv_hammer_20:Blacksmith Hammer}，{b}去之前先买一把{/b}，可以在丧钟镇的 {n:0:horde:Walter Mason} 或布瑞尔的 {n:0:horde:Abigail Shiel} 处购买。",
  ["{n:0::Daeann Steelwind} in Valanaar, {n:0::Aedi Thriceforged} in Shen'dar Village"] = "Valanaar 的 {n:0::Daeann Steelwind}，Shen'dar Village 的 {n:0::Aedi Thriceforged}",
  ["Stormwind City: {n:0:alliance:Dane Lindgren}"] = "暴风城：{n:0:alliance:Dane Lindgren}",
  ["Ironforge: {n:0:alliance:Groum Stonebeard}"] = "铁炉堡：{n:0:alliance:Groum Stonebeard}",
  ["{n:0:alliance:Smith Argus} in Goldshire, across from the inn"] = "闪金镇旅店对面的 {n:0:alliance:Smith Argus}",
  ["{n:0:alliance:Tognus Flintfire} in Kharanos, across from the Thunderbrew Distillery"] = "卡拉诺斯雷酒酿制厂对面的 {n:0:alliance:Tognus Flintfire}",
  ["There is no Blacksmithing trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Delfrum Flintbeard} in Auberdine, Darkshore"] = "泰达希尔和达纳苏斯都没有锻造训练师，最近的是黑海岸奥伯丁的 {n:0:alliance:Delfrum Flintbeard}",
  ["You can find every Blacksmithing trainer for Horde and Alliance on my WoW Forever Blacksmithing Trainers page."] = "你可以在我的 WoW Forever 锻造训练师页面找到部落和联盟的所有锻造训练师。",
  ["Apprentice Blacksmithing (1-75)"] = "学徒锻造 (1-75)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer} when you learn Blacksmithing, most recipes need it, so you can craft gear for yourself while you level. It costs a few copper, open your faction below to see who sells it closest to your trainer."] = "学习锻造时顺便买一把 {i:5956:inv_hammer_20:Blacksmith Hammer}，大多数配方都需要它，这样你在升级时就能为自己打造装备。它只要几个铜币，展开下面你的阵营，看看离你的训练师最近的出售者是谁。",
  ["Horde vendors"] = "部落商人",
  ["Vendor"] = "商人",
  ["Orgrimmar"] = "奥格瑞玛",
  ["{n:0:horde:Sumi}, right next to the trainer"] = "{n:0:horde:Sumi}，就在训练师旁边",
  ["Undercity"] = "幽暗城",
  ["{n:0:horde:Samuel Van Brunt}, right next to the trainer"] = "{n:0:horde:Samuel Van Brunt}，就在训练师旁边",
  ["Thunder Bluff"] = "雷霆崖",
  ["{n:0:horde:Taur Stonehoof}, right next to the trainer"] = "{n:0:horde:Taur Stonehoof}，就在训练师旁边",
  ["{n:0:horde:Flakk} in Razor Hill"] = "剃刀岭的 {n:0:horde:Flakk}",
  ["{n:0:horde:Walter Mason} in Deathknell {n:0:horde:Abigail Shiel} in Brill"] = "丧钟镇的 {n:0:horde:Walter Mason} 布瑞尔的 {n:0:horde:Abigail Shiel}",
  ["{n:0::Halavuul Cragwind}, the Mining trainer in Valanaar {n:0::Aedi Thriceforged} in Shen'dar Village"] = "{n:0::Halavuul Cragwind}，Valanaar 的采矿训练师 Shen'dar Village 的 {n:0::Aedi Thriceforged}",
  ["Alliance vendors"] = "联盟商人",
  ["Stormwind City"] = "暴风城",
  ["{n:0:alliance:Kaita Deepforge}, right next to the trainer"] = "{n:0:alliance:Kaita Deepforge}，就在训练师旁边",
  ["Ironforge"] = "铁炉堡",
  ["{n:0:alliance:Thurgrum Deepforge}, right next to the trainer"] = "{n:0:alliance:Thurgrum Deepforge}，就在训练师旁边",
  ["{n:0:alliance:Tharynn Bouden} in Goldshire"] = "闪金镇的 {n:0:alliance:Tharynn Bouden}",
  ["{n:0:alliance:Thrawn Boltar}, right next to the trainer"] = "{n:0:alliance:Thrawn Boltar}，就在训练师旁边",
  ["Darkshore"] = "黑海岸",
  ["{n:0:alliance:Elisa Steelhand} in Auberdine, right next to the trainer"] = "奥伯丁的 {n:0:alliance:Elisa Steelhand}，就在训练师旁边",
  ["30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 Rough Stone"] = "30x {s:2660:inv_stone_sharpeningstone_01:Rough Sharpening Stone} - 30 劣质石头",
  ["30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 Rough Stone"] = "30x {s:3320:inv_stone_grindingstone_01:Rough Grinding Stone} - 60 劣质石头",
  ["Keep 10 of them, you need them for the Silver Rods at 75."] = "留下 10 个，75 时制作银棒需要用到。",
  ["36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 Coarse Stone"] = "36x {s:3326:inv_stone_grindingstone_02:Coarse Grinding Stone} - 72 粗糙的石头",
  ["Make all 36, you will need them for the bracers at 95 and 112."] = "36 个全部做完，95 和 112 制作护腕时需要用到。",
  ["If you are not at 75 after these, make a few more."] = "如果做完这些还没到 75，就再多做几个。",
  ["Journeyman Blacksmithing (75-150)"] = "熟练锻造 (75-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Blacksmithing. You need {b}Blacksmithing 50{/b} and {b}level 10{/b}:"] = "要突破 75，请拜访以下训练师之一学习熟练锻造。你需要 {b}锻造 50{/b} 和 {b}10 级{/b}：",
  ["Orgrimmar: {n:0:horde:Snarl}"] = "奥格瑞玛：{n:0:horde:Snarl}",
  ["Undercity: {n:0:horde:James Van Brunt}"] = "幽暗城：{n:0:horde:James Van Brunt}",
  ["Thunder Bluff: {n:0:horde:Karn Stonehoof}"] = "雷霆崖：{n:0:horde:Karn Stonehoof}",
  ["Tirisfal Glades: {n:0:horde:Angus Hammerhand} at Bandarion Keep"] = "提瑞斯法林地：Bandarion Keep 的 {n:0:horde:Angus Hammerhand}",
  ["Zephras Isle: {n:0::Daeann Steelwind} in Valanaar"] = "Zephras Isle：Valanaar 的 {n:0::Daeann Steelwind}",
  ["Stormwind City: {n:0:alliance:Therum Deepforge}"] = "暴风城：{n:0:alliance:Therum Deepforge}",
  ["Ironforge: {n:0:alliance:Rotgath Stonebeard}"] = "铁炉堡：{n:0:alliance:Rotgath Stonebeard}",
  ["5x {s:7818:inv_staff_01:Silver Rod} - 5 Silver Bar, 10 Rough Grinding Stone"] = "5x {s:7818:inv_staff_01:Silver Rod} - 5 银锭，10 劣质磨刀石",
  ["You need the {i:5956:inv_hammer_20:Blacksmith Hammer} from here on."] = "从这里开始需要 {i:5956:inv_hammer_20:Blacksmith Hammer}。",
  ["Make 5x {s:2666:inv_belt_03:Runed Copper Belt} instead (10 Copper Bar each) if one Silver Bar costs more than 10 Copper Bars."] = "如果一块银锭比 10 块铜锭还贵，就改做 5x {s:2666:inv_belt_03:Runed Copper Belt}（每个 10 铜锭）。",
  ["18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 Copper Bar"] = "18x {s:2666:inv_belt_03:Runed Copper Belt} - 180 铜锭",
  ["5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 Bronze Bar, 10 Coarse Grinding Stone"] = "5x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 25 青铜锭，10 粗磨刀石",
  ["Use 10 of the Coarse Grinding Stones you made at 50 and keep the other 26 for 112."] = "用掉你在 50 时做的 10 个粗磨刀石，剩下 26 个留到 112。",
  ["20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 Heavy Stone"] = "20x {s:3337:inv_stone_grindingstone_03:Heavy Grinding Stone} - 60 沉重的石头",
  ["Keep them, you need all 20 for the Golden Scale Bracers at 180."] = "留着它们，180 制作金鳞护腕时 20 个全部要用。",
  ["13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 Bronze Bar, 26 Coarse Grinding Stone"] = "13x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 65 青铜锭，26 粗磨刀石",
  ["24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 Bronze Bar, 96 Weak Flux, 48 Medium Leather"] = "24x {s:2742:inv_sword_04:Bronze Shortsword} - 120 青铜锭，96 弱效助熔剂，48 中皮",
  ["I recommend these over the Patterned Bronze Bracers because they sell for more than twice as much to a vendor, so they end up cheaper."] = "我推荐做这个而不是图纹青铜护腕，因为它卖给商人的价格是后者的两倍多，所以最终更便宜。",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} and the {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} for the Bronze Warhammers (140-150) are sold by the Blacksmithing Supply vendor right next to the Blacksmithing trainer in every capital city."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} 以及青铜战锤（140-150）所需的 {i:3466:inv_misc_ammo_gunpowder_01:Strong Flux} 由每座主城锻造训练师旁边的锻造供应商出售。",
  ["If you disenchant your greens:"] = "如果你会分解绿色装备：",
  ["24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 Bronze Bar, 48 Coarse Grinding Stone."] = "24x {s:2672:inv_bracer_07:Patterned Bronze Bracers} - 120 青铜锭，48 粗磨刀石。",
  ["10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 Bronze Bar, 10 Strong Flux, 10 Medium Leather"] = "10x {s:9985:inv_hammer_18:Bronze Warhammer} - 80 青铜锭，10 强效助熔剂，10 中皮",
  ["Expert Blacksmithing (150-215)"] = "专家锻造 (150-215)",
  ["To train past 150, visit {n:0:horde:Saru Steelfury} in Orgrimmar (Horde) or {n:0:alliance:Bengus Deepforge} in Ironforge (Alliance) and learn Expert Blacksmithing. You need {b}Blacksmithing 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要突破 150，请拜访奥格瑞玛的 {n:0:horde:Saru Steelfury}（部落）或铁炉堡的 {n:0:alliance:Bengus Deepforge}（联盟）学习专家锻造。你需要 {b}锻造 125{/b} 和 {b}20 级{/b}，费用为 50 银币。",
  ["30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 Iron Bar, 30 Green Dye"] = "30x {s:3501:inv_bracer_06:Green Iron Bracers} - 180 铁锭，30 绿色染料",
  ["Green Dye is sold by {n:0:horde:Tamar} in Orgrimmar and {n:0:alliance:Bombus Finespindle} in Ironforge."] = "绿色染料由奥格瑞玛的 {n:0:horde:Tamar} 和铁炉堡的 {n:0:alliance:Bombus Finespindle} 出售。",
  ["8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 Solid Stone"] = "8x {s:9920:inv_stone_grindingstone_04:Solid Grinding Stone} - 32 坚固的石头",
  ["Keep them, you need 6 for the Heavy Mithril Axes at 210."] = "留着它们，210 制作重型秘银斧时需要 6 个。",
  ["20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 Steel Bar, 40 Heavy Grinding Stone"] = "20x {s:7223:inv_bracer_10:Golden Scale Bracers} - 100 钢锭，40 重磨刀石",
  ["Use the 20 Heavy Grinding Stones you made at 100 and make 20 more (60 {i:2838:inv_stone_12:Heavy Stone})."] = "用掉你在 100 时做的 20 个重磨刀石，再做 20 个（60 {i:2838:inv_stone_12:Heavy Stone}）。",
  ["If you have Mining 165, you can smelt the {i:3859:inv_ingot_steel:Steel Bars} yourself from {i:3575:inv_ingot_iron:Iron Bar} and {i:3857:inv_ore_tin_01:Coal}. Coal is sold by the Blacksmithing Supply vendor next to the Blacksmithing trainer in every capital city."] = "如果你的采矿达到 165，可以用 {i:3575:inv_ingot_iron:Iron Bar} 和 {i:3857:inv_ore_tin_01:Coal} 自己熔炼 {i:3859:inv_ingot_steel:Steel Bars}。煤炭由每座主城锻造训练师旁边的锻造供应商出售。",
  ["Alliance players should keep 6 of these. You might need them if you choose Armorsmithing."] = "联盟玩家应该留下 6 件。如果你选择防具锻造，可能会用到。",
  ["17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 Mithril Bar"] = "17x {s:9931:inv_pants_04:Mithril Plate Pants} - 204 秘银锭",
  ["I recommend these over the Heavy Mithril Gauntlets because they sell for more than three times as much to a vendor, so they end up cheaper."] = "我推荐做这个而不是重型秘银护手，因为它卖给商人的价格是后者的三倍多，所以最终更便宜。",
  ["6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 Mithril Bar, 12 Citrine, 6 Solid Grinding Stone, 24 Heavy Leather"] = "6x {s:9993:inv_axe_14:Heavy Mithril Axe} - 72 秘银锭，12 黄水晶，6 坚固磨刀石，24 重皮",
  ["Keep 2 of these. You might need them if you choose Weaponsmithing."] = "留下 2 把。如果你选择武器锻造，可能会用到。",
  ["Blacksmithing Specializations"] = "锻造专精",
  ["At {b}Blacksmithing 200{/b} and {b}level 40{/b}, you can specialize in Armorsmithing or Weaponsmithing to craft powerful armor or weapons. Choosing one is optional, you don't need it to level Blacksmithing, and you can choose later too."] = "在 {b}锻造 200{/b} 和 {b}40 级{/b} 时，你可以选择专精防具锻造或武器锻造，打造强力的护甲或武器。专精是可选的，升级锻造并不需要它，你也可以以后再选。",
  ["For information on how to become an Armorsmith or a Weaponsmith, please see my separate guides:"] = "关于如何成为防具锻造师或武器锻造师，请参阅我的单独指南：",
  ["Artisan Blacksmithing (215-300)"] = "大师锻造 (215-300)",
  ["To train past 225, visit {n:0::Brikk Keencraft} in Booty Bay, Stranglethorn Vale and learn Artisan Blacksmithing. You need {b}Blacksmithing 200{/b} and {b}level 35{/b}, and both factions learn it there."] = "要突破 225，请拜访荆棘谷藏宝海湾的 {n:0::Brikk Keencraft} 学习大师锻造。你需要 {b}锻造 200{/b} 和 {b}35 级{/b}，两个阵营都在那里学习。",
  ["{i:7989:inv_scroll_06:Plans: Mithril Spurs} is a world drop. If you already have it, you can use the {b}Mithril Spurs{/b} tab instead."] = "{i:7989:inv_scroll_06:Plans: Mithril Spurs} 是世界掉落。如果你已经有了，可以改用 {b}秘银马刺{/b} 标签页。",
  ["Heavy Mithril"] = "重型秘银",
  ["Mithril Spurs"] = "秘银马刺",
  ["10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 Mithril Bar"] = "10x {s:9959:inv_chest_plate10:Heavy Mithril Breastplate} - 160 秘银锭",
  ["Keep 2 of these. You might need them if you choose Armorsmithing."] = "留下 2 件。如果你选择防具锻造，可能会用到。",
  ["5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 Dense Stone"] = "5x {s:16641:inv_stone_sharpeningstone_05:Dense Sharpening Stone} - 5 致密的石头",
  ["16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 Mithril Bar, 64 Thick Leather"] = "16x {s:9968:inv_boots_plate_01:Heavy Mithril Boots} - 224 秘银锭，64 厚皮",
  ["5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 Thorium Bar, 30 Rugged Leather, 5 Aquamarine"] = "5x {s:16647:inv_belt_01:Imperial Plate Belt} - 110 瑟银锭，30 硬甲皮，5 海蓝宝石",
  ["You can get the recipe from the {q:7653::Imperial Plate Belt} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it. Do his {q:7652::A Blue Light Bargain} quest first, it unlocks the Imperial Plate quests."] = "你可以在塔纳利斯从 {n:14567::Derotain Mudsipper} 处接 {q:7653::Imperial Plate Belt} 任务（需要 {b}50 级{/b}）获得配方。完成任务需要 20 块瑟银锭。先做他的 {q:7652::A Blue Light Bargain} 任务，它会解锁帝国板甲系列任务。",
  ["{b}The next three recipes are also from the same NPC{/b}, so make sure to bring at least 140 Thorium Bar with you to get all 4 recipes."] = "{b}接下来的三个配方也来自同一个 NPC{/b}，所以一定要带上至少 140 块瑟银锭，才能拿到全部 4 个配方。",
  ["If you have the plans for one of these world drops, you can make it from 240 instead:"] = "如果你有以下任意一个世界掉落的设计图，可以从 240 开始改做它：",
  ["240-255: 27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 Mithril Bar, 27 Aquamarine, 54 Lesser Moonstone, 54 Moss Agate, 27 Solid Grinding Stone, 54 Mageweave Cloth"] = "240-255：27x {s:10005:inv_sword_30:Dazzling Mithril Rapier} - 378 秘银锭，27 海蓝宝石，54 次级月亮石，54 苔藓玛瑙，27 坚固磨刀石，54 魔纹布",
  ["240-255: 20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 Mithril Bar, 40 Core of Earth, 20 Solid Grinding Stone, 80 Thick Leather"] = "240-255：20x {s:10009:inv_hammer_17:Runed Mithril Hammer} - 360 秘银锭，40 大地之核，20 坚固磨刀石，80 厚皮",
  ["240-255: 17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 Thorium Bar, 68 Blue Power Crystal"] = "240-255：17x {s:16644:inv_bracer_13:Thorium Bracers} - 204 瑟银锭，68 蓝色能量水晶",
  ["10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 Mithril Bar, 30 Solid Grinding Stone (120 Solid Stone)"] = "10x {s:9964:ability_rogue_sprint:Mithril Spurs} - 40 秘银锭，30 坚固磨刀石（120 坚固的石头）",
  ["33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 Mithril Bar, 99 Solid Grinding Stone (396 Solid Stone)"] = "33x {s:9964:ability_rogue_sprint:Mithril Spurs} - 132 秘银锭，99 坚固磨刀石（396 坚固的石头）",
  ["{b}The next three recipes all come from one NPC in Tanaris{/b}, so make sure to bring at least 120 Thorium Bar with you to get all 3 recipes."] = "{b}接下来的三个配方都来自塔纳利斯的同一个 NPC{/b}，所以一定要带上至少 120 块瑟银锭，才能拿到全部 3 个配方。",
  ["27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 Thorium Bar, 27 Star Ruby"] = "27x {s:16649:inv_bracer_19:Imperial Plate Bracers} - 540 瑟银锭，27 星辰红宝石",
  ["You get the recipe from the {q:7655::Imperial Plate Bracer} quest (Requires {b}level 50{/b}) in Tanaris from {n:14567::Derotain Mudsipper}. You will need 20 Thorium Bar to complete it."] = "你可以在塔纳利斯从 {n:14567::Derotain Mudsipper} 处接 {q:7655::Imperial Plate Bracer} 任务（需要 {b}50 级{/b}）获得配方。完成任务需要 20 块瑟银锭。",
  ["20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 Thorium Bar, 20 Star Ruby, 20 Aquamarine"] = "20x {s:16657:inv_boots_plate_01:Imperial Plate Boots} - 680 瑟银锭，20 星辰红宝石，20 海蓝宝石",
  ["You get the recipe from the {q:7654::Imperial Plate Boots} quest, it needs 40 Thorium Bar."] = "配方来自 {q:7654::Imperial Plate Boots} 任务，需要 40 块瑟银锭。",
  ["{b}Note:{/b} It wasn't possible to level this far on the beta, so this part only relies on the data I found in the game files. There might be more recipes we haven't discovered yet, but if there is nothing else, these are the only recipes you can use to level until 300."] = "{b}注意：{/b}在测试服上无法升到这么高，所以这一部分只依据我在游戏文件中找到的数据。可能还有我们尚未发现的配方，但如果没有其他配方，这些就是升到 300 唯一可用的配方。",
  ["10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 Thorium Bar, 20 Star Ruby"] = "10x {s:16730:inv_pants_04:Imperial Plate Leggings} - 440 瑟银锭，20 星辰红宝石",
  ["You get the recipe from the {q:7658::Imperial Plate Leggings} quest, it needs 60 Thorium Bar."] = "配方来自 {q:7658::Imperial Plate Leggings} 任务，需要 60 块瑟银锭。",
  ["This WoW Forever Enchanting leveling guide will show you the fastest and cheapest way to level your Enchanting skill from 1 to 300. You will also find every trainer location and where to train Enchanting past 75, 150 and 225."] = "这份 WoW Forever 附魔升级指南将告诉你把附魔技能从 1 升到 300 的最快、最省钱的方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习附魔。",
  ["Enchanting goes well with Tailoring because you don't need a gathering profession for either of them, and you can disenchant the items you made with Tailoring. Below you will find the shopping list, the Enchanting trainers by starting zone and capital city, and the cheapest enchants for every skill range. Forever added a few new low level recipes, so the first 70 points are cheaper than in Classic."] = "附魔和裁缝很搭，因为两者都不需要采集专业，而且你可以分解用裁缝做出的物品。下面是购物清单、按新手区和主城列出的附魔训练师，以及每个技能区间最便宜的附魔。Forever 新增了几个低级配方，所以前 70 点比经典版更便宜。",
  ["An alternative replaces the whole row, so buy the one that is cheaper."] = "替代方案会替换整行内容，所以买更便宜的那个。",
  ["Enchanting Trainer Locations"] = "附魔训练师位置",
  ["Apprentice Enchanting has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中学习学徒级附魔没有等级要求，所以新建的角色也能学。",
  ["Orgrimmar: {n:0:horde:Jhag}"] = "奥格瑞玛：{n:0:horde:Jhag}",
  ["Undercity: {n:0:horde:Malcomb Wynn}"] = "幽暗城：{n:0:horde:Malcomb Wynn}",
  ["Thunder Bluff: {n:0:horde:Mot Dawnstrider}"] = "雷霆崖：{n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Pa'zula} in Sen'jin Village"] = "森金村的 {n:0:horde:Pa'zula}",
  ["There is no Enchanting trainer in Mulgore, go to {n:0:horde:Mot Dawnstrider} on the middle rise in Thunder Bluff"] = "莫高雷没有附魔训练师，请前往雷霆崖中层平台的 {n:0:horde:Mot Dawnstrider}",
  ["{n:0:horde:Vance Undergloom} upstairs in the inn in Brill"] = "布瑞尔旅店楼上的 {n:0:horde:Vance Undergloom}",
  ["{n:0::Eaysaa Brightgust} in Valanaar, {n:0::Nasalanna Windsinger} in Shen'dar Village"] = "Valanaar 的 {n:0::Eaysaa Brightgust}，Shen'dar Village 的 {n:0::Nasalanna Windsinger}",
  ["Stormwind City: {n:0:alliance:Betty Quin}"] = "暴风城：{n:0:alliance:Betty Quin}",
  ["Ironforge: {n:0:alliance:Thonys Pillarstone}"] = "铁炉堡：{n:0:alliance:Thonys Pillarstone}",
  ["Darnassus: {n:0:alliance:Lalina Summermoon}"] = "达纳苏斯：{n:0:alliance:Lalina Summermoon}",
  ["There is no Enchanting trainer in Elwynn Forest, go to {n:0:alliance:Betty Quin} in the Mage Quarter in Stormwind City"] = "艾尔文森林没有附魔训练师，请前往暴风城法师区的 {n:0:alliance:Betty Quin}",
  ["There is no Enchanting trainer in Dun Morogh, go to {n:0:alliance:Thonys Pillarstone} at the Great Forge in Ironforge"] = "丹莫罗没有附魔训练师，请前往铁炉堡大熔炉的 {n:0:alliance:Thonys Pillarstone}",
  ["{n:0:alliance:Alanna Raveneye} at the Oracle Glade, in the north-west of Teldrassil"] = "泰达希尔西北部神谕林地的 {n:0:alliance:Alanna Raveneye}",
  ["You can find every Enchanting trainer for Horde and Alliance on my WoW Forever Enchanting Trainers page."] = "你可以在我的 WoW Forever 附魔训练师页面找到部落和联盟的所有附魔训练师。",
  ["Enchanting Macro for Faster Leveling"] = "加快升级的附魔宏",
  ["I highly recommend using this macro to speed up the leveling process."] = "我强烈推荐使用这个宏来加快升级速度。",
  ["This macro presses the Create button for you and confirms the prompt that asks if you want to replace the enchant already on the item, without any extra clicks."] = "这个宏会替你点击“制造”按钮，并确认询问是否替换物品上已有附魔的提示框，无需额外点击。",
  ["Macro"] = "宏",
  ["If you have never made a macro, type /m in the chat and press Enter, click New, give it a name and paste these two lines into it."] = "如果你从没做过宏，在聊天框输入 /m 并按回车，点击“新建”，起个名字，然后把这两行粘贴进去。",
  ["How to Use"] = "使用方法",
  ["Place the macro on your action bar"] = "把宏放到你的动作条上",
  ["Open your Enchanting profession window"] = "打开附魔专业窗口",
  ["Select the enchant you want to craft (make sure it's the right one)"] = "选择你要制作的附魔（确保选对了）",
  ["Put the item you want to enchant into the optional target slot"] = "把要附魔的物品放进可选目标栏位",
  ["Press the macro repeatedly"] = "反复按这个宏",
  ["Disenchanting"] = "分解",
  ["You get {s:13262:inv_enchant_disenchant:Disenchant} together with Apprentice Enchanting. In WoW Forever {b}Disenchant is not in your spellbook{/b}, it's in the Enchanting box of the Professions window."] = "学会学徒级附魔时会同时获得 {s:13262:inv_enchant_disenchant:Disenchant}。在 WoW Forever 中，{b}分解不在你的法术书里{/b}，而是在专业窗口的附魔框中。",
  ["If you are looking for the disenchanting table, it's in my disenchanting guide, and if you can't find the Disenchant button, the guide shows it with pictures:"] = "如果你在找分解对照表，它在我的分解指南里；如果你找不到分解按钮，该指南也有图片说明：",
  ["Apprentice Enchanting (1-70)"] = "学徒附魔 (1-70)",
  ["1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 Copper Rod, 1 Mote of Magic"] = "1x {s:7421:inv_staff_goldfeathered_01:Runed Copper Rod} - 1 铜棒，1 Mote of Magic",
  ["The {i:6217:inv_misc_flute_01:Copper Rod} and the {i:247786:inv_elemental_mote_mana:Mote of Magic} are sold by the Enchanting Supply vendor near your trainer, don't buy them from the Auction House."] = "{i:6217:inv_misc_flute_01:Copper Rod} 和 {i:247786:inv_elemental_mote_mana:Mote of Magic} 由你训练师附近的附魔供应商出售，不要在拍卖行买。",
  ["{b}If you are leveling in a starting zone with a low level character{/b}, you can buy the Copper Rod from a trade vendor there, but the Mote of Magic is only sold by Enchanting vendors. In the starting zones only the trainers on {b}Zephras Isle{/b} and in {b}Tirisfal Glades{/b} (Brill) sell it, everyone else has to visit the trainer in the capital city, the vendor stands right next to them."] = "{b}如果你是用低级角色在新手区升级{/b}，可以在当地的商业供应商处买到铜棒，但 Mote of Magic 只有附魔商人出售。新手区中只有 {b}Zephras Isle{/b} 和 {b}提瑞斯法林地{/b}（布瑞尔）的训练师旁有卖，其他人都得去主城的训练师那里，商人就站在训练师旁边。",
  ["Make one of these:"] = "以下任选其一：",
  ["50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 Strange Dust"] = "50x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 50 奇异之尘",
  ["50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 Lesser Magic Essence"] = "50x {s:7428:spell_holy_greaterheal:Enchant Bracer - Minor Deflect} - 50 次级魔法精华",
  ["A {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} turns into 3 Lesser Magic Essence when you right-click it in your bags, so you can buy those too."] = "在背包里右键点击 {i:10939:inv_enchant_essencemagiclarge:Greater Magic Essence} 会变成 3 个次级魔法精华，所以你也可以买这个。",
  ["Journeyman Enchanting (70-150)"] = "熟练附魔 (70-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Enchanting. You need {b}Enchanting 50{/b} and {b}level 10{/b}:"] = "要突破 75，请拜访以下训练师之一学习熟练附魔。你需要 {b}附魔 50{/b} 和 {b}10 级{/b}：",
  ["Orgrimmar: {n:0:horde:Godan}"] = "奥格瑞玛：{n:0:horde:Godan}",
  ["Undercity: {n:0:horde:Lavinia Crowe}"] = "幽暗城：{n:0:horde:Lavinia Crowe}",
  ["Thunder Bluff: {n:0:horde:Teg Dawnstrider}"] = "雷霆崖：{n:0:horde:Teg Dawnstrider}",
  ["Stormwind City: {n:0:alliance:Lucan Cordell}"] = "暴风城：{n:0:alliance:Lucan Cordell}",
  ["Ironforge: {n:0:alliance:Gimble Thistlefuzz}"] = "铁炉堡：{n:0:alliance:Gimble Thistlefuzz}",
  ["Darnassus: {n:0:alliance:Taladan}"] = "达纳苏斯：{n:0:alliance:Taladan}",
  ["If you bought Strange Dust pick the {b}Strange Dust{/b} tab, if you bought Lesser Magic Essence pick the {b}Lesser Magic Essence{/b} tab."] = "如果你买的是奇异之尘，选择 {b}奇异之尘{/b} 标签页；如果你买的是次级魔法精华，选择 {b}次级魔法精华{/b} 标签页。",
  ["Strange Dust"] = "奇异之尘",
  ["Lesser Magic Essence"] = "次级魔法精华",
  ["49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 Lesser Magic Essence"] = "49x {s:7426:spell_holy_greaterheal:Enchant Chest - Minor Absorption} - 49 次级魔法精华",
  ["1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 Silver Rod, 3 Strange Dust, 4 Lesser Magic Essence, 1 Shadowgem"] = "1x {s:7795:inv_staff_01:Runed Silver Rod} - 1 银棒，3 奇异之尘，4 次级魔法精华，1 暗影宝石",
  ["{i:6338:inv_staff_01:Silver Rod} and every other rod in this guide (Golden, Truesilver, Arcanite) is made by Blacksmiths, you can buy them from the Auction House."] = "{i:6338:inv_staff_01:Silver Rod} 以及本指南中的其他所有棒子（金棒、真银棒、奥金棒）都由铁匠制作，你可以从拍卖行购买。",
  ["23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 Simple Wood, 46 Lesser Magic Essence"] = "23x {s:14807:inv_staff_07:Greater Magic Wand} - 23 简易木材，46 次级魔法精华",
  ["37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 Lesser Magic Essence"] = "37x {s:7793:spell_holy_greaterheal:Enchant 2H Weapon - Lesser Intellect} - 148 次级魔法精华",
  ["{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} is sold by these vendors:"] = "{i:6349:inv_misc_note_01:Formula: Enchant 2H Weapon - Lesser Intellect} 由以下商人出售：",
  ["{n:0:horde:Kithas} in Orgrimmar"] = "奥格瑞玛的 {n:0:horde:Kithas}",
  ["{n:0:horde:Nata Dawnstrider} in Thunder Bluff"] = "雷霆崖的 {n:0:horde:Nata Dawnstrider}",
  ["{n:0:horde:Leo Sarn} in Silverpine Forest"] = "银松森林的 {n:0:horde:Leo Sarn}",
  ["{n:0:alliance:Tilli Thistlefuzz} in Ironforge"] = "铁炉堡的 {n:0:alliance:Tilli Thistlefuzz}",
  ["Buy {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} and {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need them at 150 and 200."] = "顺便也在他们那里买 {i:20752:inv_misc_note_01:Formula: Minor Mana Oil} 和 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}，150 和 200 时会用到。",
  ["If you don't want to get the formula, make this:"] = "如果你不想买这个公式，就做这个：",
  ["25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 Strange Dust"] = "25x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 100 奇异之尘",
  ["23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 Strange Dust"] = "23x {s:7420:spell_holy_greaterheal:Enchant Chest - Inferior Stamina} - 23 奇异之尘",
  ["15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 Strange Dust"] = "15x {s:7457:spell_holy_greaterheal:Enchant Bracer - Minor Stamina} - 30 奇异之尘",
  ["9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 Strange Dust"] = "9x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 18 奇异之尘",
  ["32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 Strange Dust"] = "32x {s:7771:spell_holy_greaterheal:Enchant Cloak - Minor Protection} - 64 奇异之尘",
  ["20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 Strange Dust"] = "20x {s:7863:spell_holy_greaterheal:Enchant Boots - Minor Stamina} - 80 奇异之尘",
  ["If 20 Soul Dust cost less than 80 Strange Dust, make this:"] = "如果 20 个灵魂之尘比 80 个奇异之尘便宜，就做这个：",
  ["20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 Soul Dust."] = "20x {s:13501:spell_holy_greaterheal:Enchant Bracer - Lesser Stamina} - 20 灵魂之尘。",
  ["Expert Enchanting (150-225)"] = "专家附魔 (150-225)",
  ["To train past 150, visit one of these trainers and learn Expert Enchanting. You need {b}Enchanting 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要突破 150，请拜访以下训练师之一学习专家附魔。你需要 {b}附魔 125{/b} 和 {b}20 级{/b}，费用为 50 银币。",
  ["There is only one Expert Enchanting trainer for each faction. {n:0:horde:Hgarth} in Stonetalon Mountains at Sun Rock Retreat is the Horde trainer, he is up on the hill above the village. {n:0:alliance:Kitta Firewind} in Elwynn Forest is the Alliance trainer, she is at the top of the Tower of Azora."] = "每个阵营只有一位专家附魔训练师。部落训练师是石爪山脉烈日石居的 {n:0:horde:Hgarth}，他在村子上方的山丘上。联盟训练师是艾尔文森林的 {n:0:alliance:Kitta Firewind}，她在阿祖拉之塔的顶层。",
  ["1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 Golden Rod, 1 Iridescent Pearl, 1 Greater Astral Essence, 1 Soul Dust"] = "1x {s:13628:inv_staff_10:Runed Golden Rod} - 1 金棒，1 彩色珍珠，1 强效星界精华，1 灵魂之尘",
  ["16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 Soul Dust, 32 Maple Seed, 16 Leaded Vial"] = "16x {s:25125:inv_potion_98:Minor Mana Oil} - 16 灵魂之尘，32 枫树种子，16 铅瓶",
  ["{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} is sold by these vendors:"] = "{i:20752:inv_misc_note_01:Formula: Minor Mana Oil} 由以下商人出售：",
  ["{n:0:horde:Thaddeus Webb} in Undercity"] = "幽暗城的 {n:0:horde:Thaddeus Webb}",
  ["{n:0:alliance:Vaean} in Darnassus"] = "达纳苏斯的 {n:0:alliance:Vaean}",
  ["{n:0:alliance:Jessara Cordell} in Stormwind City"] = "暴风城的 {n:0:alliance:Jessara Cordell}",
  ["Buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} from them too, you will need it at 200."] = "顺便也在他们那里买 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}，200 时会用到。",
  ["{i:17034:inv_misc_food_02:Maple Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17034:inv_misc_food_02:Maple Seed} 由材料商出售，{i:3372:inv_potion_85:Leaded Vial} 由炼金供应商出售。",
  ["47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 Soul Dust"] = "47x {s:13637:spell_holy_greaterheal:Enchant Boots - Lesser Agility} - 47 灵魂之尘",
  ["If 2 Vision Dust cost less than 3 Soul Dust, stop the boots at 185 and make this until 200:"] = "如果 2 个幻象之尘比 3 个灵魂之尘便宜，就在 185 停止做靴子，改做这个直到 200：",
  ["15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 Vision Dust."] = "15x {s:13661:spell_holy_greaterheal:Enchant Bracer - Strength} - 15 幻象之尘。",
  ["1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 Truesilver Rod, 1 Black Pearl, 1 Greater Mystic Essence, 1 Vision Dust"] = "1x {s:13702:inv_staff_11:Runed Truesilver Rod} - 1 真银棒，1 黑珍珠，1 强效秘法精华，1 幻象之尘",
  ["25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 Vision Dust, 50 Stranglethorn Seed, 25 Leaded Vial"] = "25x {s:25126:inv_potion_103:Lesser Wizard Oil} - 25 幻象之尘，50 荆棘谷种子，25 铅瓶",
  ["If you didn't buy {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil} yet, the vendors are listed at the 151-165 step above."] = "如果你还没买 {i:20753:inv_misc_note_01:Formula: Lesser Wizard Oil}，出售它的商人已在上面 151-165 的步骤中列出。",
  ["{i:17035:inv_misc_food_02:Stranglethorn Seed} is sold by Reagent vendors and {i:3372:inv_potion_85:Leaded Vial} by Alchemy Supply vendors."] = "{i:17035:inv_misc_food_02:Stranglethorn Seed} 由材料商出售，{i:3372:inv_potion_85:Leaded Vial} 由炼金供应商出售。",
  ["5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 Vision Dust"] = "5x {s:13746:spell_holy_greaterheal:Enchant Cloak - Greater Defense} - 5 幻象之尘",
  ["Artisan Enchanting (225-300)"] = "大师附魔 (225-300)",
  ["The Expert Enchanting trainers only teach you up to 225. To train Enchanting past 225 you need {b}level 35{/b} and {b}Enchanting 200{/b}, then learn Artisan Enchanting from Annora in Uldaman (I explain below how to find her). {b}She is the only trainer who teaches Artisan Enchanting.{/b}"] = "专家附魔训练师只能教你到 225。要把附魔练到 225 以上，你需要 {b}35 级{/b} 和 {b}附魔 200{/b}，然后去奥达曼找 Annora 学习大师附魔（下面会说明如何找到她）。{b}她是唯一教授大师附魔的训练师。{/b}",
  ["There are a few recipes only Annora teaches, {b}so bring enough gold to learn every recipe and enough materials to reach Enchanting 250{/b}, otherwise you have to go back to Uldaman for the higher recipes. Around 50 {i:11137:inv_enchant_dustvision:Vision Dust} gets you to 250."] = "有些配方只有 Annora 会教，{b}所以请带够金币学会所有配方，并带够把附魔练到 250 的材料{/b}，否则你还得再回奥达曼学更高级的配方。大约 50 个 {i:11137:inv_enchant_dustvision:Vision Dust} 就能让你升到 250。",
  ["How to enter Uldaman"] = "如何进入奥达曼",
  ["Uldaman is in the Badlands and it has two entrances, use the back entrance. You can't solo it at level 35, so go with a party or ask a level 60 to help."] = "奥达曼位于荒芜之地，有两个入口，请走后门入口。35 级时无法单刷，所以请组队或找一位 60 级玩家帮忙。",
  ["How to find Annora"] = "如何找到 Annora",
  ["Annora only spawns once you {b}kill every mob in the area she is in!{/b}"] = "只有在你{b}杀光她所在区域的所有怪物{/b}后，Annora 才会出现！",
  ["{b}Don't forget to learn everything from Annora before you leave Uldaman!{/b} The recipes from 230 up are taught nowhere else."] = "{b}离开奥达曼之前，别忘了向 Annora 学会所有东西！{/b}230 以上的配方在其他地方都学不到。",
  ["Recipe"] = "配方",
  ["Skill"] = "技能",
  ["Cost"] = "费用",
  ["{b}Artisan Enchanting{/b}"] = "{b}大师附魔{/b}",
  ["37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 Vision Dust"] = "37x {s:13815:spell_holy_greaterheal:Enchant Gloves - Agility} - 37 幻象之尘",
  ["20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 Dream Dust, 20 Purple Lotus, 20 Crystal Vial"] = "20x {s:25127:inv_potion_99:Lesser Mana Oil} - 20 梦境之尘，20 紫莲花，20 水晶瓶",
  ["{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} is sold by {n:0::Kania} in Silithus, she is upstairs in the inn. {i:8925:inv_potion_86:Crystal Vial} is sold by {n:0::Mishta} in Silithus or any Alchemy Supply vendor."] = "{i:20754:inv_misc_note_01:Formula: Lesser Mana Oil} 由希利苏斯的 {n:0::Kania} 出售，她在旅店楼上。{i:8925:inv_potion_86:Crystal Vial} 由希利苏斯的 {n:0::Mishta} 或任意炼金供应商出售。",
  ["If you don't have Purple Lotus, make {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength} instead (1 Dream Dust, 2 Lesser Nether Essence each), Annora teaches it."] = "如果你没有紫莲花，就改做 {s:13939:spell_holy_greaterheal:Enchant Bracer - Greater Strength}（每个需要 1 梦境之尘、2 次级虚空精华），Annora 会教这个。",
  ["40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 Dream Dust"] = "40x {s:20017:spell_holy_greaterheal:Enchant Shield - Greater Stamina} - 240 梦境之尘",
  ["{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} is sold by {n:0:horde:Daniel Bartlett} in Undercity and {n:0:alliance:Mythrin'dir} in Darnassus. It's bind on pickup, so don't buy it on an alt."] = "{i:16217:inv_misc_note_01:Formula: Enchant Shield - Greater Stamina} 由幽暗城的 {n:0:horde:Daniel Bartlett} 和达纳苏斯的 {n:0:alliance:Mythrin'dir} 出售。它是拾取后绑定的，所以不要用小号购买。",
  ["From 290 you can make the Runed Arcanite Rod, see the next step."] = "从 290 开始你可以制作符文奥金棒，见下一步。",
  ["1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 Arcanite Rod, 1 Golden Pearl, 10 Illusion Dust, 4 Greater Eternal Essence, 4 Small Brilliant Shard, 2 Large Brilliant Shard"] = "1x {s:20051:inv_wand_09:Runed Arcanite Rod} - 1 奥金棒，1 金珍珠，10 幻影之尘，4 强效不灭精华，4 小块光辉碎片，2 大块光辉碎片",
  ["{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} is sold by {n:0::Lorelae Wintersong} in Moonglade at Nighthaven."] = "{i:16243:inv_misc_note_01:Formula: Runed Arcanite Rod} 由月光林地永夜港的 {n:0::Lorelae Wintersong} 出售。",
  ["{b}You need this rod for some recipes from 290 and for most recipes at 300{/b}, Crusader for example. You can make it from 290, but if you don't need it yet, you can make it later and make one more Shield for the last point instead."] = "{b}290 以后的部分配方和 300 的大多数配方都需要这根棒子{/b}，例如十字军。你从 290 起就能做它，但如果暂时用不上，可以以后再做，最后一点改为多做一个盾牌附魔。",
  ["This WoW Forever Engineering leveling guide will show you the fastest and cheapest way to level your Engineering skill from 1 to 300. You will also find every trainer location and where to train Engineering past 75, 150 and 225."] = "这份 WoW Forever 工程学升级指南将告诉你把工程学技能从 1 升到 300 的最快、最省钱的方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习工程学。",
  ["Engineering is best combined with Mining, because almost everything you make needs stone and bars, and you can mine both. If you don't have Mining, you have to buy everything from the Auction House. Below you will find the shopping list, the Engineering trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "工程学最好搭配采矿，因为你做的几乎所有东西都需要石头和金属锭，而这两样你都能自己挖。如果你没有采矿，就只能全部从拍卖行购买。下面是购物清单、按新手区和主城列出的工程学训练师，以及每个技能区间最便宜的配方。",
  ["Engineering Trainer Locations"] = "工程学训练师位置",
  ["Apprentice Engineering has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中学习学徒级工程学没有等级要求，所以新建的角色也能学。",
  ["There is no Engineering trainer in Thunder Bluff and Darnassus, the other four capitals have one. You can also ask a guard, then it will be marked with a red flag on your map."] = "雷霆崖和达纳苏斯没有工程学训练师，其他四座主城都有。你也可以询问卫兵，训练师的位置会以红旗标记在你的地图上。",
  ["Orgrimmar: {n:0:horde:Thund}"] = "奥格瑞玛：{n:0:horde:Thund}",
  ["Undercity: {n:0:horde:Graham Van Talen}"] = "幽暗城：{n:0:horde:Graham Van Talen}",
  ["{n:0:horde:Mukdrak} in Razor Hill, near the forge next to the road to Orgrimmar"] = "剃刀岭的 {n:0:horde:Mukdrak}，在通往奥格瑞玛的路旁熔炉附近",
  ["{n:0::Twizwick Sprocketgrind} on the plateau above the Venture Co. Mine, hard to reach at low level. There is no anvil near him and nobody there sells the Blacksmith Hammer, so it's probably best to go to {n:0:horde:Thund} in Orgrimmar instead."] = "风险投资公司矿洞上方高地上的 {n:0::Twizwick Sprocketgrind}，低等级时很难到达。他附近没有铁砧，那里也没有人卖铁匠锤，所以最好还是去奥格瑞玛找 {n:0:horde:Thund}。",
  ["There is no Engineering trainer in Tirisfal Glades, go to {n:0:horde:Graham Van Talen} in the Rogues' Quarter in Undercity"] = "提瑞斯法林地没有工程学训练师，请前往幽暗城盗贼区的 {n:0:horde:Graham Van Talen}",
  ["{n:0::Strange Hermit} in Shadowgale Forest"] = "Shadowgale Forest 的 {n:0::Strange Hermit}",
  ["Stormwind City: {n:0:alliance:Sprite Jumpsprocket}"] = "暴风城：{n:0:alliance:Sprite Jumpsprocket}",
  ["Ironforge: {n:0:alliance:Jemma Quikswitch}"] = "铁炉堡：{n:0:alliance:Jemma Quikswitch}",
  ["There is no Engineering trainer in Elwynn Forest, go to {n:0:alliance:Sprite Jumpsprocket} in the Dwarven District in Stormwind City"] = "艾尔文森林没有工程学训练师，请前往暴风城矮人区的 {n:0:alliance:Sprite Jumpsprocket}",
  ["{n:0:alliance:Bronk Guzzlegear} at Steelgrill's Depot"] = "钢架补给站的 {n:0:alliance:Bronk Guzzlegear}",
  ["There is no Engineering trainer in Teldrassil or Darnassus, the closest one is {n:0:alliance:Jenna Lemkenilli} in Auberdine in Darkshore"] = "泰达希尔和达纳苏斯都没有工程学训练师，最近的是黑海岸奥伯丁的 {n:0:alliance:Jenna Lemkenilli}",
  ["You can find every Engineering trainer for Horde and Alliance on my WoW Forever Engineering Trainers page."] = "你可以在我的 WoW Forever 工程学训练师页面找到部落和联盟的所有工程学训练师。",
  ["Apprentice Engineering (1-50)"] = "学徒工程学 (1-50)",
  ["Buy a {i:5956:inv_hammer_20:Blacksmith Hammer}, most recipes need it. {b}Most trainers{/b} have a Blacksmithing or Engineering Supply vendor nearby that sells it, {b}except{/b} the trainers in Dun Morogh and on Zephras Isle. In Dun Morogh buy it in Kharanos from {n:0:alliance:Thrawn Boltar}, on Zephras Isle in Shen'dar Village from {n:0::Aedi Thriceforged}."] = "买一把 {i:5956:inv_hammer_20:Blacksmith Hammer}，大多数配方都需要它。{b}大多数训练师{/b}附近都有出售它的锻造或工程学供应商，{b}除了{/b}丹莫罗和 Zephras Isle 的训练师。在丹莫罗请到卡拉诺斯的 {n:0:alliance:Thrawn Boltar} 处购买，在 Zephras Isle 请到 Shen'dar Village 的 {n:0::Aedi Thriceforged} 处购买。",
  ["The {b}Gnome{/b} racial changed in Forever. Instead of +15 Engineering skill, Engineering Specialization now makes your devices fail or backfire 20% less often, so Gnomes level Engineering exactly like everyone else."] = "Forever 中{b}侏儒{/b}的种族天赋改变了。工程学专精不再提供 +15 工程学技能，而是让你的装置失灵或反噬的几率降低 20%，所以侏儒练工程学和其他人完全一样。",
  ["66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 Rough Stone"] = "66x {s:3918:inv_misc_dust_01:Rough Blasting Powder} - 66 劣质石头",
  ["Keep all of them, you need 66 for the bombs at 51."] = "全部留着，51 制作炸弹时需要 66 份。",
  ["33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 Copper Bar"] = "33x {s:3922:inv_misc_gear_06:Handful of Copper Bolts} - 33 铜锭",
  ["Keep these too, you will need all 33 for the bombs."] = "这些也留着，制作炸弹时 33 个全部要用。",
  ["1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 Copper Bar"] = "1x {s:7430:inv_misc_wrench_01:Arclight Spanner} - 6 铜锭",
  ["You will use this to craft Engineering recipes, so keep it."] = "制作工程学配方时要用到它，所以留着。",
  ["Journeyman Engineering (50-150)"] = "熟练工程学 (50-150)",
  ["To train past 75, visit one of these trainers and learn Journeyman Engineering. You need {b}Engineering 50{/b} and {b}level 10{/b}:"] = "要突破 75，请拜访以下训练师之一学习熟练工程学。你需要 {b}工程学 50{/b} 和 {b}10 级{/b}：",
  ["Orgrimmar: {n:0:horde:Nogg}"] = "奥格瑞玛：{n:0:horde:Nogg}",
  ["Undercity: {n:0:horde:Franklin Lloyd}"] = "幽暗城：{n:0:horde:Franklin Lloyd}",
  ["Stormwind City: {n:0:alliance:Lilliam Sparkspindle}"] = "暴风城：{n:0:alliance:Lilliam Sparkspindle}",
  ["Ironforge: {n:0:alliance:Trixie Quikswitch}"] = "铁炉堡：{n:0:alliance:Trixie Quikswitch}",
  ["Duskwood: {n:0:alliance:Finbus Geargrind}"] = "暮色森林：{n:0:alliance:Finbus Geargrind}",
  ["33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 Copper Bar, 33 Handful of Copper Bolts, 66 Rough Blasting Powder, 33 Linen Cloth"] = "33x {s:3923:inv_misc_bomb_09:Rough Copper Bomb} - 33 铜锭，33 一捆铜螺栓，66 劣质火药，33 亚麻布",
  ["{b}It's possible that you reach further than 75 with these{/b}, so it's best not to afk craft them unless you already learned Journeyman Engineering. Either make sure you learn it first, or just don't afk craft them. (Depends on luck, sometimes you don't even reach 75.)"] = "{b}做这些有可能超过 75{/b}，所以除非你已经学会熟练工程学，否则最好不要挂机制作。要么先确保学会，要么就别挂机做。（看运气，有时甚至到不了 75。）",
  ["60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 Coarse Stone"] = "60x {s:3929:inv_misc_dust_02:Coarse Blasting Powder} - 60 粗糙的石头",
  ["Keep them, you will need all 60 for the dynamite at 90."] = "留着它们，90 制作炸药时 60 份全部要用。",
  ["20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 Coarse Blasting Powder, 20 Linen Cloth"] = "20x {s:3931:inv_misc_bomb_06:Coarse Dynamite} - 60 粗制火药，20 亚麻布",
  ["5x {s:3973:inv_ingot_04:Silver Contact} - 5 Silver Bar"] = "5x {s:3973:inv_ingot_04:Silver Contact} - 5 银锭",
  ["If Silver Bar is expensive, make this instead:"] = "如果银锭很贵，就改做这个：",
  ["5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 Light Leather, 10 Tigerseye."] = "5x {s:3934:inv_helmet_47:Flying Tiger Goggles} - 30 轻皮，10 虎眼石。",
  ["25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 Bronze Bar, 25 Weak Flux"] = "25x {s:3938:inv_gizmo_pipe_01:Bronze Tube} - 50 青铜锭，25 弱效助熔剂",
  ["Keep 10 of them, you will need them at 125."] = "留下 10 个，125 时会用到。",
  ["{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} is sold by Engineering Supply vendors near your trainer."] = "{i:2880:inv_misc_ammo_gunpowder_02:Weak Flux} 由你训练师附近的工程学供应商出售。",
  ["If you end up a few points short of 125, don't make more tubes, just start the scopes."] = "如果离 125 还差几点，不要再做青铜管了，直接开始做瞄准镜。",
  ["10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 Bronze Tube, 10 Moss Agate"] = "10x {s:3978:inv_misc_spyglass_02:Standard Scope} - 10 青铜管，10 苔藓玛瑙",
  ["Start making {s:3945:inv_misc_dust_06:Heavy Blasting Powder} instead if you don't have any Moss Agate, or it's really expensive."] = "如果你没有苔藓玛瑙或者它非常贵，就改为开始制作 {s:3945:inv_misc_dust_06:Heavy Blasting Powder}。",
  ["Make both of these:"] = "以下两样都要做：",
  ["30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 Heavy Stone"] = "30x {s:3945:inv_misc_dust_06:Heavy Blasting Powder} - 30 沉重的石头",
  ["15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 Bronze Bar, 15 Wool Cloth"] = "15x {s:3942:inv_gizmo_02:Whirring Bronze Gizmo} - 30 青铜锭，15 毛料",
  ["{b}Make sure to make them in the same order.{/b} You need both for the sheep at 160, so make them now and you should reach 150 with them."] = "{b}一定要按照同样的顺序制作。{/b}160 制作绵羊时两样都要用，所以现在就做，做完应该能到 150。",
  ["Expert Engineering (150-200)"] = "专家工程学 (150-200)",
  ["To train past 150, visit {n:0:horde:Roxxik} in Orgrimmar (Horde) or {n:0:alliance:Springspindle Fizzlegear} in Ironforge (Alliance) and learn Expert Engineering. You need {b}Engineering 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要突破 150，请拜访奥格瑞玛的 {n:0:horde:Roxxik}（部落）或铁炉堡的 {n:0:alliance:Springspindle Fizzlegear}（联盟）学习专家工程学。你需要 {b}工程学 125{/b} 和 {b}20 级{/b}，费用为 50 银币。",
  ["15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 Bronze Bar, 15 Medium Leather, 15 Wool Cloth"] = "15x {s:3953:inv_gizmo_bronzeframework_01:Bronze Framework} - 30 青铜锭，15 中皮，15 毛料",
  ["Keep these too, you will need all 15 for the sheep."] = "这些也留着，制作绵羊时 15 个全部要用。",
  ["The 15 will probably take you past 160, that's fine."] = "做完 15 个大概会超过 160，没关系。",
  ["15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 Heavy Blasting Powder, 15 Whirring Bronze Gizmo, 15 Bronze Framework, 30 Wool Cloth"] = "15x {s:3955:spell_nature_polymorph:Explosive Sheep} - 30 重火药，15 嗡鸣的青铜零件，15 青铜框架，30 毛料",
  ["Keep 5 of them, you might need them if you choose Goblin Engineering at 200."] = "留下 5 个，如果你在 200 选择地精工程学可能会用到。",
  ["60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 Solid Stone"] = "60x {s:12585:inv_misc_powder_black:Solid Blasting Powder} - 120 坚固的石头",
  ["Save these, you will need them later."] = "留着这些，之后会用到。",
  ["1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 Steel Bar"] = "1x {s:12590:inv_misc_screwdriver_02:Gyromatic Micro-Adjustor} - 4 钢锭",
  ["Keep this, you will need it to craft some of the Engineering recipes."] = "留着它，制作部分工程学配方时需要用到。",
  ["If you were unlucky with the skill points and didn't reach 195, craft a few {s:3962:inv_misc_bomb_08:Iron Grenade} or any other recipe that gives skill points."] = "如果你技能点运气不好，没到 195，就做几个 {s:3962:inv_misc_bomb_08:Iron Grenade} 或其他任何能加技能点的配方。",
  ["6x {s:12589:inv_musket_01:Mithril Tube} - 18 Mithril Bar"] = "6x {s:12589:inv_musket_01:Mithril Tube} - 18 秘银锭",
  ["Keep all 6, you might need them if you choose Gnomish Engineering at 200."] = "6 个全部留着，如果你在 200 选择侏儒工程学可能会用到。",
  ["Engineering Specializations"] = "工程学专精",
  ["At {b}Engineering 200{/b} and {b}level 30{/b}, you can specialize in Gnomish or Goblin Engineering. Some items require a specific specialization to use, while other items are crafted by one specialization but are usable by any engineer. Fortunately, most recipes that are crafted by one specialization can be used by both."] = "在 {b}工程学 200{/b} 和 {b}30 级{/b} 时，你可以选择专精侏儒工程学或地精工程学。有些物品需要特定专精才能使用，另一些物品由某一专精制作但任何工程师都能使用。好在大多数由某一专精制作的物品两种专精都能用。",
  ["For information on how to choose a specialization, please see my separate guide:"] = "关于如何选择专精，请参阅我的单独指南：",
  ["Artisan Engineering (200-300)"] = "大师工程学 (200-300)",
  ["To train Engineering past 225 you need {b}Engineering 200{/b} and {b}level 35{/b}, then learn Artisan Engineering from {n:0::Buzzek Bracketswing} in Tanaris at Gadgetzan, he is right outside the inn near the mailbox. He also teaches the recipes above 200, so go there as soon as you reach 200."] = "要把工程学练到 225 以上，你需要 {b}工程学 200{/b} 和 {b}35 级{/b}，然后去塔纳利斯加基森找 {n:0::Buzzek Bracketswing} 学习大师工程学，他就在旅店外的邮箱旁边。他也教 200 以上的配方，所以一到 200 就去找他。",
  ["20x {s:12591:inv_battery_01:Unstable Trigger} - 20 Mithril Bar, 20 Mageweave Cloth, 20 Solid Blasting Powder"] = "20x {s:12591:inv_battery_01:Unstable Trigger} - 20 秘银锭，20 魔纹布，20 坚固火药",
  ["Keep them, you will need all 20 for the bombs at 238."] = "留着它们，238 制作炸弹时 20 个全部要用。",
  ["40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 Mithril Bar"] = "40x {s:12599:inv_gizmo_mithrilcasing_01:Mithril Casing} - 120 秘银锭",
  ["Keep these too, you will need 40 for the bombs."] = "这些也留着，制作炸弹需要 40 个。",
  ["20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 Mithril Casing, 20 Unstable Trigger, 40 Solid Blasting Powder"] = "20x {s:12619:inv_misc_bomb_07:Hi-Explosive Bomb} - 40 秘银外壳，20 不稳定的触发器，40 坚固火药",
  ["44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 Dense Stone"] = "44x {s:19788:inv_misc_ammo_gunpowder_01:Dense Blasting Powder} - 88 致密的石头",
  ["35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 Thorium Bar, 35 Runecloth"] = "35x {s:19791:inv_gizmo_04:Thorium Widget} - 105 瑟银锭，35 符文布",
  ["{i:16042:inv_scroll_03:Schematic: Thorium Widget} is sold by {n:0:horde:Sovik} in Orgrimmar and {n:0:alliance:Gearcutter Cogspinner} in Ironforge."] = "{i:16042:inv_scroll_03:Schematic: Thorium Widget} 由奥格瑞玛的 {n:0:horde:Sovik} 和铁炉堡的 {n:0:alliance:Gearcutter Cogspinner} 出售。",
  ["20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 Thorium Bar"] = "20x {s:19795:inv_gizmo_pipe_04:Thorium Tube} - 120 瑟银锭",
  ["{i:16047:inv_scroll_03:Schematic: Thorium Tube} is sold by {n:0::Xizzer Fizzbolt} in Winterspring at Everlook, in the first building on the right after the gate. It's bind on pickup in Forever, so buy it with the character that levels Engineering."] = "{i:16047:inv_scroll_03:Schematic: Thorium Tube} 由冬泉谷永望镇的 {n:0::Xizzer Fizzbolt} 出售，他在进门后右手边的第一栋建筑里。在 Forever 中它是拾取后绑定的，所以请用练工程学的角色购买。",
  ["This WoW Forever Leatherworking leveling guide will show you the fastest and cheapest way to level your Leatherworking skill from 1 to 300. You will also find every trainer location and where to train Leatherworking past 75, 150 and 225."] = "这份 WoW Forever 制皮升级指南将告诉你把制皮技能从 1 升到 300 的最快、最省钱的方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习制皮。",
  ["Below you will find the full shopping list, the Leatherworking trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Leatherworking is best combined with Skinning because leather is most of the cost, but you can also buy everything in the guide from the Auction House."] = "下面是完整的购物清单、按新手区和主城列出的制皮训练师，以及从学徒到大师每个技能区间最便宜的配方。制皮最好搭配剥皮，因为皮革占了大部分成本，不过指南中的所有材料你也可以从拍卖行购买。",
  ["When a recipe is yellow or green, a craft doesn't always give you a skill point, so nobody can tell exactly how many materials you will need. That's why the counts that depend a lot on luck are a range. {b}With the bigger number 9 out of 10 players have enough, with the smaller one it's 50/50.{/b} If you buy the smaller number, be ready to buy more later."] = "配方为黄色或绿色时，制作并不一定能获得技能点，所以没人能准确说出你需要多少材料。因此，那些很看运气的数量给出的是一个范围。{b}按较大的数字，10 个玩家中有 9 个够用；按较小的数字，则是一半一半。{/b}如果你按较小的数字购买，请做好之后补买的准备。",
  ["Material"] = "材料",
  ["Leatherworking Trainer Locations"] = "制皮训练师位置",
  ["Apprentice Leatherworking has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中学习学徒级制皮没有等级要求，所以新建的角色也能学。",
  ["Orgrimmar: {n:0:horde:Kamari}"] = "奥格瑞玛：{n:0:horde:Kamari}",
  ["Undercity: {n:0:horde:Dan Golthas}"] = "幽暗城：{n:0:horde:Dan Golthas}",
  ["Thunder Bluff: {n:0:horde:Mak}"] = "雷霆崖：{n:0:horde:Mak}",
  ["There is no Leatherworking trainer in Durotar, go to {n:0:horde:Kamari} in the Drag in Orgrimmar"] = "杜隆塔尔没有制皮训练师，请前往奥格瑞玛暗巷区的 {n:0:horde:Kamari}",
  ["{n:0:horde:Chaw Stronghide} in Bloodhoof Village"] = "血蹄村的 {n:0:horde:Chaw Stronghide}",
  ["{n:0:horde:Shelene Rhobart} at the road junction southeast of Brill"] = "布瑞尔东南方岔路口的 {n:0:horde:Shelene Rhobart}",
  ["{n:0::Emerii Tallgust} in Valanaar, {n:0::Indari Sunseam} in Shen'dar Village"] = "Valanaar 的 {n:0::Emerii Tallgust}，Shen'dar Village 的 {n:0::Indari Sunseam}",
  ["Stormwind City: {n:0:alliance:Randal Worth}"] = "暴风城：{n:0:alliance:Randal Worth}",
  ["Ironforge: {n:0:alliance:Gretta Finespindle}"] = "铁炉堡：{n:0:alliance:Gretta Finespindle}",
  ["Darnassus: {n:0:alliance:Darianna}"] = "达纳苏斯：{n:0:alliance:Darianna}",
  ["{n:0:alliance:Adele Fielder} in the small house by Crystal Lake, northeast of Goldshire"] = "闪金镇东北方水晶湖边小屋里的 {n:0:alliance:Adele Fielder}",
  ["There is no Leatherworking trainer in Dun Morogh, go to {n:0:alliance:Gretta Finespindle} at the Great Forge in Ironforge"] = "丹莫罗没有制皮训练师，请前往铁炉堡大熔炉的 {n:0:alliance:Gretta Finespindle}",
  ["{n:0:alliance:Nadyia Maneweaver} in the small house near the road to Darnassus"] = "通往达纳苏斯的路旁小屋里的 {n:0:alliance:Nadyia Maneweaver}",
  ["You can find every Leatherworking trainer for Horde and Alliance on my WoW Forever Leatherworking Trainers page."] = "你可以在我的 WoW Forever 制皮训练师页面找到部落和联盟的所有制皮训练师。",
  ["Apprentice Leatherworking (1-55)"] = "学徒制皮 (1-55)",
  ["35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 Ruined Leather Scraps"] = "35x {s:2881:inv_misc_leatherscrap_03:Light Leather} - 105 破烂的皮革碎片",
  ["27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 Light Hide, 27 Salt"] = "27x {s:3816:inv_misc_pelt_wolf_01:Cured Light Hide} - 27 轻毛皮，27 盐",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Leatherworking Supply vendor nearby that sells the threads, dyes, and salt, {b}except{/b} the trainers in Elwynn Forest and Tirisfal Glades. For those, buy the Salt and Coarse Thread in Goldshire from {n:0:alliance:Tharynn Bouden} or in Brill from {n:0:horde:Abigail Shiel}."] = "{b}注意：{/b}{b}大多数训练师{/b}附近都有出售线、染料和盐的制皮供应商，{b}除了{/b}艾尔文森林和提瑞斯法林地的训练师。这两处请到闪金镇的 {n:0:alliance:Tharynn Bouden} 或布瑞尔的 {n:0:horde:Abigail Shiel} 处购买盐和粗线。",
  ["Keep 24 of the hides, you will need them for the Light Leather Pants at 100."] = "留下 24 张毛皮，100 制作轻皮护腿时会用到。",
  ["Alternative recipes"] = "替代配方",
  ["If you farm your own leather and don't have 27 Light Hides, make Light Armor Kits until 45, then Embossed Leather Gloves until 55:"] = "如果你自己剥皮获取皮革，而且没有 27 张轻毛皮，就先做轻型护甲片到 45，再做压花皮手套到 55：",
  ["24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 Light Leather"] = "24x {s:2152:inv_misc_armorkit_17:Light Armor Kit} - 24 轻皮",
  ["10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 Light Leather, 20 Coarse Thread"] = "10x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 30 轻皮，20 粗线",
  ["You still need 24 Cured Light Hide for the Light Leather Pants at 100, so keep the Light Hides you skin until then."] = "100 制作轻皮护腿时你仍然需要 24 张熟化轻毛皮，所以在那之前把剥下的轻毛皮都留着。",
  ["Journeyman Leatherworking (55-130)"] = "熟练制皮 (55-130)",
  ["To train past 75, visit one of these trainers and learn Journeyman Leatherworking. You need {b}Leatherworking 50{/b} and {b}level 10{/b}:"] = "要突破 75，请拜访以下训练师之一学习熟练制皮。你需要 {b}制皮 50{/b} 和 {b}10 级{/b}：",
  ["Orgrimmar: {n:0:horde:Karolek}"] = "奥格瑞玛：{n:0:horde:Karolek}",
  ["Undercity: {n:0:horde:Arthur Moore}"] = "幽暗城：{n:0:horde:Arthur Moore}",
  ["Thunder Bluff: {n:0:horde:Tarn}"] = "雷霆崖：{n:0:horde:Tarn}",
  ["Stormwind City: {n:0:alliance:Simon Tanner}"] = "暴风城：{n:0:alliance:Simon Tanner}",
  ["Ironforge: {n:0:alliance:Fimble Finespindle}"] = "铁炉堡：{n:0:alliance:Fimble Finespindle}",
  ["Darnassus: {n:0:alliance:Faldron}"] = "达纳苏斯：{n:0:alliance:Faldron}",
  ["21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 Light Leather, 42 Coarse Thread"] = "21x {s:3756:inv_gauntlets_05:Embossed Leather Gloves} - 63 轻皮，42 粗线",
  ["8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 Light Leather"] = "8x {s:20648:inv_misc_leatherscrap_05:Medium Leather} - 32 轻皮",
  ["10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 Medium Hide, 10 Salt"] = "10x {s:3817:inv_misc_pelt_bear_02:Cured Medium Hide} - 10 中毛皮，10 盐",
  ["Keep the Cured Medium Hides, you will need them for the Dark Leather Belts at 115."] = "留着熟化中毛皮，115 制作黑皮腰带时会用到。",
  ["19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 Light Leather, 38 Coarse Thread"] = "19x {s:3763:inv_belt_04:Fine Leather Belt} - 114 轻皮，38 粗线",
  ["Keep 10 of the belts for the Dark Leather Belts at 115."] = "留下 10 条腰带，用于 115 制作黑皮腰带。",
  ["24x {s:9068:inv_pants_02:Light Leather Pants} - 240 Light Leather, 24 Cured Light Hide, 24 Fine Thread"] = "24x {s:9068:inv_pants_02:Light Leather Pants} - 240 轻皮，24 熟化轻毛皮，24 细线",
  ["10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 Fine Leather Belt, 10 Cured Medium Hide, 20 Fine Thread, 10 Gray Dye"] = "10x {s:3766:inv_belt_03:Dark Leather Belt} - 10 精制皮腰带，10 熟化中毛皮，20 细线，10 灰色染料",
  ["7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 Medium Leather"] = "7x {s:20649:inv_misc_leatherscrap_07:Heavy Leather} - 35 中皮",
  ["Expert Leatherworking (130-205)"] = "专家制皮 (130-205)",
  ["To train past 150, visit {n:0:horde:Una} in Thunder Bluff (Horde) or {n:0:alliance:Telonis} in Darnassus (Alliance) and learn Expert Leatherworking. You need {b}Leatherworking 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要突破 150，请拜访雷霆崖的 {n:0:horde:Una}（部落）或达纳苏斯的 {n:0:alliance:Telonis}（联盟）学习专家制皮。你需要 {b}制皮 125{/b} 和 {b}20 级{/b}，费用为 50 银币。",
  ["30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 Heavy Hide, 90 Salt"] = "30x {s:3818:inv_misc_pelt_wolf_02:Cured Heavy Hide} - 30 重毛皮，90 盐",
  ["Keep the Cured Heavy Hides, you will need 10 for the Barbaric Shoulders at 155 and 20 for the Guardian Gloves at 165."] = "留着熟化重毛皮，155 制作野蛮护肩需要 10 张，165 制作守护手套需要 20 张。",
  ["17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 Medium Leather, 68 Fine Thread"] = "17x {s:3764:inv_gauntlets_05:Hillman's Leather Gloves} - 238 中皮，68 细线",
  ["10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 Heavy Leather, 10 Cured Heavy Hide, 20 Fine Thread"] = "10x {s:7151:inv_shoulder_08:Barbaric Shoulders} - 80 重皮，10 熟化重毛皮，20 细线",
  ["20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 Heavy Leather, 20 Cured Heavy Hide, 20 Silken Thread"] = "20x {s:7156:inv_gauntlets_05:Guardian Gloves} - 80 重皮，20 熟化重毛皮，20 丝线",
  ["22x {s:10507:inv_belt_24:Nightscape Headband} - 110 Thick Leather, 44 Silken Thread"] = "22x {s:10507:inv_belt_24:Nightscape Headband} - 110 厚皮，44 丝线",
  ["Leatherworking Specializations"] = "制皮专精",
  ["Once you reach {b}Leatherworking 225{/b} and {b}level 40{/b}, you can choose one of the three Leatherworking specializations: Dragonscale, Elemental, or Tribal. Each specialization gives access to a specific set of patterns."] = "达到 {b}制皮 225{/b} 和 {b}40 级{/b} 后，你可以从三种制皮专精中选择一种：龙鳞、元素或部族。每种专精都能学到一套专属图样。",
  ["Dragonscale - Mail-type gear"] = "龙鳞 - 锁甲装备",
  ["Elemental - elemental resistance and Leather-type agility gear"] = "元素 - 元素抗性及皮甲敏捷装备",
  ["Tribal - Leather-type intellect & agility gear and the Devilsaur Armor set"] = "部族 - 皮甲智力和敏捷装备，以及魔暴龙护甲套装",
  ["For information on how to become a Dragonscale, Elemental, or Tribal Leatherworker, please see my separate guides:"] = "关于如何成为龙鳞、元素或部族制皮师，请参阅我的单独指南：",
  ["Artisan Leatherworking (205-300)"] = "大师制皮 (205-300)",
  ["To train past 225, visit {n:0:horde:Hahrana Ironhide} in Camp Mojache, Feralas (Horde) or {n:0:alliance:Drakk Stonehand} in Aerie Peak, The Hinterlands (Alliance) and learn Artisan Leatherworking. You need {b}Leatherworking 200{/b} and {b}level 35{/b}."] = "要突破 225，请拜访菲拉斯莫沙彻营地的 {n:0:horde:Hahrana Ironhide}（部落）或辛特兰鹰巢山的 {n:0:alliance:Drakk Stonehand}（联盟）学习大师制皮。你需要 {b}制皮 200{/b} 和 {b}35 级{/b}。",
  ["36x {s:10548:inv_pants_11:Nightscape Pants} - 504 Thick Leather, 144 Silken Thread"] = "36x {s:10548:inv_pants_11:Nightscape Pants} - 504 厚皮，144 丝线",
  ["{b}The Expert trainers in Thunder Bluff and Darnassus don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}雷霆崖和达纳苏斯的专家训练师不教这个配方{/b}，你只能从上面两位训练师那里学到。",
  ["I recommend these over the Nightscape Boots because they sell for more to a vendor, so they end up cheaper."] = "我推荐做这个而不是夜色长靴，因为它卖给商人的价格更高，所以最终更便宜。",
  ["36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 Rugged Leather, 36 Black Dye, 36 Rune Thread"] = "36x {s:19049:inv_gauntlets_31:Wicked Leather Gauntlets} - 288 硬甲皮，36 黑色染料，36 符文线",
  ["The pattern is sold by {n:0:horde:Werg Thickblade} in Tirisfal Glades (Horde) and {n:0:alliance:Leonard Porter} in Western Plaguelands (Alliance)."] = "图样由提瑞斯法林地的 {n:0:horde:Werg Thickblade}（部落）和西瘟疫之地的 {n:0:alliance:Leonard Porter}（联盟）出售。",
  ["Blue Suede Shoes use the same leather but sell for more to a vendor, so they save you about 13 gold on this step. If the pattern costs less than that on the Auction House, make these instead:"] = "Blue Suede Shoes 使用同样的皮革，但卖给商人的价格更高，所以这一步能帮你省大约 13 金币。如果拍卖行上的图样比这便宜，就改做这个：",
  ["36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 Rugged Leather, 36 Blue Dye, 36 Rune Thread."] = "36x {s:1255048:inv_boots_leather_12:Blue Suede Shoes} - 288 硬甲皮，36 蓝色染料，36 符文线。",
  ["53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 Rugged Leather, 530 Runecloth, 53 Rune Thread"] = "53x {s:19082:inv_misc_bandage_11:Runic Leather Headband} - 742 硬甲皮，530 符文布，53 符文线",
  ["The pattern is sold by {n:0::Jase Farlane} at Light's Hope Chapel in Eastern Plaguelands."] = "图样由东瘟疫之地圣光之愿礼拜堂的 {n:0::Jase Farlane} 出售。",
  ["If you have the pattern, make these from 275 instead:"] = "如果你有图样，就从 275 开始改做这个：",
  ["27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 Rugged Leather, 27 Blue Dye, 27 Rune Thread."] = "27x {s:1255019:inv_bracer_22a:Blue Suede Bracers} - 270 硬甲皮，27 蓝色染料，27 符文线。",
  ["{b}Someone with Leatherworking 300 has to place the Sewing Machine for you.{/b} You can't place a Sewing Machine yourself before 300, even if you buy one. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}需要一位制皮 300 的玩家帮你放置缝纫机。{/b}即使你买了缝纫机，在 300 之前也无法自己放置。我不确定这是不是暴雪的疏忽，所以之后可能会有改动。",
  ["If you can use one and have the pattern, you can make these from 280:"] = "如果你能用上缝纫机并且有图样，可以从 280 开始做这个：",
  ["20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 Rugged Leather, 80 Blue Dye, 20 Rune Thread."] = "20x {s:1255017:inv_helm_armor_buckledhat_b_01_blue:Blue Suede Hat} - 320 硬甲皮，80 蓝色染料，20 符文线。",
  ["This WoW Forever Tailoring leveling guide will show you the fastest and cheapest way to level your Tailoring skill from 1 to 300. You will also find every trainer location and where to train Tailoring past 75, 150 and 225."] = "这份 WoW Forever 裁缝升级指南将告诉你把裁缝技能从 1 升到 300 的最快、最省钱的方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习裁缝。",
  ["Below you will find the full shopping list, the Tailoring trainers by starting zone and capital city, and the cheapest recipes for every skill range from Apprentice to Artisan. Tailoring uses cloth as its main material, but cloth drops from humanoids, so you don't need a gathering profession and you can combine Tailoring with anything. Enchanting is a popular choice because you can disenchant the things you make while leveling and use the dust to level Enchanting."] = "下面是完整的购物清单、按新手区和主城列出的裁缝训练师，以及从学徒到大师每个技能区间最便宜的配方。裁缝以布料为主要材料，而布料由人型怪物掉落，所以你不需要采集专业，可以和任何专业搭配。附魔是很受欢迎的选择，因为你可以分解升级时做出的物品，再用尘来练附魔。",
  ["{b}NOTE:{/b} {b}Most trainers{/b} have a Tailoring Supply vendor nearby that sells the threads and dyes, {b}except{/b} the trainer in Tirisfal Glades. For that one, buy the Coarse Thread in Brill from {n:0:horde:Abigail Shiel}."] = "{b}注意：{/b}{b}大多数训练师{/b}附近都有出售线和染料的裁缝供应商，{b}除了{/b}提瑞斯法林地的训练师。在那里请到布瑞尔的 {n:0:horde:Abigail Shiel} 处购买粗线。",
  ["Alternative (if cheaper)"] = "替代方案（如果更便宜）",
  ["This list is not final yet, but the skill ranges come from the game data, so it should be pretty close. The 280-300 part is not included here yet."] = "这份清单还不是最终版，但技能区间来自游戏数据，所以应该相当接近。280-300 的部分暂未包含在内。",
  ["Tailoring Trainer Locations"] = "裁缝训练师位置",
  ["Apprentice Tailoring has no level requirement in Forever, so you can learn it on a fresh character."] = "在 Forever 中学习学徒级裁缝没有等级要求，所以新建的角色也能学。",
  ["Orgrimmar: {n:0:horde:Snang}"] = "奥格瑞玛：{n:0:horde:Snang}",
  ["Undercity: {n:0:horde:Victor Ward}"] = "幽暗城：{n:0:horde:Victor Ward}",
  ["Thunder Bluff: {n:0:horde:Vhan}"] = "雷霆崖：{n:0:horde:Vhan}",
  ["There is no Tailoring trainer in Durotar, go to {n:0:horde:Snang} in the Drag in Orgrimmar"] = "杜隆塔尔没有裁缝训练师，请前往奥格瑞玛暗巷区的 {n:0:horde:Snang}",
  ["There is no Tailoring trainer in Mulgore, go to {n:0:horde:Vhan} on the middle rise in Thunder Bluff"] = "莫高雷没有裁缝训练师，请前往雷霆崖中层平台的 {n:0:horde:Vhan}",
  ["{n:0:horde:Bowen Brisboise} in the small house at Cold Hearth Manor, southwest of Brill"] = "布瑞尔西南方寒心庄园小屋里的 {n:0:horde:Bowen Brisboise}",
  ["{n:0::Othesia Evengale} in Valanaar, {n:0::Taleen Shimmerthread} in Shen'dar Village"] = "Valanaar 的 {n:0::Othesia Evengale}，Shen'dar Village 的 {n:0::Taleen Shimmerthread}",
  ["Stormwind City: {n:0:alliance:Lawrence Schneider}"] = "暴风城：{n:0:alliance:Lawrence Schneider}",
  ["Ironforge: {n:0:alliance:Uthrar Threx}"] = "铁炉堡：{n:0:alliance:Uthrar Threx}",
  ["Darnassus: {n:0:alliance:Trianna}"] = "达纳苏斯：{n:0:alliance:Trianna}",
  ["{n:0:alliance:Eldrin} in a house at the Eastvale Logging Camp"] = "东谷伐木场一栋房子里的 {n:0:alliance:Eldrin}",
  ["There is no Tailoring trainer in Dun Morogh, go to {n:0:alliance:Uthrar Threx} at the Great Forge in Ironforge"] = "丹莫罗没有裁缝训练师，请前往铁炉堡大熔炉的 {n:0:alliance:Uthrar Threx}",
  ["There is no Tailoring trainer in Teldrassil, go to {n:0:alliance:Trianna} at the Craftsmen's Terrace in Darnassus"] = "泰达希尔没有裁缝训练师，请前往达纳苏斯工匠区的 {n:0:alliance:Trianna}",
  ["You can find every Tailoring trainer for Horde and Alliance on my WoW Forever Tailoring Trainers page."] = "你可以在我的 WoW Forever 裁缝训练师页面找到部落和联盟的所有裁缝训练师。",
  ["Apprentice Tailoring (1-55)"] = "学徒裁缝 (1-55)",
  ["30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 Linen Cloth"] = "30x {s:2963:inv_fabric_linen_02:Bolt of Linen Cloth} - 60 亚麻布",
  ["Keep the bolts, you need all of them for the belts."] = "留着布卷，制作腰带时全部要用。",
  ["28x {s:8776:inv_belt_05:Linen Belt} - 28 Bolt of Linen Cloth, 28 Coarse Thread"] = "28x {s:8776:inv_belt_05:Linen Belt} - 28 亚麻布卷，28 粗线",
  ["Journeyman Tailoring (55-140)"] = "熟练裁缝 (55-140)",
  ["To train past 75, visit one of these trainers and learn Journeyman Tailoring. You need {b}Tailoring 50{/b} and {b}level 10{/b}:"] = "要突破 75，请拜访以下训练师之一学习熟练裁缝。你需要 {b}裁缝 50{/b} 和 {b}10 级{/b}：",
  ["Orgrimmar: {n:0:horde:Magar}"] = "奥格瑞玛：{n:0:horde:Magar}",
  ["Undercity: {n:0:horde:Rhiannon Davis}"] = "幽暗城：{n:0:horde:Rhiannon Davis}",
  ["Thunder Bluff: {n:0:horde:Tepa}"] = "雷霆崖：{n:0:horde:Tepa}",
  ["Stormwind City: {n:0:alliance:Sellandus}"] = "暴风城：{n:0:alliance:Sellandus}",
  ["Ironforge: {n:0:alliance:Jormund Stonebrow}"] = "铁炉堡：{n:0:alliance:Jormund Stonebrow}",
  ["Darnassus: {n:0:alliance:Me'lynn}"] = "达纳苏斯：{n:0:alliance:Me'lynn}",
  ["{b}Learn Journeyman Tailoring before you make these.{/b} You can reach past 75 with them, but you won't get any skill points above 75 until you learn it, so don't go AFK while crafting before you have it."] = "{b}做这些之前先学会熟练裁缝。{/b}做这些可以超过 75，但在学会之前，75 以上不会获得任何技能点，所以学会之前制作时不要挂机。",
  ["45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 Wool Cloth"] = "45x {s:2964:inv_fabric_wool_03:Bolt of Woolen Cloth} - 135 毛料",
  ["Keep the bolts, you will need them later. In total you will need 153 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth} (459 {i:2592:inv_fabric_wool_01:Wool Cloth}) until 140, so you can also make all of them now."] = "留着布卷，之后会用到。到 140 为止你总共需要 153 个 {i:2997:inv_fabric_wool_03:Bolt of Woolen Cloth}（459 个 {i:2592:inv_fabric_wool_01:Wool Cloth}），所以你也可以现在一次全部做好。",
  ["22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 Bolt of Woolen Cloth, 22 Fine Thread"] = "22x {s:2402:inv_misc_cape_10:Woolen Cape} - 22 毛料卷，22 细线",
  ["If the bolts already took you past 80, just make capes until 95."] = "如果做布卷已经让你超过 80，就一直做披风到 95。",
  ["5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 Bolt of Woolen Cloth, 10 Fine Thread"] = "5x {s:3848:inv_shoulder_06:Double-stitched Woolen Shoulders} - 15 毛料卷，10 细线",
  ["54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 Silk Cloth"] = "54x {s:3839:inv_fabric_silk_03:Bolt of Silk Cloth} - 216 丝绸",
  ["Keep the bolts, you will need them later. In total you will need 184 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth} (736 {i:4306:inv_fabric_silk_01:Silk Cloth}) until 190, so you can also make all of them now."] = "留着布卷，之后会用到。到 190 为止你总共需要 184 个 {i:4305:inv_fabric_silk_03:Bolt of Silk Cloth}（736 个 {i:4306:inv_fabric_silk_01:Silk Cloth}），所以你也可以现在一次全部做好。",
  ["29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 Bolt of Woolen Cloth, 87 Fine Thread, 29 Elixir of Wisdom"] = "29x {s:3852:inv_gauntlets_05:Gloves of Meditation} - 116 毛料卷，87 细线，29 智慧药剂",
  ["You can buy {i:3383:inv_potion_06:Elixir of Wisdom} from the Auction House or ask an Alchemist."] = "你可以从拍卖行购买 {i:3383:inv_potion_06:Elixir of Wisdom}，或者找炼金师帮忙。",
  ["Expert Tailoring (140-200)"] = "专家裁缝 (140-200)",
  ["To train past 150, visit {n:0:horde:Josef Gregorian} in Undercity (Horde) or {n:0:alliance:Georgio Bolero} in Stormwind City (Alliance) and learn Expert Tailoring. You need {b}Tailoring 125{/b} and {b}level 20{/b}, and it costs 50 silver."] = "要突破 150，请拜访幽暗城的 {n:0:horde:Josef Gregorian}（部落）或暴风城的 {n:0:alliance:Georgio Bolero}（联盟）学习专家裁缝。你需要 {b}裁缝 125{/b} 和 {b}20 级{/b}，费用为 50 银币。",
  ["23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 Mageweave Cloth"] = "23x {s:3865:inv_fabric_mageweave_03:Bolt of Mageweave} - 115 魔纹布",
  ["Keep the bolts, you will need them later. In total you will need 157 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave} (785 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}) until 225, so you can also make all of them now."] = "留着布卷，之后会用到。到 225 为止你总共需要 157 个 {i:4339:inv_fabric_mageweave_03:Bolt of Mageweave}（785 个 {i:4338:inv_fabric_mageweave_01:Mageweave Cloth}），所以你也可以现在一次全部做好。",
  ["20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 Bolt of Silk Cloth, 40 Red Dye, 40 Fine Thread"] = "20x {s:8791:inv_shirt_04:Crimson Silk Vest} - 80 丝绸卷，40 红色染料，40 细线",
  ["26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 Bolt of Silk Cloth, 52 Red Dye, 52 Silken Thread"] = "26x {s:8799:inv_pants_06:Crimson Silk Pantaloons} - 104 丝绸卷，52 红色染料，52 丝线",
  ["19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 Bolt of Mageweave, 57 Silken Thread"] = "19x {s:12049:inv_pants_09:Black Mageweave Leggings} - 38 魔纹布卷，57 丝线",
  ["Artisan Tailoring (200-300)"] = "大师裁缝 (200-300)",
  ["To train past 225, visit {n:0:horde:Daryl Stack} in Tarren Mill, Hillsbrad Foothills (Horde) or {n:0:alliance:Timothy Worthington} in Theramore Isle, Dustwallow Marsh (Alliance) and learn Artisan Tailoring. You need {b}Tailoring 200{/b} and {b}level 35{/b}."] = "要突破 225，请拜访希尔斯布莱德丘陵塔伦米尔的 {n:0:horde:Daryl Stack}（部落）或尘泥沼泽塞拉摩岛的 {n:0:alliance:Timothy Worthington}（联盟）学习大师裁缝。你需要 {b}裁缝 200{/b} 和 {b}35 级{/b}。",
  ["5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 Bolt of Mageweave, 10 Heavy Silken Thread"] = "5x {s:12074:inv_shoulder_25:Black Mageweave Shoulders} - 15 魔纹布卷，10 粗丝线",
  ["{b}The Expert trainers in Undercity and Stormwind don't teach this recipe{/b}, you can only learn it from the two trainers above."] = "{b}幽暗城和暴风城的专家训练师不教这个配方{/b}，你只能从上面两位训练师那里学到。",
  ["23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 Runecloth"] = "23x {s:18401:inv_fabric_purplefire_02:Bolt of Runecloth} - 115 符文布",
  ["Keep the bolts, you will need them later. In total you will need 311 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth} (1555 {i:14047:inv_fabric_purplefire_01:Runecloth}) until 280, so you can also make all of them now."] = "留着布卷，之后会用到。到 280 为止你总共需要 311 个 {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}（1555 个 {i:14047:inv_fabric_purplefire_01:Runecloth}），所以你也可以现在一次全部做好。",
  ["26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 Bolt of Mageweave, 52 Silken Thread"] = "26x {s:12065:inv_misc_bag_10_black:Mageweave Bag} - 104 魔纹布卷，52 丝线",
  ["I recommend the bags right now simply because they are more useful. You can use them yourself, sell some, give them to friends or use them in your bank."] = "现阶段我推荐做包，单纯因为它们更实用。你可以自己用、卖掉一些、送给朋友，或者放进银行使用。",
  ["If you don't need the bags and don't want to sell them, make these instead."] = "如果你不需要这些包也不想卖，就改做这个。",
  ["10x {s:18402:inv_belt_15:Runecloth Belt} - 30 Bolt of Runecloth, 10 Rune Thread."] = "10x {s:18402:inv_belt_15:Runecloth Belt} - 30 符文布卷，10 符文线。",
  ["24x {s:18402:inv_belt_15:Runecloth Belt} - 72 Bolt of Runecloth, 24 Rune Thread"] = "24x {s:18402:inv_belt_15:Runecloth Belt} - 72 符文布卷，24 符文线",
  ["11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 Bolt of Runecloth, 44 Rugged Leather, 11 Rune Thread"] = "11x {s:18417:inv_gauntlets_25:Runecloth Gloves} - 44 符文布卷，44 硬甲皮，11 符文线",
  ["The pattern is sold by {n:0::Qia} in Winterspring."] = "图样由冬泉谷的 {n:0::Qia} 出售。",
  ["39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 Bolt of Runecloth, 39 Ironweb Spider Silk, 39 Rune Thread"] = "39x {s:1257487:inv_bracer_13:Runecloth Cuffs} - 195 符文布卷，39 铁网蛛丝，39 符文线",
  ["The pattern is sold by {n:0::Pexmit} in Mount Hyjal. It's bind on pickup, so buy it with the character that levels Tailoring."] = "图样由海加尔山的 {n:0::Pexmit} 出售。它是拾取后绑定的，所以请用练裁缝的角色购买。",
  ["Horde players can also get it as the reward for {q:95769::Threading a Solution}, a quest from {n:265788::Kal'tinzan} in Elderwild, Mount Hyjal. It needs level 54 and 6 Bolt of Runecloth. It's probably a Tailoring quest, but I don't know yet what skill it needs."] = "部落玩家也可以通过 {q:95769::Threading a Solution} 任务的奖励获得它，该任务由海加尔山 Elderwild 的 {n:265788::Kal'tinzan} 发布。任务需要 54 级和 6 个符文布卷。它可能是个裁缝任务，但我还不知道需要多少技能。",
  ["Make the {s:18449:inv_shoulder_21:Runecloth Shoulders} if you can get the pattern. These are all the recipes I found so far that still give points after 280. I left out the ones that aren't worth it for leveling, and there might be new ones that nobody has found yet."] = "如果你能拿到图样，就做 {s:18449:inv_shoulder_21:Runecloth Shoulders}。这些是我目前找到的 280 以后仍能加点的全部配方。我略去了那些不值得用来升级的配方，而且可能还有没人发现的新配方。",
  ["Range"] = "区间",
  ["Materials"] = "材料",
  ["Pattern"] = "图样",
  ["World drop, on the Auction House"] = "世界掉落，可在拍卖行购买",
  ["Rare, grab it if you see it on the Auction House"] = "稀有，在拍卖行看到就赶紧买",
  ["You can get a few more points with these, but they stop giving skill points before 300, so you can't reach 300 with them:"] = "做这些还能多拿几点，但它们在 300 之前就不再加技能点了，所以无法靠它们升到 300：",
  ["{n:0::Pexmit} in Mount Hyjal"] = "海加尔山的 {n:0::Pexmit}",
  ["Recipes that need a Loom"] = "需要织布机的配方",
  ["{b}These recipes need a Loom, and you can only make a Loom at Tailoring 300.{/b} They could be used for leveling, but for now you would need a camp where another tailor already placed a Loom. I'm not sure if this is an oversight by Blizzard, so they might change it."] = "{b}这些配方需要织布机，而织布机只能在裁缝 300 时制作。{/b}它们本可以用来升级，但目前你需要找一个已有其他裁缝放置了织布机的营地。我不确定这是不是暴雪的疏忽，所以之后可能会有改动。",
  ["These are the Cenarion Circle patterns from {n:0::Mishta} in Silithus:"] = "以下是希利苏斯 {n:0::Mishta} 出售的塞纳里奥议会图样：",
  ["Requires"] = "需求",
  ["5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} or {s:1297120:inv_gauntlets_18:Venomspew Gloves}"] = "5x {s:1297123:inv_gauntlets_17:Swarmtender's Gloves} 或 {s:1297120:inv_gauntlets_18:Venomspew Gloves}",
  ["20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "20x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}，5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}，15x {i:7080:spell_nature_acid_01:Essence of Water} 或 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Friendly"] = "塞纳里奥议会 友善",
  ["5x {s:1297124:inv_belt_03:Swarmtender's Cord} or {s:1297121:inv_belt_25:Venomspew Cord}"] = "5x {s:1297124:inv_belt_03:Swarmtender's Cord} 或 {s:1297121:inv_belt_25:Venomspew Cord}",
  ["30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 15x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "30x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}，5x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}，15x {i:7080:spell_nature_acid_01:Essence of Water} 或 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["Cenarion Circle Honored"] = "塞纳里奥议会 尊敬",
  ["18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} or {s:1297122:inv_boots_cloth_04:Venomspew Footpads}"] = "18x {s:1297125:inv_boots_cloth_01:Swarmtender's Footpads} 或 {s:1297122:inv_boots_cloth_04:Venomspew Footpads}",
  ["90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}, 18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}, 54x {i:7080:spell_nature_acid_01:Essence of Water} or {i:7082:spell_nature_earthbind:Essence of Air}"] = "90x {i:14048:inv_fabric_purplefire_02:Bolt of Runecloth}，18x {i:14343:inv_enchant_shardbrilliantsmall:Small Brilliant Shard}，54x {i:7080:spell_nature_acid_01:Essence of Water} 或 {i:7082:spell_nature_earthbind:Essence of Air}",
  ["This WoW Forever Mining leveling guide will show you the fastest way to level Mining from 1 to 300. You will also find every trainer location and where to train Mining past 75, 150 and 225."] = "这份 WoW Forever 采矿升级指南将告诉你把采矿从 1 升到 300 的最快方法。你还能找到所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习采矿。",
  ["Below you will find the Mining trainers by starting zone and capital city, and the best zones to mine in for every skill range. Mining serves two professions, Blacksmithing and Engineering, so it's really good combined with these two. Check out my Forever Blacksmithing leveling guide or my Forever Engineering leveling guide if you want to level one of them."] = "下面是按新手区和主城列出的采矿训练师，以及每个技能区间最适合采矿的区域。采矿为锻造和工程学两个专业提供材料，所以和它们搭配非常好。如果你想练其中之一，可以看看我的 Forever 锻造升级指南或 Forever 工程学升级指南。",
  ["WoW Forever added a couple of new ores, bars and recipes. You can check them out here:"] = "WoW Forever 新增了几种矿石、金属锭和配方。你可以在这里查看：",
  ["Mining Trainer Locations"] = "采矿训练师位置",
  ["Every capital city except Darnassus has a Mining trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "除达纳苏斯外，每座主城都有采矿训练师。你也可以询问卫兵，训练师的位置会以红旗标记在你的地图上。",
  ["{b}Capital cities:{/b}"] = "{b}主城：{/b}",
  ["Orgrimmar: {n:0:horde:Makaru}"] = "奥格瑞玛：{n:0:horde:Makaru}",
  ["Undercity: {n:0:horde:Brom Killian}"] = "幽暗城：{n:0:horde:Brom Killian}",
  ["Thunder Bluff: {n:0:horde:Brek Stonehoof}"] = "雷霆崖：{n:0:horde:Brek Stonehoof}",
  ["{b}Starting zones:{/b}"] = "{b}新手区：{/b}",
  ["{n:0:horde:Norzsh} in the Valley of Trials (only up to 75) {n:0:horde:Krunn} in Razor Hill"] = "试炼谷的 {n:0:horde:Norzsh}（最高只到 75） 剃刀岭的 {n:0:horde:Krunn}",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache (only up to 75) {n:0:horde:Brek Stonehoof} in Thunder Bluff"] = "纳拉其营地的 {n:0:horde:Vartha Rockmane}（最高只到 75） 雷霆崖的 {n:0:horde:Brek Stonehoof}",
  ["{n:0:horde:Walter Mason} in Deathknell (only up to 75) {n:0:horde:Brom Killian} in Undercity"] = "丧钟镇的 {n:0:horde:Walter Mason}（最高只到 75） 幽暗城的 {n:0:horde:Brom Killian}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining. The trainers on the island are {n:0::Halavuul Cragwind} in Valanaar and {n:0::Messana Crestwind} in Shen'dar Village."] = "你出生的 Thendal Village 没有训练师，但你也不需要。{q:93552::Harvesting Windstones} 是你在 Thendal Village 最早接到的任务之一。奖励选择 {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies}，它会教你采矿。岛上的训练师是 Valanaar 的 {n:0::Halavuul Cragwind} 和 Shen'dar Village 的 {n:0::Messana Crestwind}。",
  ["Stormwind City: {n:0:alliance:Gelman Stonehand}"] = "暴风城：{n:0:alliance:Gelman Stonehand}",
  ["Ironforge: {n:0:alliance:Geofram Bouldertoe}"] = "铁炉堡：{n:0:alliance:Geofram Bouldertoe}",
  ["Darnassus: no trainer, the closest one is {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "达纳苏斯：没有训练师，最近的是黑海岸奥伯丁的 {n:0:alliance:Kurdram Stonehammer}",
  ["{n:0:alliance:Kelsey Fargo} (only up to 75) {n:0:alliance:Gelman Stonehand} in Stormwind City"] = "{n:0:alliance:Kelsey Fargo}（最高只到 75） 暴风城的 {n:0:alliance:Gelman Stonehand}",
  ["{n:0:alliance:Sally Swiftwrench} (only up to 75) {n:0:alliance:Yarr Hammerstone} at Steelgrill's Depot {n:0:alliance:Dank Drizzlecut} at Gol'Bolar Quarry"] = "{n:0:alliance:Sally Swiftwrench}（最高只到 75） 钢架补给站的 {n:0:alliance:Yarr Hammerstone} 古博拉采掘场的 {n:0:alliance:Dank Drizzlecut}",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Kurdram Stonehammer} in Auberdine, Darkshore"] = "幽影谷奥达希尔的 {n:0:alliance:Fanorran Stilloak}（最高只到 75） 黑海岸奥伯丁的 {n:0:alliance:Kurdram Stonehammer}",
  ["You can find every Mining trainer for Horde and Alliance on my WoW Forever Mining Trainers page."] = "你可以在我的 WoW Forever 采矿训练师页面找到部落和联盟的所有采矿训练师。",
  ["Track Ore on Your Minimap"] = "在小地图上追踪矿石",
  ["You can only track one thing at a time, so {b}you can't track minerals and herbs together{/b}."] = "一次只能追踪一样东西，所以{b}无法同时追踪矿物和草药{/b}。",
  ["You learn {s:2580:spell_nature_earthquake:Find Minerals} together with Mining, but it's not turned on by default:"] = "学会采矿时会同时学会 {s:2580:spell_nature_earthquake:Find Minerals}，但它默认没有开启：",
  ["Open the Professions window with the hammer and pick button, the 2nd button in the menu at the bottom of your screen."] = "打开专业窗口，即屏幕底部菜单中带锤子和矿镐图标的第 2 个按钮。",
  ["Click Find Minerals in the Mining box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "点击采矿框中的“寻找矿物”。{b}我建议把它拖到动作条上，放在你死后要补的增益技能旁边。{/b}这样你会养成习惯，不容易忘记。",
  ["The Find Minerals buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "寻找矿物的增益效果会显示在小地图旁边。{b}每次死亡后追踪都会关闭，所以别忘了重新打开！{/b}",
  ["The Find Minerals button in the WoW Forever Professions window"] = "WoW Forever 专业窗口中的“寻找矿物”按钮",
  ["Mining Skill Bonuses"] = "采矿技能加成",
  ["You don't need these, but they help when you are stuck between two ores. With +5 you can mine Iron Deposits from 120 instead of 125, so you can skip the last few slow points of Tin."] = "这些不是必需的，但在你卡在两种矿石之间时很有帮助。有了 +5，你在 120 而不是 125 就能采铁矿脉，可以跳过锡矿最后几个慢点。",
  ["Item"] = "物品",
  ["Mining"] = "采矿",
  ["How to get it"] = "获取方式",
  ["An enchanter"] = "附魔师",
  ["Made by Engineers, you need Engineering 205 to wear it"] = "由工程师制作，需要工程学 205 才能装备",
  ["Reward of A Miner Problem, an Alliance quest in the Riverglades"] = "A Miner Problem 任务的奖励，这是 Riverglades 的一个联盟任务",
  ["Drops from Miner Johnson in The Deadmines"] = "死亡矿井的矿工约翰森掉落",
  ["Smelting to 105"] = "熔炼到 105",
  ["You can skip the first 105 skill points by buying ores on the Auction House and smelting them. If you prefer leveling Mining the normal way, scroll down to the mining routes. But I would recommend smelting if you have the gold, as it saves a lot of time. Sometimes the bars even sell for more than the ores or they are very close in price, so it's not like you are losing much by doing this."] = "你可以在拍卖行买矿石来熔炼，跳过前 105 个技能点。如果你更喜欢按正常方式练采矿，请向下滚动到采矿路线部分。但如果你有金币，我推荐熔炼，因为能省下大量时间。有时金属锭甚至比矿石卖得还贵，或者价格非常接近，所以这样做其实亏不了多少。",
  ["Buy around 140 {i:2770:inv_ore_copper_01:Copper Ore} and 70 {i:2771:inv_ore_tin_01:Tin Ore}. Smelting is mostly yellow and green, so you might need a few more if you are unlucky."] = "购买大约 140 个 {i:2770:inv_ore_copper_01:Copper Ore} 和 70 个 {i:2771:inv_ore_tin_01:Tin Ore}。熔炼大多是黄色和绿色，所以运气不好的话可能需要多买一些。",
  ["Notes"] = "说明",
  ["120-140x {s:2657:inv_ingot_02:Smelt Copper} until you reach 65. Keep 70 Copper Bars, you will need them for Bronze."] = "120-140x {s:2657:inv_ingot_02:Smelt Copper} 直到 65。留下 70 块铜锭，熔炼青铜时要用。",
  ["Learn Journeyman Mining, Smelt Tin and Smelt Bronze from your trainer. Make 70x {s:3304:inv_ingot_05:Smelt Tin}. It turns grey at 75, but you need all 70 Tin Bars for Bronze anyway."] = "向训练师学习熟练采矿、熔炼锡和熔炼青铜。做 70x {s:3304:inv_ingot_05:Smelt Tin}。它在 75 时会变灰，但反正你需要全部 70 块锡锭来做青铜。",
  ["Make 70x {s:2659:inv_ingot_bronze:Smelt Bronze} from the Copper Bars and Tin Bars you made. You will end up somewhere between 100 and 110, so you might need a few more."] = "用你做好的铜锭和锡锭做 70x {s:2659:inv_ingot_bronze:Smelt Bronze}。做完你会在 100 到 110 之间，所以可能需要多做几个。",
  ["Learn Smelt Silver from your trainer. Check the price of Silver Ore and Silver Bar first, because this part can get expensive. If you don't mind the cost, make 35-45x {s:2658:inv_ingot_01:Smelt Silver} until you reach 120. The last 5 points to 125 could take around 50 more Silver Ore, so I recommend mining from 120. (or keep smelting if you have the gold) Iron Deposits need Mining 125, but with +5 from the Mining Skill Bonuses above you can mine them from 120, so you can skip Tin and go straight to Iron."] = "向训练师学习熔炼银。先看看银矿石和银锭的价格，因为这部分可能会很贵。如果你不在意花费，就做 35-45x {s:2658:inv_ingot_01:Smelt Silver} 直到 120。到 125 的最后 5 点可能还要再花大约 50 个银矿石，所以我推荐从 120 开始去挖矿。（如果你有金币也可以继续熔炼）铁矿石需要采矿 125，但有了上面采矿技能加成的 +5，你从 120 就能采，所以可以跳过锡矿直接采铁矿。",
  ["{b}Don't forget to buy{/b} a {i:2901:inv_pick_02:Mining Pick} from the Mining Supplier near your trainer or from the trainer!"] = "{b}别忘了{/b}从训练师附近的采矿供应商或训练师本人那里买一把 {i:2901:inv_pick_02:Mining Pick}！",
  ["You can buy one from these vendors:"] = "你可以从以下商人处购买：",
  ["{n:0:horde:Norzsh} in the Valley of Trials, {n:0:horde:Flakk} in Razor Hill"] = "试炼谷的 {n:0:horde:Norzsh}，剃刀岭的 {n:0:horde:Flakk}",
  ["{n:0:horde:Vartha Rockmane} in Camp Narache, {n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "纳拉其营地的 {n:0:horde:Vartha Rockmane}，血蹄村的 {n:0:horde:Wunna Darkmane}",
  ["{n:0:horde:Walter Mason} in Deathknell, {n:0:horde:Abigail Shiel} in Brill"] = "丧钟镇的 {n:0:horde:Walter Mason}，布瑞尔的 {n:0:horde:Abigail Shiel}",
  ["{n:0::Uualia Suncrest} in Thendal Village, {n:0::Belandiel Farflight} in Shen'dar Village"] = "Thendal Village 的 {n:0::Uualia Suncrest}，Shen'dar Village 的 {n:0::Belandiel Farflight}",
  ["{n:0:horde:Gorina} in the Valley of Honor"] = "荣誉谷的 {n:0:horde:Gorina}",
  ["{n:0:horde:Elizabeth Van Talen} in the Rogues' Quarter"] = "盗贼区的 {n:0:horde:Elizabeth Van Talen}",
  ["{n:0:alliance:Brother Danil} in Northshire Valley, {n:0:alliance:Tharynn Bouden} in Goldshire"] = "北郡山谷的 {n:0:alliance:Brother Danil}，闪金镇的 {n:0:alliance:Tharynn Bouden}",
  ["{n:0:alliance:Thrawn Boltar} in Kharanos"] = "卡拉诺斯的 {n:0:alliance:Thrawn Boltar}",
  ["{n:0:alliance:Fanorran Stilloak} at Aldrassil in Shadowglen, {n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "幽影谷奥达希尔的 {n:0:alliance:Fanorran Stilloak}，多兰纳尔的 {n:0:alliance:Narret Shadowgrove}",
  ["{n:0:alliance:Brooke Stonebraid} in the Dwarven District"] = "矮人区的 {n:0:alliance:Brooke Stonebraid}",
  ["{n:0:alliance:Thurgrum Deepforge} in The Great Forge"] = "大熔炉的 {n:0:alliance:Thurgrum Deepforge}",
  ["Darnassus"] = "达纳苏斯",
  ["Like I said above, for most high level players I think it's best to skip this part and smelt your way up to at least 105. But if you prefer mining and you can choose your zone, I think {b}Durotar{/b} is the best for Horde and {b}Elwynn Forest{/b} for Alliance."] = "正如上面所说，对大多数高等级玩家来说，我认为最好跳过这部分，靠熔炼至少升到 105。但如果你更喜欢挖矿并且可以选择区域，我认为部落最好选 {b}杜隆塔尔{/b}，联盟最好选 {b}艾尔文森林{/b}。",
  ["One or two laps around the zone will get you enough Copper Ore to reach 65 with smelting."] = "在区域里绕一两圈，就能采到足够的铜矿石，靠熔炼升到 65。",
  ["After you do one lap, {b}stop at Razor Hill and smelt your Copper Ore{/b} into Copper Bars."] = "绕完一圈后，{b}在剃刀岭停下，把铜矿石熔炼成{/b}铜锭。",
  ["Mining route in Durotar"] = "杜隆塔尔的采矿路线",
  ["The cave marked with the red circle has 5 Copper Veins inside, {b}the respawn rate is so fast that you can basically stay inside the cave and level there{/b}. The cave layout is also very good because there is a drop down at the end, so you can quickly return to the start and continue mining. If the respawn rate is not enough for you or there is competition, just run outside, mine a couple of Copper Veins and go back to the cave."] = "红圈标记的山洞里有 5 个铜矿脉，{b}刷新速度快到你基本可以待在洞里升级{/b}。山洞的结构也很好，尽头有一个可以跳下去的地方，能迅速回到起点继续挖。如果刷新速度不够或者有人抢，就跑出去挖几个铜矿脉再回洞里。",
  ["You can also just do a full lap in Mulgore, the route is very easy to follow, it's basically a loop around the edge of the zone. But I found the cave to be better without a mount."] = "你也可以在莫高雷绕完整一圈，路线很好跟，基本就是沿着区域边缘绕一圈。不过没有坐骑的话，我觉得山洞更好。",
  ["{b}You can smelt your ore at the Bael'dun Digsite{/b}, the dwarf camp just north of the cave has a forge and an anvil. (marked on the map) The dwarves there are hostile."] = "{b}你可以在巴尔丹挖掘场熔炼矿石{/b}，山洞正北方的矮人营地里有熔炉和铁砧。（已在地图上标出）那里的矮人是敌对的。",
  ["Mining route in Mulgore with the forge and anvil at the Bael'dun Digsite"] = "莫高雷的采矿路线，以及巴尔丹挖掘场的熔炉和铁砧",
  ["Both routes are good. The route on the east side of the zone will probably have fewer people, because there are fewer quest hubs there."] = "两条路线都不错。区域东侧的路线人可能会少一些，因为那边的任务点比较少。",
  ["{b}Stop at Brill after one lap{/b} to smelt your Copper Ore."] = "{b}绕完一圈后在布瑞尔停下{/b}，熔炼你的铜矿石。",
  ["Mining route in Tirisfal Glades"] = "提瑞斯法林地的采矿路线",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies} as your reward, it teaches you Mining."] = "{q:93552::Harvesting Windstones} 是你在 Thendal Village 最早接到的任务之一。奖励选择 {i:247840:inv_10_specialization_professionbook_mining_orig:Mining for Dummies}，它会教你采矿。",
  ["The respawn rate is very fast around this area, sometimes the veins spawned right on top of me. You can do a larger route, but without a mount and with the fast respawn rate I found it wasn't needed."] = "这一带的刷新速度非常快，有时矿脉就刷在我脚下。你可以走更大的路线，但没有坐骑而且刷新又快，我觉得没有必要。",
  ["{b}Stop at Shen'dar Village after one lap{/b} to smelt your Copper Ore."] = "{b}绕完一圈后在 Shen'dar Village 停下{/b}，熔炼你的铜矿石。",
  ["Mining route on Zephras Isle"] = "Zephras Isle 的采矿路线",
  ["Just move back and forth along the marked route, and clear the cave if you are high enough level. The respawn rate is quite fast inside the cave, so you might not even have to leave it, it depends on your level. You can also just skip the cave, the respawn rate seems to be fast enough on the route, but then do the small detour to the north too."] = "沿着标记的路线来回走就行，如果等级够高就把山洞也清掉。洞里的刷新速度相当快，所以你可能根本不用出来，这取决于你的等级。你也可以跳过山洞，路线上的刷新速度似乎也够快，不过那样的话也要往北绕一小段。",
  ["{b}Stop at Goldshire after one lap{/b} to smelt your Copper Ore."] = "{b}绕完一圈后在闪金镇停下{/b}，熔炼你的铜矿石。",
  ["Mining route in Elwynn Forest"] = "艾尔文森林的采矿路线",
  ["Not much to say about this one, just do loops around this area. You don't have to go inside the cave, it's optional and the respawn rate outside is quite fast."] = "这条没什么好说的，就在这一带绕圈。山洞不一定要进，是可选的，外面的刷新速度也相当快。",
  ["{b}Stop at Kharanos after one lap{/b} to smelt your Copper Ore."] = "{b}绕完一圈后在卡拉诺斯停下{/b}，熔炼你的铜矿石。",
  ["Mining route in Dun Morogh"] = "丹莫罗的采矿路线",
  ["These two caves have an insanely fast respawn rate. I don't know if it stays like this, but right now you can just stay inside the caves and level there."] = "这两个山洞的刷新速度快得离谱。我不知道会不会一直这样，但目前你完全可以待在洞里升级。",
  ["There is no forge in Teldrassil, {b}the closest one is at the Warrior's Terrace in Darnassus{/b}."] = "泰达希尔没有熔炉，{b}最近的熔炉在达纳苏斯的战士区{/b}。",
  ["Mining route in Teldrassil"] = "泰达希尔的采矿路线",
  ["Visit your trainer and learn Journeyman Mining, it requires Mining 50. The new Junior Mining Trainers in the starting areas won't teach you Journeyman Mining."] = "去找训练师学习熟练采矿，需要采矿 50。新手区里新增的初级采矿训练师不会教熟练采矿。",
  ["If you have any Copper Ore or Tin Ore at this point, smelt them and make Bronze Bars before you head out, because Bronze stops giving skill points around 105."] = "如果你此时手上还有铜矿石或锡矿石，出发前先熔炼并做成青铜锭，因为青铜在 105 左右就不再给技能点了。",
  ["For Alliance, the {b}Wetlands{/b} is the best one by far if you can manage the cave. For Horde it's the {b}Silverpine Forest{/b} cave or {b}Hillsbrad Foothills{/b}. The rest are pretty even, hard to judge."] = "联盟的话，如果你能应付山洞，{b}湿地{/b}是目前最好的选择。部落则是{b}银松森林{/b}的山洞或{b}希尔斯布莱德丘陵{/b}。其余的差不多，很难评判。",
  ["Ores in these zones: {i:2771:inv_ore_tin_01:Tin Ore}, {i:2770:inv_ore_copper_01:Copper Ore}, {i:2775:inv_stone_16:Silver Ore}"] = "这些区域的矿石：{i:2771:inv_ore_tin_01:Tin Ore}、{i:2770:inv_ore_copper_01:Copper Ore}、{i:2775:inv_stone_16:Silver Ore}",
  ["Tin Veins need Mining 65 and Silver Veins 75."] = "锡矿脉需要采矿 65，银矿脉需要 75。",
  ["Wetlands"] = "湿地",
  ["Silverpine Forest"] = "银松森林",
  ["Westfall"] = "西部荒野",
  ["Hillsbrad Foothills"] = "希尔斯布莱德丘陵",
  ["The Barrens"] = "贫瘠之地",
  ["Ashenvale"] = "灰谷",
  ["Stonetalon Mountains"] = "石爪山脉",
  ["This cave in the Wetlands is the best place for Alliance players to level Mining. The cave is full of Tin Veins and Incendicite Mineral Veins with a very fast respawn time."] = "湿地的这个山洞是联盟玩家练采矿的最佳地点。洞里满是锡矿脉和火岩矿脉，刷新时间非常短。",
  ["The mobs are around level 20 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "怪物大约 20 级，而且{b}在 Forever 中它们刷新得快得多，所以你需要比它们高出不少等级{/b}，否则它们会不断刷在你身边。",
  ["Mining route in the Wetlands"] = "湿地的采矿路线",
  ["This cave has 3 vein spawn points with a very fast respawn time, just mine the veins and wait for the respawn. (around 2 minutes)"] = "这个山洞有 3 个矿脉刷新点，刷新时间非常短，挖完矿脉等它刷新就行。（大约 2 分钟）",
  ["The mobs are around level 21-22 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "怪物大约 21-22 级，而且{b}在 Forever 中它们刷新得快得多，所以你需要比它们高出不少等级{/b}，否则它们会不断刷在你身边。",
  ["Mining route in Silverpine Forest"] = "银松森林的采矿路线",
  ["This cave has several Tin Veins that respawn very fast. There are also veins outside, so if you clear it too fast you can just run outside and mine a few there too."] = "这个山洞有好几个锡矿脉，刷新非常快。外面也有矿脉，所以如果洞里挖得太快，可以跑出去挖几个。",
  ["The mobs are around level 13-15 and {b}in Forever they respawn much faster, so you need to outlevel them by quite a few levels{/b}, or they will keep respawning right on top of you."] = "怪物大约 13-15 级，而且{b}在 Forever 中它们刷新得快得多，所以你需要比它们高出不少等级{/b}，否则它们会不断刷在你身边。",
  ["Mining route in Westfall"] = "西部荒野的采矿路线",
  ["This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area. The route goes around a Horde town, so I'm not sure how it works for Alliance. I think you can probably avoid the guards, but I only tested this one with a Horde character."] = "如果你更喜欢按正常方式挖矿，这是最好的选择，但这里是热门区域，可能会有更多玩家和你抢。路线会绕过一个部落城镇，所以我不确定联盟走起来如何。我想你大概可以避开卫兵，但我只用部落角色测试过。",
  ["Mining route in Hillsbrad Foothills"] = "希尔斯布莱德丘陵的采矿路线",
  ["The mobs are around level 22-26 here, so it's best to farm here if you are above those levels. But the respawn rate is fast."] = "这里的怪物大约 22-26 级，所以最好在你等级高于它们时来这里刷。不过刷新速度很快。",
  ["Mining route in The Barrens"] = "贫瘠之地的采矿路线",
  ["A very straightforward route that is easy to follow. This is the best if you prefer mining the normal way, but you might have more competition from other players because this is a popular area."] = "一条非常直接、容易跟的路线。如果你更喜欢按正常方式挖矿，这是最好的选择，但这里是热门区域，可能会有更多玩家和你抢。",
  ["Mining route in Ashenvale"] = "灰谷的采矿路线",
  ["This route might not work if more than one player is leveling Mining there, because when I tested it there were very few people around. But this place usually has fewer people, so I think it's a good alternative if you don't want to level in caves. The only downside is that sometimes an Iron Deposit spawns instead of a Tin Vein, and you can't mine it yet."] = "如果有不止一个玩家在这里练采矿，这条路线可能就不太好用了，因为我测试的时候附近人很少。但这里通常人比较少，所以如果你不想在山洞里升级，我觉得这是个不错的替代选择。唯一的缺点是有时刷出来的是铁矿石而不是锡矿脉，而你暂时还挖不了。",
  ["Mining route in Stonetalon Mountains"] = "石爪山脉的采矿路线",
  ["From this point the guide follows the standard Classic Mining routes. The beta cap was 30, so I couldn't properly test Arathi and Desolace. I'll revise this section once I level my character higher on live, but the main change is the ore respawn rate, so most routes should work and you can probably take shorter routes in most zones."] = "从这里开始，本指南采用标准的经典版采矿路线。测试服等级上限是 30，所以我没法好好测试阿拉希和凄凉之地。等我在正式服把角色练得更高后会修订这部分，不过主要的变化是矿石刷新速度，所以大多数路线应该都能用，而且在大多数区域你可能可以走更短的路线。",
  ["{b}Visit your trainer and learn Expert Mining{/b}, it requires Mining 125."] = "{b}去找训练师学习专家采矿{/b}，需要采矿 125。",
  ["Smelting Iron and Gold (optional)"] = "熔炼铁和金（可选）",
  ["If you want to save some time and have the gold, buy around 20 {i:2772:inv_ore_iron_01:Iron Ore} and make {s:3307:inv_ingot_iron:Smelt Iron} until 135 before you head out mining. After 135 it rarely gives a point, so don't count on reaching 140."] = "如果你想省点时间并且有金币，出发挖矿前买大约 20 个 {i:2772:inv_ore_iron_01:Iron Ore}，做 {s:3307:inv_ingot_iron:Smelt Iron} 直到 135。135 以后就很少加点了，所以别指望能到 140。",
  ["At 155 you can learn {s:3308:inv_ingot_03:Smelt Gold} from your trainer. It gives a point every time until 170, so around 22 Gold Ore takes you from 155 to 175 and you can start on Mithril right away. I recommend checking the price of Gold Ore and Gold Bar first."] = "到 155 你可以向训练师学习 {s:3308:inv_ingot_03:Smelt Gold}。到 170 之前每次都能加点，所以大约 22 个金矿石就能让你从 155 升到 175，然后马上开始挖秘银。我建议先看看金矿石和金锭的价格。",
  ["If you have a {b}lower level character{/b} around level 30, stick to the {b}Thousand Needles{/b} route, that's the safest. If you have a {b}higher level character or a mount{/b} already, I recommend {b}Arathi Highlands{/b}."] = "如果你是 30 级左右的{b}低等级角色{/b}，就走{b}千针石林{/b}路线，那是最安全的。如果你已经是{b}高等级角色或者有坐骑{/b}，我推荐{b}阿拉希高地{/b}。",
  ["Ores in these zones: {i:2772:inv_ore_iron_01:Iron Ore}, {i:2771:inv_ore_tin_01:Tin Ore}, {i:2776:inv_ore_gold_01:Gold Ore}"] = "这些区域的矿石：{i:2772:inv_ore_iron_01:Iron Ore}、{i:2771:inv_ore_tin_01:Tin Ore}、{i:2776:inv_ore_gold_01:Gold Ore}",
  ["Iron Deposits need Mining 125 and Gold Veins 155."] = "铁矿石需要采矿 125，金矿脉需要 155。",
  ["Arathi Highlands"] = "阿拉希高地",
  ["Thousand Needles"] = "千针石林",
  ["Desolace"] = "凄凉之地",
  ["There are 4 caves marked with red circles on the map. Make sure to go all the way to the end of each cave because you won't see all the mining veins from the entrance."] = "地图上用红圈标出了 4 个山洞。每个山洞一定要走到最深处，因为从入口看不到所有矿脉。",
  ["Low level players should skip all 4 caves, and low level Alliance players should take a detour and go south of Hammerfall!"] = "低等级玩家应该跳过全部 4 个山洞，低等级联盟玩家应该绕路走落锤镇南边！",
  ["Mining route in Arathi Highlands"] = "阿拉希高地的采矿路线",
  ["Mining route in Thousand Needles"] = "千针石林的采矿路线",
  ["Mining route in Desolace"] = "凄凉之地的采矿路线",
  ["To train past 225, visit your trainer and learn Artisan Mining, it requires Mining 200."] = "要突破 225，请去找训练师学习大师采矿，需要采矿 200。",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}"] = "这些区域的矿石：{i:3858:inv_ore_mithril_02:Mithril Ore}、{i:7911:inv_ore_truesilver_01:Truesilver Ore}",
  ["Mithril Deposits need Mining 175 and Truesilver Deposits 230."] = "秘银矿脉需要采矿 175，真银矿石需要 230。",
  ["The Hinterlands"] = "辛特兰",
  ["Tanaris"] = "塔纳利斯",
  ["The red route should be skipped by lower level players because the area is filled with level 62 elites. Lower level players might also want to consider skipping the cave marked with a red circle on the map. (depends on your gear/class)"] = "低等级玩家应该跳过红色路线，因为那一带满是 62 级精英。低等级玩家也可以考虑跳过地图上红圈标记的山洞。（取决于你的装备/职业）",
  ["Mining route in The Hinterlands"] = "辛特兰的采矿路线",
  ["Players below level 60 should skip the 4 caves marked with red circles."] = "60 级以下的玩家应该跳过红圈标记的 4 个山洞。",
  ["Mining route in Tanaris"] = "塔纳利斯的采矿路线",
  ["Ores in these zones: {i:3858:inv_ore_mithril_02:Mithril Ore}, {i:7911:inv_ore_truesilver_01:Truesilver Ore}, {i:10620:inv_ore_thorium_02:Thorium Ore}"] = "这些区域的矿石：{i:3858:inv_ore_mithril_02:Mithril Ore}、{i:7911:inv_ore_truesilver_01:Truesilver Ore}、{i:10620:inv_ore_thorium_02:Thorium Ore}",
  ["Small Thorium Veins need Mining 245."] = "瑟银矿脉需要采矿 245。",
  ["Un'Goro Crater"] = "安戈洛环形山",
  ["Blasted Lands"] = "诅咒之地",
  ["Felwood"] = "费伍德森林",
  ["You will find 2-3 veins in the two caves marked with red circles on the map."] = "地图上红圈标记的两个山洞里各有 2-3 个矿脉。",
  ["Lower level players should probably skip the cave to the south. It really depends on your level, gear and class."] = "低等级玩家最好跳过南边的山洞。这主要取决于你的等级、装备和职业。",
  ["Mining route in Un'Goro Crater"] = "安戈洛环形山的采矿路线",
  ["Both caves marked with red circles have a lot of mobs inside, so I only recommend this zone to level 60 players with good gear, or to Druids and Rogues with stealth."] = "红圈标记的两个山洞里都有很多怪物，所以我只推荐装备好的 60 级玩家，或者能潜行的德鲁伊和盗贼来这个区域。",
  ["It's really hard to navigate inside the Garrison Armory mine, so I included a small map. {b}Alliance{/b} players can't mine inside the Garrison Armory!"] = "驻军武器库矿洞里很难辨别方向，所以我附了一张小地图。{b}联盟{/b}玩家无法在驻军武器库里采矿！",
  ["Mining route in the Blasted Lands"] = "诅咒之地的采矿路线",
  ["There are usually 2 veins inside the cave marked with a red circle. It's worth going in because the cave is small and there aren't many mobs inside, and if you are high level, you can pass some of them without aggro."] = "红圈标记的山洞里通常有 2 个矿脉。值得进去，因为山洞很小、怪物不多，如果你等级高，还能不引怪地绕过一些。",
  ["I recommend skipping the other two caves at Jaedenar, especially Shadow Hold. (if you have stealth, they might be worth going into)"] = "我建议跳过加德纳尔的另外两个山洞，尤其是暗影堡。（如果你能潜行，或许值得进去）",
  ["Mining route in Felwood"] = "费伍德森林的采矿路线",
  ["Ores in these zones: {i:10620:inv_ore_thorium_02:Thorium Ore}, {i:3858:inv_ore_mithril_02:Mithril Ore}"] = "这些区域的矿石：{i:10620:inv_ore_thorium_02:Thorium Ore}、{i:3858:inv_ore_mithril_02:Mithril Ore}",
  ["At 275 you can mine Rich Thorium Veins too."] = "到 275 你还可以采富瑟银矿。",
  ["Eastern Plaguelands"] = "东瘟疫之地",
  ["Winterspring"] = "冬泉谷",
  ["Burning Steppes"] = "燃烧平原",
  ["Almost the same as the previous Un'Goro route, but now it includes Rich Thorium Veins."] = "和前面的安戈洛路线几乎一样，只是现在加上了富瑟银矿。",
  ["Mining route with Rich Thorium Veins in Un'Goro Crater"] = "安戈洛环形山包含富瑟银矿的采矿路线",
  ["The red line is full of level 57-58 elites, so if your gear is bad, you should probably skip that part unless you have stealth. With some practice you can usually get through and only pull a few of them."] = "红线上满是 57-58 级精英，所以如果你装备不好，除非能潜行，否则最好跳过那一段。多练几次的话，通常可以只引到几只就穿过去。",
  ["Mining route in the Eastern Plaguelands"] = "东瘟疫之地的采矿路线",
  ["The mobs in this cave are not that hard, so most classes can clear it. (depends on your gear)"] = "这个山洞里的怪物不算难，大多数职业都能清掉。（取决于你的装备）",
  ["Most classes can get into at least the first part of the cave without pulling aggro. You can try going deeper depending on your gear."] = "大多数职业至少可以不引怪地进入山洞的前半部分。根据你的装备，可以试着往更深处走。",
  ["A lot of elites patrol this gorge, but you can usually pass most of them without pulling aggro. Sometimes you have to kill 1 or 2."] = "这条峡谷里有很多精英在巡逻，但通常你可以不引怪地绕过大部分。有时得杀掉 1 到 2 只。",
  ["I don't recommend this area for most players because it's hard to farm here without dying. It really depends on your class and how good you are at avoiding mobs."] = "我不推荐大多数玩家来这里，因为在这里刷很难不死。这主要取决于你的职业以及你躲怪的水平。",
  ["Mining route in Winterspring"] = "冬泉谷的采矿路线",
  ["The two caves marked with red circles are full of level 50 mobs, so lower level players might want to skip them. (depends on your gear and level)"] = "红圈标记的两个山洞里满是 50 级怪物，所以低等级玩家可能要跳过它们。（取决于你的装备和等级）",
  ["Mining route in the Burning Steppes"] = "燃烧平原的采矿路线",
  ["This WoW Forever Herbalism leveling guide will show you the fastest way to level Herbalism from 1 to 300. You will also find a route map for every zone, every trainer location and where to train Herbalism past 75, 150 and 225."] = "这份 WoW Forever 草药学升级指南将告诉你把草药学从 1 升到 300 的最快方法。你还能找到每个区域的路线图、所有训练师的位置，以及在 75、150 和 225 之后去哪里继续学习草药学。",
  ["Below you will find the Herbalism trainers by starting zone and capital city, and the best zones to pick herbs in for every skill range. Herbalism goes well with Alchemy because you can use the herbs you pick to make potions and elixirs, so check out my Forever Alchemy leveling guide if you want to level Alchemy. But keep in mind, this guide is made to level Herbalism as fast as possible, so sometimes the herbs you pick are not the best ones for Alchemy."] = "下面是按新手区和主城列出的草药学训练师，以及每个技能区间最适合采药的区域。草药学和炼金术很搭，因为你可以用采到的草药制作药水和药剂，如果你想练炼金术，可以看看我的 Forever 炼金术升级指南。但请注意，本指南的目的是尽快练草药学，所以有时采到的草药并不是炼金术最需要的。",
  ["WoW Forever added a couple of new herbs, seeds and recipes. You can check them out here:"] = "WoW Forever 新增了几种草药、种子和配方。你可以在这里查看：",
  ["Herbalism Trainer Locations"] = "草药学训练师位置",
  ["Every capital city has a Herbalism trainer. You can also ask a guard where the herbalist is, then it will be marked with a red flag on your map."] = "每座主城都有草药学训练师。你也可以询问卫兵草药师在哪里，位置会以红旗标记在你的地图上。",
  ["Orgrimmar: {n:0:horde:Jandi}"] = "奥格瑞玛：{n:0:horde:Jandi}",
  ["Undercity: {n:0:horde:Martha Alliestar}"] = "幽暗城：{n:0:horde:Martha Alliestar}",
  ["Thunder Bluff: {n:0:horde:Komin Winterhoof}"] = "雷霆崖：{n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Zor'la} in the Valley of Trials (only up to 75) {n:0:horde:Mishiki} in Sen'jin Village"] = "试炼谷的 {n:0:horde:Zor'la}（最高只到 75） 森金村的 {n:0:horde:Mishiki}",
  ["{n:0:horde:Garan Sunstrider} in Camp Narache (only up to 75) {n:0:horde:Komin Winterhoof} in Thunder Bluff"] = "纳拉其营地的 {n:0:horde:Garan Sunstrider}（最高只到 75） 雷霆崖的 {n:0:horde:Komin Winterhoof}",
  ["{n:0:horde:Florence Nightshade} in Deathknell (only up to 75) {n:0:horde:Faruza} in Brill"] = "丧钟镇的 {n:0:horde:Florence Nightshade}（最高只到 75） 布瑞尔的 {n:0:horde:Faruza}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism. The trainers on the island are {n:0::Syriel Nightrain} in Valanaar and {n:0::Halassa Fernbreeze} in Shen'dar Village."] = "你出生的 Thendal Village 没有训练师，但你也不需要。{q:93552::Harvesting Windstones} 是你在 Thendal Village 最早接到的任务之一。奖励选择 {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest}，它会教你草药学。岛上的训练师是 Valanaar 的 {n:0::Syriel Nightrain} 和 Shen'dar Village 的 {n:0::Halassa Fernbreeze}。",
  ["Stormwind City: {n:0:alliance:Tannysa}"] = "暴风城：{n:0:alliance:Tannysa}",
  ["Ironforge: {n:0:alliance:Reyna Stonebranch}"] = "铁炉堡：{n:0:alliance:Reyna Stonebranch}",
  ["Darnassus: {n:0:alliance:Firodren Mooncaller}"] = "达纳苏斯：{n:0:alliance:Firodren Mooncaller}",
  ["{n:0:alliance:Nancy Songflower} (only up to 75) {n:0:alliance:Herbalist Pomeroy}"] = "{n:0:alliance:Nancy Songflower}（最高只到 75） {n:0:alliance:Herbalist Pomeroy}",
  ["{n:0:alliance:Emrys Flintbeard} (only up to 75) {n:0:alliance:Reyna Stonebranch} in Ironforge"] = "{n:0:alliance:Emrys Flintbeard}（最高只到 75） 铁炉堡的 {n:0:alliance:Reyna Stonebranch}",
  ["{n:0:alliance:Eleyna Duskbreeze} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Malorne Bladeleaf} in Dolanaar"] = "幽影谷奥达希尔的 {n:0:alliance:Eleyna Duskbreeze}（最高只到 75） 多兰纳尔的 {n:0:alliance:Malorne Bladeleaf}",
  ["You can find every Herbalism trainer for Horde and Alliance on my WoW Forever Herbalism Trainers page."] = "你可以在我的 WoW Forever 草药学训练师页面找到部落和联盟的所有草药学训练师。",
  ["Track Herbs on Your Minimap"] = "在小地图上追踪草药",
  ["You can only track one thing at a time, so {b}you can't track herbs and minerals together{/b}."] = "一次只能追踪一样东西，所以{b}无法同时追踪草药和矿物{/b}。",
  ["You learn {s:2383:inv_misc_flower_02:Find Herbs} together with Herbalism, but it's not turned on by default:"] = "学会草药学时会同时学会 {s:2383:inv_misc_flower_02:Find Herbs}，但它默认没有开启：",
  ["Click Find Herbs in the Herbalism box. {b}I recommend dragging it to your action bar, close to the buffs you use after you die.{/b} This way you make a habit out of it and you are less likely to forget it."] = "点击草药学框中的“寻找草药”。{b}我建议把它拖到动作条上，放在你死后要补的增益技能旁边。{/b}这样你会养成习惯，不容易忘记。",
  ["The Find Herbs buff shows up next to your minimap. {b}Your tracking turns off every time you die, so don't forget to turn it back on!{/b}"] = "寻找草药的增益效果会显示在小地图旁边。{b}每次死亡后追踪都会关闭，所以别忘了重新打开！{/b}",
  ["Herbalism Skill Bonuses"] = "草药学技能加成",
  ["You don't need these, but they help when you are stuck between two herbs. With +5 you can pick Kingsblood from 120 instead of 125, so you can move on earlier."] = "这些不是必需的，但在你卡在两种草药之间时很有帮助。有了 +5，你在 120 而不是 125 就能采皇血草，可以更早进入下一阶段。",
  ["Herbalism"] = "草药学",
  ["A world drop, check the Auction House"] = "世界掉落，去拍卖行看看",
  ["Henry Stern in Razorfen Downs teaches the recipe, it {b}requires Cooking 175{/b}. Take the left path at the start of the instance and go all the way to the end, to the stables, knock down the walls and talk to him."] = "剃刀高地的亨利·斯特恩会教这个配方，{b}需要烹饪 175{/b}。在副本入口处走左边的路，一直走到尽头的马厩，打破墙壁后和他对话。",
  ["can be very handy when you find a herb you can't pick yet and you are only a few points short. It will probably be pretty expensive early on because of the Goldthorn prices, but it's worth keeping a few with you while you level Herbalism."] = "当你发现一株还采不了的草药、只差几点时会非常方便。由于金棘草的价格，早期它可能相当贵，但练草药学时值得随身带几个。",
  ["Every starting zone is full of herbs, so it doesn't really matter which one you choose. The respawn rate is so fast that without a mount you often can't even finish a full lap, you just run around in circles and pick the herbs as you see them."] = "每个新手区都遍地是草药，所以选哪个其实无所谓。刷新速度快到没有坐骑时你常常连一整圈都走不完，就是绕着圈跑，看到草药就采。",
  ["Herbs in these zones: {i:2447:inv_misc_flower_02:Peacebloom}, {i:765:inv_misc_herb_10:Silverleaf}, {i:2449:inv_misc_herb_07:Earthroot}"] = "这些区域的草药：{i:2447:inv_misc_flower_02:Peacebloom}、{i:765:inv_misc_herb_10:Silverleaf}、{i:2449:inv_misc_herb_07:Earthroot}",
  ["Earthroot requires Herbalism 15."] = "地根草需要草药学 15。",
  ["Herbalism route in Durotar"] = "杜隆塔尔的采药路线",
  ["Herbalism route in Mulgore"] = "莫高雷的采药路线",
  ["Herbalism route in Tirisfal Glades"] = "提瑞斯法林地的采药路线",
  ["{q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest} as your reward, it teaches you Herbalism."] = "{q:93552::Harvesting Windstones} 是你在 Thendal Village 最早接到的任务之一。奖励选择 {i:247841:inv_10_specialization_professionbook_herbalism_color1:Wild Harvest}，它会教你草药学。",
  ["Herbalism route on Zephras Isle"] = "Zephras Isle 的采药路线",
  ["Herbalism route in Elwynn Forest"] = "艾尔文森林的采药路线",
  ["Herbalism route in Dun Morogh"] = "丹莫罗的采药路线",
  ["Herbalism route in Teldrassil"] = "泰达希尔的采药路线",
  ["Visit your trainer and learn Journeyman Herbalism, it requires Herbalism 50. The new Junior Herbalism Trainers in the starting areas won't teach you Journeyman Herbalism."] = "去找训练师学习熟练草药学，需要草药学 50。新手区里新增的初级草药学训练师不会教熟练草药学。",
  ["Herbs in these zones: {i:785:inv_jewelry_talisman_03:Mageroyal}, {i:2450:inv_misc_root_01:Briarthorn}, {i:3820:inv_misc_herb_11:Stranglekelp}"] = "这些区域的草药：{i:785:inv_jewelry_talisman_03:Mageroyal}、{i:2450:inv_misc_root_01:Briarthorn}、{i:3820:inv_misc_herb_11:Stranglekelp}",
  ["Stranglekelp requires Herbalism 85, so you can't pick it right away."] = "荆棘藻需要草药学 85，所以你暂时还采不了。",
  ["Loch Modan"] = "洛克莫丹",
  ["The respawn rate in the lower part of Silverpine Forest is fast enough that you can basically run in small circles in the marked area. I tested this without a mount, so with a mount it might be different, but then running up and down the main road to the loop should work fine as well."] = "银松森林南部的刷新速度足够快，你基本可以在标记区域里绕小圈跑。我是在没有坐骑的情况下测试的，有坐骑可能会不一样，但那样沿着主路上下跑到环线也应该没问题。",
  ["Herbalism route in Silverpine Forest"] = "银松森林的采药路线",
  ["A very easy route to follow, but there might be a bit fewer herbs than in Darkshore."] = "一条非常容易跟的路线，但草药可能比黑海岸少一些。",
  ["Herbalism route in Loch Modan"] = "洛克莫丹的采药路线",
  ["Darkshore has herbs everywhere. I used this loop, but you can also expand it to the upper part of the map. The respawn rate is fast, so you can do smaller circles in different areas. I just found this route pretty easy and chill to follow."] = "黑海岸到处都是草药。我用的是这条环线，但你也可以扩展到地图上半部分。刷新速度很快，所以你可以在不同区域绕小圈。我只是觉得这条路线很好跟，也很轻松。",
  ["Herbalism route in Darkshore"] = "黑海岸的采药路线",
  ["To train past 150, visit your trainer and learn Expert Herbalism, it requires Herbalism 125."] = "要突破 150，请去找训练师学习专家草药学，需要草药学 125。",
  ["Herbs in these zones: {i:2453:inv_misc_herb_01:Bruiseweed}, {i:3355:inv_misc_flower_01:Wild Steelbloom}, {i:3820:inv_misc_herb_11:Stranglekelp}, {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}"] = "这些区域的草药：{i:2453:inv_misc_herb_01:Bruiseweed}、{i:3355:inv_misc_flower_01:Wild Steelbloom}、{i:3820:inv_misc_herb_11:Stranglekelp}、{i:3356:inv_misc_herb_03:Kingsblood}、{i:3357:inv_misc_root_02:Liferoot}",
  ["Kingsblood requires Herbalism 125 and Liferoot 150, so you can't pick them right away."] = "皇血草需要草药学 125，活根草需要 150，所以你暂时还采不了。",
  ["Running this loop in Hillsbrad Foothills gives the herbs enough time to respawn, but I tested it without a mount, so with a mount it might be different."] = "在希尔斯布莱德丘陵跑这条环线，能给草药足够的刷新时间，但我是在没有坐骑的情况下测试的，有坐骑可能会不一样。",
  ["Herbalism route in Hillsbrad Foothills"] = "希尔斯布莱德丘陵的采药路线",
  ["All three areas are good here:"] = "这里的三个区域都不错：",
  ["The mobs here are only around level 14-15, so this is the lowest level area where you can safely farm these herbs."] = "这里的怪物只有 14-15 级左右，所以这是能安全采这些草药的最低等级区域。",
  ["A good alternative if someone is already farming the first area. The mobs are higher level here, around 25."] = "如果第一个区域已经有人在采，这是个不错的替代选择。这里的怪物等级更高，大约 25 级。",
  ["This area is usually pretty crowded and full of mobs. {b}I only recommend it if you are over 125 already{/b}, because there is more Kingsblood here."] = "这个区域通常相当拥挤，而且到处是怪物。{b}只有你已经超过 125 时我才推荐{/b}，因为这里的皇血草更多。",
  ["Herbalism route in Stonetalon Mountains"] = "石爪山脉的采药路线",
  ["From this point the guide follows the standard Classic Herbalism routes. The beta cap was 30, so I couldn't test the higher level routes. I'll revise this section once I level my character higher on live, but the main change is the herb respawn rate, so most routes should work."] = "从这里开始，本指南采用标准的经典版草药学路线。测试服等级上限是 30，所以我没法测试更高等级的路线。等我在正式服把角色练得更高后会修订这部分，不过主要的变化是草药刷新速度，所以大多数路线应该都能用。",
  ["Herbs in these zones: {i:3356:inv_misc_herb_03:Kingsblood}, {i:3357:inv_misc_root_02:Liferoot}, {i:3818:inv_misc_herb_12:Fadeleaf}, {i:3821:inv_misc_herb_15:Goldthorn}, {i:3358:inv_misc_herb_08:Khadgar's Whisker}"] = "这些区域的草药：{i:3356:inv_misc_herb_03:Kingsblood}、{i:3357:inv_misc_root_02:Liferoot}、{i:3818:inv_misc_herb_12:Fadeleaf}、{i:3821:inv_misc_herb_15:Goldthorn}、{i:3358:inv_misc_herb_08:Khadgar's Whisker}",
  ["Khadgar's Whisker requires Herbalism 185, so you can't pick it right away."] = "卡德加的胡须需要草药学 185，所以你暂时还采不了。",
  ["Stranglethorn Vale"] = "荆棘谷",
  ["Herbalism route in Stranglethorn Vale"] = "荆棘谷的采药路线",
  ["Herbalism route in Arathi Highlands"] = "阿拉希高地的采药路线",
  ["{b}Learn Artisan Herbalism before you leave for these zones{/b}, it requires Herbalism 200. There is no trainer in Tanaris or Searing Gorge, so if you skip it, you have to fly back at 225."] = "{b}去这些区域之前先学会大师草药学{/b}，需要草药学 200。塔纳利斯和灼热峡谷都没有训练师，所以如果你没学，到 225 时就得飞回去。",
  ["Herbs in these zones: {i:8831:inv_misc_herb_17:Purple Lotus}, {i:4625:inv_misc_herb_19:Firebloom}"] = "这些区域的草药：{i:8831:inv_misc_herb_17:Purple Lotus}、{i:4625:inv_misc_herb_19:Firebloom}",
  ["Searing Gorge"] = "灼热峡谷",
  ["Herbalism route in Tanaris"] = "塔纳利斯的采药路线",
  ["Herbalism route in Searing Gorge"] = "灼热峡谷的采药路线",
  ["Herbs in The Hinterlands: {i:8838:inv_misc_herb_18:Sungrass}, {i:8831:inv_misc_herb_17:Purple Lotus}, {i:8845:inv_mushroom_08:Ghost Mushroom}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}"] = "辛特兰的草药：{i:8838:inv_misc_herb_18:Sungrass}、{i:8831:inv_misc_herb_17:Purple Lotus}、{i:8845:inv_mushroom_08:Ghost Mushroom}、{i:13464:inv_misc_herb_sansamroot:Golden Sansam}",
  ["I marked a cave with a red X, there are a lot of Ghost Mushrooms in the cave, but you can only pick them with Herbalism 245."] = "我用红色 X 标出了一个山洞，洞里有很多幽灵菇，但需要草药学 245 才能采。",
  ["Herbalism route in The Hinterlands"] = "辛特兰的采药路线",
  ["Herbs in Felwood: {i:8838:inv_misc_herb_18:Sungrass}, {i:8846:inv_misc_herb_16:Gromsblood}, {i:13464:inv_misc_herb_sansamroot:Golden Sansam}, {i:13463:inv_misc_herb_dreamfoil:Dreamfoil}, {i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}, {i:13466:inv_misc_herb_plaguebloom:Plaguebloom}"] = "费伍德森林的草药：{i:8838:inv_misc_herb_18:Sungrass}、{i:8846:inv_misc_herb_16:Gromsblood}、{i:13464:inv_misc_herb_sansamroot:Golden Sansam}、{i:13463:inv_misc_herb_dreamfoil:Dreamfoil}、{i:13465:inv_misc_herb_mountainsilversage:Mountain Silversage}、{i:13466:inv_misc_herb_plaguebloom:Plaguebloom}",
  ["Herbalism route in Felwood"] = "费伍德森林的采药路线",
  ["This WoW Forever Skinning leveling guide will show you the fastest way to level Skinning from 1 to 300. You will also find every trainer location and the best places to skin for each skill range."] = "这份 WoW Forever 剥皮升级指南将告诉你把剥皮从 1 升到 300 的最快方法。你还能找到所有训练师的位置，以及每个技能区间最适合剥皮的地点。",
  ["This guide is aimed at higher level players who want to switch their profession, but it's good for lower level players too. Leveling Skinning is easy but really boring, you will have to run around and skin hundreds of mobs. Skinning goes well with Leatherworking because you can use the leather you skin, so check out my Forever Leatherworking leveling guide if you want to level Leatherworking."] = "本指南主要面向想要更换专业的高等级玩家，但对低等级玩家也同样适用。练剥皮很简单但非常无聊，你得到处跑，剥几百只怪的皮。剥皮和制皮很搭，因为你可以用剥下的皮革，如果你想练制皮，可以看看我的 Forever 制皮升级指南。",
  ["Skinning Trainer Locations"] = "剥皮训练师位置",
  ["Every capital city has a Skinning trainer. You can also ask a guard, then it will be marked with a red flag on your map."] = "每座主城都有剥皮训练师。你也可以询问卫兵，训练师的位置会以红旗标记在你的地图上。",
  ["Orgrimmar: {n:0:horde:Thuwd}"] = "奥格瑞玛：{n:0:horde:Thuwd}",
  ["Undercity: {n:0:horde:Killian Hagey}"] = "幽暗城：{n:0:horde:Killian Hagey}",
  ["Thunder Bluff: {n:0:horde:Mooranta}"] = "雷霆崖：{n:0:horde:Mooranta}",
  ["{n:0:horde:Kagil} in the Valley of Trials (only up to 75) {n:0:horde:Thuwd} in Orgrimmar"] = "试炼谷的 {n:0:horde:Kagil}（最高只到 75） 奥格瑞玛的 {n:0:horde:Thuwd}",
  ["{n:0:horde:Nawka Wildsong} in Camp Narache (only up to 75) {n:0:horde:Yonn Deepcut} in Bloodhoof Village"] = "纳拉其营地的 {n:0:horde:Nawka Wildsong}（最高只到 75） 血蹄村的 {n:0:horde:Yonn Deepcut}",
  ["{n:0:horde:Margaret Weaver} in Deathknell (only up to 75) {n:0:horde:Rand Rhobart} in Tirisfal Glades"] = "丧钟镇的 {n:0:horde:Margaret Weaver}（最高只到 75） 提瑞斯法林地的 {n:0:horde:Rand Rhobart}",
  ["There is no trainer in Thendal Village, where you start, but you don't need one. {q:93552::Harvesting Windstones} is one of the first quests you get in Thendal Village. Pick {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners} as your reward, it teaches you Skinning. The trainers on the island are {n:0::Ishlee Breezewhisper} in Valanaar and {n:0::Mendalass Tattermend} in Shen'dar Village."] = "你出生的 Thendal Village 没有训练师，但你也不需要。{q:93552::Harvesting Windstones} 是你在 Thendal Village 最早接到的任务之一。奖励选择 {i:247846:inv_10_specialization_professionbook_skinning_color1:Pelt Collecting for Beginners}，它会教你剥皮。岛上的训练师是 Valanaar 的 {n:0::Ishlee Breezewhisper} 和 Shen'dar Village 的 {n:0::Mendalass Tattermend}。",
  ["Stormwind City: {n:0:alliance:Maris Granger}"] = "暴风城：{n:0:alliance:Maris Granger}",
  ["Ironforge: {n:0:alliance:Balthus Stoneflayer}"] = "铁炉堡：{n:0:alliance:Balthus Stoneflayer}",
  ["Darnassus: {n:0:alliance:Eladriel}"] = "达纳苏斯：{n:0:alliance:Eladriel}",
  ["{n:0:alliance:Riley Peltskinner} in Northshire Valley (only up to 75) {n:0:alliance:Helene Peltskinner} in Goldshire"] = "北郡山谷的 {n:0:alliance:Riley Peltskinner}（最高只到 75） 闪金镇的 {n:0:alliance:Helene Peltskinner}",
  ["{n:0:alliance:Brighid Stormflayer} (only up to 75) {n:0:alliance:Balthus Stoneflayer} in Ironforge"] = "{n:0:alliance:Brighid Stormflayer}（最高只到 75） 铁炉堡的 {n:0:alliance:Balthus Stoneflayer}",
  ["{n:0:alliance:Terunne Bearshaper} at Aldrassil in Shadowglen (only up to 75) {n:0:alliance:Radnaal Maneweaver} in Teldrassil"] = "幽影谷奥达希尔的 {n:0:alliance:Terunne Bearshaper}（最高只到 75） 泰达希尔的 {n:0:alliance:Radnaal Maneweaver}",
  ["You can find every Skinning trainer for Horde and Alliance on my WoW Forever Skinning Trainers page."] = "你可以在我的 WoW Forever 剥皮训练师页面找到部落和联盟的所有剥皮训练师。",
  ["Skinning Skill Requirements"] = "剥皮技能要求",
  ["You need 5 times the mob's level in Skinning to skin it, so a level 30 mob needs Skinning 150. Below level 20 it's less, if you follow the guide you don't have to worry about this."] = "剥皮技能需要达到怪物等级的 5 倍才能剥它的皮，所以 30 级的怪物需要剥皮 150。20 级以下的要求更低，只要按照指南走就不用担心。",
  ["Mob level"] = "怪物等级",
  ["Skinning needed"] = "所需剥皮技能",
  ["10 for a level 11 mob, 10 more for every level (level 15 needs 50, level 19 needs 90)"] = "11 级怪物需要 10，每高一级多 10（15 级需要 50，19 级需要 90）",
  ["20 and up"] = "20 级及以上",
  ["5 times the level"] = "等级的 5 倍",
  ["If you enchant your gloves with {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}, you can skin mobs 1 level higher than normal."] = "如果你给手套附魔 {s:13698:spell_holy_greaterheal:Enchant Gloves - Skinning}，可以剥比平常高 1 级的怪物。",
  ["Horde players can also pick the {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife} (+3 Skinning) as a reward from Unwelcome Guests in The Barrens."] = "部落玩家还可以在贫瘠之地的 Unwelcome Guests 任务中选择 {i:269716:inv_weapon_shortblade_05:Keen Skinning Knife}（+3 剥皮）作为奖励。",
  ["In WoW Forever you can skin the mobs in the starting areas, and they give skill points all the way up to 75."] = "在 WoW Forever 中，你可以剥新手区怪物的皮，而且一直到 75 都能加技能点。",
  ["{b}Any starting zone is good{/b} for this. If you are leveling a new character, you can skin any mob in your starting zone, so you don't need a recommendation until around level 10, when you leave the zone. The two places below are for players who already have a higher level character and want to catch up on Skinning. A lot of players will be leveling new characters there, so there is always something to skin."] = "{b}任何新手区都可以{/b}。如果你在练新角色，可以剥新手区里任何怪物的皮，所以在大约 10 级离开新手区之前都不需要推荐地点。下面两个地方是给已有高等级角色、想补练剥皮的玩家的。很多玩家会在那里练新角色，所以总有东西可剥。",
  ["{b}Don't forget to buy a {i:7005:inv_weapon_shortblade_01:Skinning Knife}!{/b} The Leatherworking Supply vendors near your trainer and most General Goods vendors sell it. You don't have to equip it, but you can't skin without one in your bags."] = "{b}别忘了买一把 {i:7005:inv_weapon_shortblade_01:Skinning Knife}！{/b}训练师附近的制皮供应商和大多数杂货商都有卖。不需要装备它，但背包里没有它就无法剥皮。",
  ["Skin the {n:3098::Mottled Boars} in the Valley of Trials in Durotar."] = "剥杜隆塔尔试炼谷的 {n:3098::Mottled Boars}。",
  ["{b}Mob level:{/b} 1-2"] = "{b}怪物等级：{/b}1-2",
  ["The Mottled Boars in the Valley of Trials in Durotar"] = "杜隆塔尔试炼谷的斑点野猪",
  ["Skin the {n:299::Young Wolves} and {n:69::Timber Wolves} in Northshire Valley in Elwynn Forest."] = "剥艾尔文森林北郡山谷的 {n:299::Young Wolves} 和 {n:69::Timber Wolves}。",
  ["The wolves in Northshire Valley in Elwynn Forest"] = "艾尔文森林北郡山谷的狼",
  ["Visit your trainer and learn Journeyman Skinning if you haven't yet, it requires Skinning 50. The new Junior Skinning Trainers in the starting areas won't teach you Journeyman Skinning."] = "如果还没学，去找训练师学习熟练剥皮，需要剥皮 50。新手区里新增的初级剥皮训练师不会教熟练剥皮。",
  ["To train past 150, visit your trainer again and learn Expert Skinning when you reach 125."] = "要突破 150，到 125 时再去找训练师学习专家剥皮。",
  ["Kill and skin {n:3256::Sunscale Scytheclaw}, {n:3426::Zhevra Charger}, {n:3245::Ornery Plainstrider}."] = "击杀并剥皮 {n:3256::Sunscale Scytheclaw}、{n:3426::Zhevra Charger}、{n:3245::Ornery Plainstrider}。",
  ["Go to the small raptor camp just west of Northwatch Hold. Skin the level 16-17 ones until 80, from 80 you can skin the level 18 ones too. Stay here until 150, the last 10 points are green but the respawn is fast."] = "前往北卫要塞正西边的小型迅猛龙营地。先剥 16-17 级的直到 80，从 80 开始也能剥 18 级的。一直待到 150，最后 10 点是绿色的，但刷新很快。",
  ["{b}Mob level:{/b} 16-18"] = "{b}怪物等级：{/b}16-18",
  ["The Sunscale Scytheclaws west of Northwatch Hold in the Barrens"] = "贫瘠之地北卫要塞西边的日鳞镰爪龙",
  ["75-125 Loch Modan"] = "75-125 洛克莫丹",
  ["Kill and skin {n:1192::Elder Mountain Boar}, {n:1189::Black Bear Patriarch}."] = "击杀并剥皮 {n:1192::Elder Mountain Boar}、{n:1189::Black Bear Patriarch}。",
  ["{n:1693::Loch Crocolisk} are also skinnable, make sure to pull them when you get to the shore."] = "{n:1693::Loch Crocolisk} 也可以剥皮，到岸边时记得把它们也拉过来。",
  ["Stay here until around 125, then head north to the Wetlands, it is on the way to Hillsbrad."] = "在这里待到 125 左右，然后往北去湿地，正好在去希尔斯布莱德的路上。",
  ["{b}Mob level:{/b} 16-17"] = "{b}怪物等级：{/b}16-17",
  ["Skinning spot in Loch Modan"] = "洛克莫丹的剥皮地点",
  ["125-150 Wetlands"] = "125-150 湿地",
  ["Kill and skin {n:1022::Mottled Scytheclaw}, {n:1023::Mottled Razormaw}."] = "击杀并剥皮 {n:1022::Mottled Scytheclaw}、{n:1023::Mottled Razormaw}。",
  ["There are always a few of them at Whelgar's Excavation Site, so you never run out of mobs to kill."] = "维尔加挖掘场总有几只，所以永远不缺怪杀。",
  ["{b}Mob level:{/b} 25-27"] = "{b}怪物等级：{/b}25-27",
  ["Whelgar's Excavation Site in the Wetlands"] = "湿地的维尔加挖掘场",
  ["From 150, go to the Foothill Caverns in Hillsbrad Foothills, the yeti cave on the border of Alterac Mountains, or to the Rotting Orchard in Duskwood."] = "从 150 开始，去希尔斯布莱德丘陵的山麓洞穴，即奥特兰克山脉边界上的雪人洞，或者去暮色森林的腐烂果园。",
  ["Duskwood"] = "暮色森林",
  ["Both factions can get there, Horde from Tarren Mill and Alliance from Southshore."] = "两个阵营都能去，部落从塔伦米尔出发，联盟从南海镇出发。",
  ["Kill and skin {n:2248::Cave Yeti}, {n:2249::Ferocious Yeti}."] = "击杀并剥皮 {n:2248::Cave Yeti}、{n:2249::Ferocious Yeti}。",
  ["The yetis respawn so fast that you can stay inside the cave the whole time."] = "雪人刷新快到你可以一直待在洞里。",
  ["{b}Mob level:{/b} 30-32"] = "{b}怪物等级：{/b}30-32",
  ["The Foothill Caverns in Hillsbrad Foothills"] = "希尔斯布莱德丘陵的山麓洞穴",
  ["Duskwood is an Alliance zone, but Grom'gol is close, so Horde players can get there too."] = "暮色森林是联盟区域，但离格罗姆高营地很近，所以部落玩家也能去。",
  ["Kill and skin {n:898::Nightbane Worgen}, {n:533::Nightbane Shadow Weaver}, {n:205::Nightbane Dark Runner}."] = "击杀并剥皮 {n:898::Nightbane Worgen}、{n:533::Nightbane Shadow Weaver}、{n:205::Nightbane Dark Runner}。",
  ["Start at the area marked with 1, clear the mobs outside and inside Roland's Doom cave, then go to the Rotting Orchard until the mobs respawn."] = "从标记 1 的区域开始，清掉罗兰之墓洞穴内外的怪物，然后去腐烂果园，直到怪物刷新。",
  ["{b}Mob level:{/b} 26-29"] = "{b}怪物等级：{/b}26-29",
  ["Roland's Doom and the Rotting Orchard in Duskwood"] = "暮色森林的罗兰之墓和腐烂果园",
  ["Visit your trainer and learn Artisan Skinning, it requires Skinning 200."] = "去找训练师学习大师剥皮，需要剥皮 200。",
  ["Mount up and go to the yeti cave at Feral Scar Vale in the south of Feralas. Both factions can get there, Horde from Camp Mojache and Alliance from Feathermoon Stronghold."] = "骑上坐骑，前往菲拉斯南部深痕谷的雪人洞。两个阵营都能去，部落从莫沙彻营地出发，联盟从羽月要塞出发。",
  ["Kill and skin {n:5292::Feral Scar Yeti}, {n:5295::Enraged Feral Scar}, {n:5293::Hulking Feral Scar}."] = "击杀并剥皮 {n:5292::Feral Scar Yeti}、{n:5295::Enraged Feral Scar}、{n:5293::Hulking Feral Scar}。",
  ["{b}Mob level:{/b} 43-46"] = "{b}怪物等级：{/b}43-46",
  ["The yeti cave at Feral Scar Vale in Feralas"] = "菲拉斯深痕谷的雪人洞",
  ["From 280, fly to Marshal's Refuge and skin the dinosaurs in the western part of Un'Goro Crater."] = "从 280 开始，飞到马绍尔营地，剥安戈洛环形山西部的恐龙。",
  ["Kill and skin {n:9163::Diemetradon}, {n:9166::Pterrordax}, {n:9164::Elder Diemetradon}, {n:9167::Frenzied Pterrordax}."] = "击杀并剥皮 {n:9163::Diemetradon}、{n:9166::Pterrordax}、{n:9164::Elder Diemetradon}、{n:9167::Frenzied Pterrordax}。",
  ["{b}Mob level:{/b} 50-55"] = "{b}怪物等级：{/b}50-55",
  ["The dinosaur area in the west of Un'Goro Crater"] = "安戈洛环形山西部的恐龙区域",
  ["This WoW Forever Fishing and Cooking leveling guide will show you the fastest way to level Fishing and Cooking together from 1 to 300."] = "这份 WoW Forever 钓鱼和烹饪升级指南将告诉你把钓鱼和烹饪一起从 1 升到 300 的最快方法。",
  ["Leveling Fishing takes a long time, so it's best to level these two together, because every fish you catch is also a Cooking recipe and your Cooking goes up for free while you fish. You will still need a lot of patience because you have to catch a lot of fish to get from start to finish. If you only want one of them, use my Fishing guide or my Cooking guide instead."] = "练钓鱼要花很长时间，所以最好把这两项一起练，因为你钓到的每条鱼同时也是一个烹饪配方，钓鱼的同时烹饪也免费跟着涨。不过你仍然需要很大的耐心，因为从头到尾要钓很多鱼。如果你只想练其中一项，请改用我的钓鱼指南或烹饪指南。",
  ["Level Fishing to 75"] = "把钓鱼练到 75",
  ["If you can choose, {b}level Fishing in Mulgore{/b}, because everything is close together there. {n:0::Harn Longcast} in Bloodhoof Village sells both recipes and the pole, and the Fishing trainer stands at Stonebull Lake. Thunder Bluff, where you fish after 75, is right next to it."] = "如果可以选择，{b}在莫高雷练钓鱼{/b}，因为那里所有东西都离得很近。血蹄村的 {n:0::Harn Longcast} 同时出售两个配方和鱼竿，钓鱼训练师就站在石牛湖边。75 以后钓鱼的雷霆崖就在旁边。",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lau'Tiki} on the coast south of Sen'jin Village."] = "如果你还没学钓鱼，去森金村南边海岸找 {n:0::Lau'Tiki} 学习。",
  ["Buy {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} from {n:0::Zansoa} in Sen'jin Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在森金村的 {n:0::Zansoa} 处购买 {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel}。顺便在那里买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish on the coast next to {n:0::Lau'Tiki}, south of Sen'jin Village, until your Fishing skill reaches 75. Almost everything you catch there is {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}, about 70 of them."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在森金村南边 {n:0::Lau'Tiki} 旁边的海岸钓鱼，直到钓鱼技能达到 75。在那里钓到的几乎都是 {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}，大约 70 条。",
  ["Learn Journeyman Fishing from {n:0::Lau'Tiki}, it requires level 10."] = "向 {n:0::Lau'Tiki} 学习熟练钓鱼，需要 10 级。",
  ["The coast south of Sen'jin Village in Durotar, where to fish from 1 to 75"] = "杜隆塔尔森金村南边的海岸，1 到 75 的钓鱼地点",
  ["If you haven't learned Fishing yet, learn it from {n:0::Uthan Stillwater} at Stonebull Lake."] = "如果你还没学钓鱼，去石牛湖找 {n:0::Uthan Stillwater} 学习。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Harn Longcast} in Bloodhoof Village. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在血蹄村的 {n:0::Harn Longcast} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。顺便在那里买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Stonebull Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在石牛湖钓鱼，直到钓鱼技能达到 75。你会钓到大约 45 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Uthan Stillwater}, it requires level 10."] = "向 {n:0::Uthan Stillwater} 学习熟练钓鱼，需要 10 级。",
  ["Stonebull Lake around Bloodhoof Village in Mulgore, where to fish from 1 to 75"] = "莫高雷血蹄村附近的石牛湖，1 到 75 的钓鱼地点",
  ["If you haven't learned Fishing yet, learn it from {n:0::Clyde Kellen} at Brightwater Lake."] = "如果你还没学钓鱼，去明水湖找 {n:0::Clyde Kellen} 学习。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Martine Tramblay} at the Death's Watch Waystation, south-east of Brill. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在布瑞尔东南方 Death's Watch Waystation 的 {n:0::Martine Tramblay} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}。顺便在那里买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Brightwater Lake until your Fishing skill reaches 75. You will catch about 30 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 20 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, plus some {i:6299:inv_misc_fish_28:Sickly Looking Fish} and junk."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在明水湖钓鱼，直到钓鱼技能达到 75。你会钓到大约 30 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 20 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}，外加一些 {i:6299:inv_misc_fish_28:Sickly Looking Fish} 和垃圾物品。",
  ["Learn Journeyman Fishing from {n:0::Clyde Kellen}, it requires level 10."] = "向 {n:0::Clyde Kellen} 学习熟练钓鱼，需要 10 级。",
  ["Brightwater Lake east of Brill in Tirisfal Glades, where to fish from 1 to 75"] = "提瑞斯法林地布瑞尔东边的明水湖，1 到 75 的钓鱼地点",
  ["If you haven't learned Fishing yet, learn it from {n:0::Fenn Fairweather} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar."] = "如果你还没学钓鱼，去 Shen'dar Village 找 {n:0::Fenn Fairweather} 或去 Valanaar 找 {n:0::Baelann Swiftcurrent} 学习。",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Belandiel Farflight} in Shen'dar Village or {n:0::Baelann Swiftcurrent} in Valanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在 Shen'dar Village 的 {n:0::Belandiel Farflight} 或 Valanaar 的 {n:0::Baelann Swiftcurrent} 处购买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in any lake or river on Zephras Isle until your Fishing skill reaches 75, for example next to the Fishing trainers in Shen'dar Village and Valanaar. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}. Keep all the fish you catch."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在 Zephras Isle 的任意湖泊或河流钓鱼，直到钓鱼技能达到 75，例如 Shen'dar Village 和 Valanaar 的钓鱼训练师旁边。你会钓到大约 45 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。钓到的鱼全部留着。",
  ["Learn Journeyman Fishing from {n:0::Fenn Fairweather} or {n:0::Baelann Swiftcurrent}, it requires level 10."] = "向 {n:0::Fenn Fairweather} 或 {n:0::Baelann Swiftcurrent} 学习熟练钓鱼，需要 10 级。",
  ["When you get to Thunder Bluff, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Sewa Mistrunner} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Naal Mistrunner}. They stand next to each other."] = "到了雷霆崖后，在 {n:0::Sewa Mistrunner} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}，在 {n:0::Naal Mistrunner} 处购买 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。他们站在一起。",
  ["The water at Shen'dar Village and Valanaar on Zephras Isle, where to fish from 1 to 75"] = "Zephras Isle 上 Shen'dar Village 和 Valanaar 的水域，1 到 75 的钓鱼地点",
  ["If you can choose, {b}level Fishing in Elwynn Forest{/b}, because everything is close together there. {n:0::Tharynn Bouden} in Goldshire sells both recipes and the pole, and the Fishing trainer stands at Crystal Lake. Stormwind City, where you fish after 75, is right next to it."] = "如果可以选择，{b}在艾尔文森林练钓鱼{/b}，因为那里所有东西都离得很近。闪金镇的 {n:0::Tharynn Bouden} 同时出售两个配方和鱼竿，钓鱼训练师就站在水晶湖边。75 以后钓鱼的暴风城就在旁边。",
  ["If you haven't learned Fishing yet, learn it from {n:0::Lee Brown} at Crystal Lake."] = "如果你还没学钓鱼，去水晶湖找 {n:0::Lee Brown} 学习。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在闪金镇的 {n:0::Tharynn Bouden} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。顺便在那里买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Crystal Lake, east of Goldshire, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在闪金镇东边的水晶湖钓鱼，直到钓鱼技能达到 75。你会钓到大约 45 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Lee Brown}, it requires level 10."] = "向 {n:0::Lee Brown} 学习熟练钓鱼，需要 10 级。",
  ["Crystal Lake east of Goldshire in Elwynn Forest, where to fish from 1 to 75"] = "艾尔文森林闪金镇东边的水晶湖，1 到 75 的钓鱼地点",
  ["If you haven't learned Fishing yet, learn it from {n:0::Paxton Ganter} at Iceflow Lake."] = "如果你还没学钓鱼，去冰流湖找 {n:0::Paxton Ganter} 学习。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} from {n:0::Gretta Ganter} at Iceflow Lake. Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} there too. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在冰流湖的 {n:0::Gretta Ganter} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}。顺便在那里买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Iceflow Lake until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在冰流湖钓鱼，直到钓鱼技能达到 75。你会钓到大约 45 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Paxton Ganter}, it requires level 10."] = "向 {n:0::Paxton Ganter} 学习熟练钓鱼，需要 10 级。",
  ["Iceflow Lake in Dun Morogh, where to fish from 1 to 75"] = "丹莫罗的冰流湖，1 到 75 的钓鱼地点",
  ["Learn Fishing from {n:0::Astaia} in Darnassus. There is no Fishing trainer in Dolanaar."] = "去达纳苏斯找 {n:0::Astaia} 学习钓鱼。多兰纳尔没有钓鱼训练师。",
  ["Buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Nyoma} in Dolanaar."] = "在多兰纳尔的 {n:0::Nyoma} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a {i:6529:inv_misc_orb_03:Shiny Bauble} from {n:0::Narret Shadowgrove} in Dolanaar. (Buy any {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you see and keep it for later.)"] = "在多兰纳尔的 {n:0::Narret Shadowgrove} 处购买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和一个 {i:6529:inv_misc_orb_03:Shiny Bauble}。（看到 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} 就买下来，留着以后用。）",
  ["Equip your fishing pole, attach a {i:6529:inv_misc_orb_03:Shiny Bauble}, and fish in Lake Al'Ameth, south of Dolanaar, until your Fishing skill reaches 75. You will catch about 45 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} and 30 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}."] = "装备鱼竿，装上 {i:6529:inv_misc_orb_03:Shiny Bauble}，在多兰纳尔南边的奥拉密斯湖钓鱼，直到钓鱼技能达到 75。你会钓到大约 45 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 和 30 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}。",
  ["Learn Journeyman Fishing from {n:0::Astaia} in Darnassus, it requires level 10."] = "向达纳苏斯的 {n:0::Astaia} 学习熟练钓鱼，需要 10 级。",
  ["Lake Al'Ameth south of Dolanaar in Teldrassil, where to fish from 1 to 75"] = "泰达希尔多兰纳尔南边的奥拉密斯湖，1 到 75 的钓鱼地点",
  ["When you get to Stormwind City, buy {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} from {n:0::Tharynn Bouden} in Goldshire, right outside the city."] = "到了暴风城后，在城外闪金镇的 {n:0::Tharynn Bouden} 处购买 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} 和 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}。",
  ["Fishing (75-130) and Cooking (1-100)"] = "钓鱼 (75-130) 和烹饪 (1-100)",
  ["Fishing"] = "钓鱼",
  ["Fish in the capital city closest to you until your Fishing skill reaches 130. From 75 no fish gets away in any of them. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "在离你最近的主城钓鱼，直到钓鱼技能达到 130。从 75 开始，在任何一座主城都不会脱钩。你应该会钓到大约 20 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}、60 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 30 条 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["{b}Thunder Bluff:{/b} the pond near the Auction House."] = "{b}雷霆崖：{/b}拍卖行附近的池塘。",
  ["{b}Undercity:{/b} the canals. About a third of what you catch here is junk, so you get fewer fish."] = "{b}幽暗城：{/b}运河。这里钓到的东西大约三分之一是垃圾，所以鱼会少一些。",
  ["{b}Orgrimmar:{/b} the pond in the Valley of Honor, where the Fishing trainer stands."] = "{b}奥格瑞玛：{/b}荣誉谷里的池塘，钓鱼训练师就站在那里。",
  ["Recipes to buy"] = "要购买的配方",
  ["Buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Ronald Burch} in Undercity, you need it in the next part."] = "在雷霆崖的 {n:0::Naal Mistrunner} 或幽暗城的 {n:0::Ronald Burch} 处购买 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}，下一部分要用到。",
  ["If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Naal Mistrunner} in Thunder Bluff or {n:0::Lizbeth Cromwell} in Undercity."] = "如果你还没有 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，在雷霆崖的 {n:0::Naal Mistrunner} 或幽暗城的 {n:0::Lizbeth Cromwell} 处购买。",
  ["Nobody sells them in Orgrimmar, so buy them on the Auction House or in Thunder Bluff."] = "奥格瑞玛没有人卖这些，所以请在拍卖行或雷霆崖购买。",
  ["Cooking"] = "烹饪",
  ["If you haven't learned Cooking yet, learn it from {n:0::Aska Mistrunner} in Thunder Bluff, {n:0::Eunice Burch} in Undercity or {n:0::Zamja} in Orgrimmar. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. If you caught {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel} in your starting zone, learn {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel} and cook them into {s:7752:inv_misc_fish_24:Slitherskin Mackerel} instead. This should take your Cooking skill to 50."] = "如果你还没学烹饪，去雷霆崖的 {n:0::Aska Mistrunner}、幽暗城的 {n:0::Eunice Burch} 或奥格瑞玛的 {n:0::Zamja} 处学习。然后学会 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}，把所有 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 烹饪成 {s:7751:inv_misc_fish_07:Brilliant Smallfish}。如果你在新手区钓到的是 {i:6303:inv_misc_fish_24:Raw Slitherskin Mackerel}，就改为学会 {i:6326:inv_scroll_03:Recipe: Slitherskin Mackerel}，把它们烹饪成 {s:7752:inv_misc_fish_24:Slitherskin Mackerel}。这样烹饪技能应该能到 50。",
  ["If you are a few points short of 50, catch and cook a few more."] = "如果离 50 还差几点，就再钓几条烹饪。",
  ["Learn Journeyman Cooking from the same trainer. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "向同一位训练师学习熟练烹饪。然后学会 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，把所有 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 烹饪成 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}。你的烹饪技能应该会超过 100。",
  ["Don't worry if you don't reach 100 Cooking with Longjaw Mud Snapper, you will catch more Raw Longjaw Mud Snapper later."] = "如果用长嘴泥鳅没能把烹饪升到 100 也不用担心，之后你还会钓到更多生长嘴泥鳅。",
  ["Fish in the canals of Stormwind City until your skill reaches 130. You should catch about 20 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}, 60 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper}, and 30 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "在暴风城的运河钓鱼，直到技能达到 130。你应该会钓到大约 20 条 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish}、60 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 30 条 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["Find {n:0::Catherine Leland} in Stormwind City and buy {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}. If you don't have {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} yet, buy it from {n:0::Tharynn Bouden} in Goldshire."] = "在暴风城找到 {n:0::Catherine Leland}，购买 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}。如果你还没有 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，在闪金镇的 {n:0::Tharynn Bouden} 处购买。",
  ["You should also find {n:0::Ben Trias} and buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from him. You will need these later for the Artisan Cooking quest."] = "你还应该找到 {n:0::Ben Trias}，从他那里买 20 个 {i:8932:inv_misc_food_37:Alterac Swiss}。之后做大师烹饪任务时会用到。",
  ["Learn Cooking from {n:0::Stephen Ryback} if you haven't yet. Then learn {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish} and cook all your {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} into {s:7751:inv_misc_fish_07:Brilliant Smallfish}. This should take your Cooking skill to 50."] = "如果还没学烹饪，去找 {n:0::Stephen Ryback} 学习。然后学会 {i:6325:inv_scroll_03:Recipe: Brilliant Smallfish}，把所有 {i:6291:inv_misc_fish_08:Raw Brilliant Smallfish} 烹饪成 {s:7751:inv_misc_fish_07:Brilliant Smallfish}。这样烹饪技能应该能到 50。",
  ["Learn Journeyman Cooking from {n:0::Stephen Ryback} in Stormwind City. Then learn {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper} and cook all your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}. Your Cooking skill should go above 100."] = "向暴风城的 {n:0::Stephen Ryback} 学习熟练烹饪。然后学会 {i:6328:inv_scroll_03:Recipe: Longjaw Mud Snapper}，把所有 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 烹饪成 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}。你的烹饪技能应该会超过 100。",
  ["Fishing (130-205) and Cooking (100-175)"] = "钓鱼 (130-205) 和烹饪 (100-175)",
  ["Expert Fishing needs {b}level 20{/b} and {b}Fishing 125{/b}, Expert Cooking needs {b}Cooking 125{/b}."] = "专家钓鱼需要 {b}20 级{/b} 和 {b}钓鱼 125{/b}，专家烹饪需要 {b}烹饪 125{/b}。",
  ["Booty Bay"] = "藏宝海湾",
  ["Go to Ratchet in The Barrens and take the boat to Booty Bay in Stranglethorn Vale."] = "前往贫瘠之地的棘齿城，乘船去荆棘谷的藏宝海湾。",
  ["Find {n:0::Old Man Heming} in Booty Bay, buy {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} from him and read it."] = "在藏宝海湾找到 {n:0::Old Man Heming}，从他那里买 {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} 并阅读。",
  ["Find {n:0::Kelsey Yance} and buy these two recipes: {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}, {i:13941:inv_scroll_03:Recipe: Filet of Redgill}."] = "找到 {n:0::Kelsey Yance}，购买这两个配方：{i:17062:inv_scroll_03:Recipe: Mithril Head Trout}、{i:13941:inv_scroll_03:Recipe: Filet of Redgill}。",
  ["Go back to The Barrens, then fly from Ratchet to Sun Rock Retreat in Stonetalon Mountains and buy 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Kulwia}. You need 2 until 150, keep the other 5 for later."] = "回到贫瘠之地，然后从棘齿城飞到石爪山脉的烈日石居，在 {n:0::Kulwia} 处买 7 个 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。到 150 之前需要 2 个，剩下 5 个留着以后用。",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "装上 {i:6530:inv_misc_monstertail_03:Nightcrawler}，在开阔水域钓鱼，直到钓鱼技能达到 205。你会钓到大约 95 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 145 条 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["Fly to Shadowprey Village in Desolace."] = "飞往凄凉之地的葬影村。",
  ["Find {n:0::Wulan} and buy the {i:16072:inv_misc_book_08:Expert Cookbook}. He is on the top floor of the eastern-most building in the village."] = "找到 {n:0::Wulan}，购买 {i:16072:inv_misc_book_08:Expert Cookbook}。他在村子最东边那栋建筑的顶层。",
  ["Buy 20 {i:8932:inv_misc_food_37:Alterac Swiss} from {n:0::Innkeeper Sikewa}. You will need them for the Artisan Cooking quest."] = "在 {n:0::Innkeeper Sikewa} 处买 20 个 {i:8932:inv_misc_food_37:Alterac Swiss}。做大师烹饪任务时会用到。",
  ["Leveling Cooking to 175"] = "把烹饪练到 175",
  ["Cook your {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} into {s:7753:inv_misc_fish_32:Longjaw Mud Snapper} if your Cooking skill is still below 100."] = "如果你的烹饪技能仍低于 100，就把 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 烹饪成 {s:7753:inv_misc_fish_32:Longjaw Mud Snapper}。",
  ["{b}Read the {i:16072:inv_misc_book_08:Expert Cookbook} as soon as you reach 125{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 150 and keep cooking for nothing."] = "{b}一到 125 就阅读 {i:16072:inv_misc_book_08:Expert Cookbook}{/b}，尤其是如果你挂机烹饪的话。没有它，到 150 就不再获得技能点，只会白白烹饪。",
  ["Learn {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish} and cook all your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}. Your Cooking skill will hopefully get close to 175."] = "学会 {i:6330:inv_scroll_03:Recipe: Bristle Whisker Catfish}，把所有 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 烹饪成 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}。你的烹饪技能有望接近 175。",
  ["Don't worry if you don't reach 175 Cooking with Bristle Whisker Catfish, you will catch more Raw Bristle Whisker Catfish later."] = "如果用刺须鲶鱼没能把烹饪升到 175 也不用担心，之后你还会钓到更多生刺须鲶鱼。",
  ["Go to Booty Bay in Stranglethorn Vale."] = "前往荆棘谷的藏宝海湾。",
  ["Go to The Barrens, then fly from Ratchet to Astranaar in Ashenvale. Ride south-east to Mystral Lake and buy the {i:16072:inv_misc_book_08:Expert Cookbook} and 7 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0::Shandrina}. You need 2 until 150, keep the other 5 for later."] = "前往贫瘠之地，然后从棘齿城飞到灰谷的阿斯特兰纳。往东南骑到密斯特拉湖，在 {n:0::Shandrina} 处购买 {i:16072:inv_misc_book_08:Expert Cookbook} 和 7 个 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。到 150 之前需要 2 个，剩下 5 个留着以后用。",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the open water of Mystral Lake until your Fishing skill reaches 205. You will catch about 95 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} and 145 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}."] = "装上 {i:6530:inv_misc_monstertail_03:Nightcrawler}，在密斯特拉湖的开阔水域钓鱼，直到钓鱼技能达到 205。你会钓到大约 95 条 {i:6289:inv_misc_fish_32:Raw Longjaw Mud Snapper} 和 145 条 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}。",
  ["Artisan Fishing Quest"] = "大师钓鱼任务",
  ["If you have no {i:6530:inv_misc_monstertail_03:Nightcrawlers} left, buy 5 from {n:0::Kilxx} in The Barrens or {n:0:alliance:Helenia Olden} in Dustwallow Marsh."] = "如果你的 {i:6530:inv_misc_monstertail_03:Nightcrawlers} 用完了，在贫瘠之地的 {n:0::Kilxx} 或尘泥沼泽的 {n:0:alliance:Helenia Olden} 处买 5 个。",
  ["Go to Dustwallow Marsh and {b}fish anywhere in the swamp until your skill reaches 225{/b}. {b}Don't fish in the ocean.{/b} Keep a {i:6530:inv_misc_monstertail_03:Nightcrawler} on your pole until 225, otherwise a few fish get away."] = "前往尘泥沼泽，{b}在沼泽里任意地方钓鱼直到技能达到 225{/b}。{b}不要在海里钓。{/b}到 225 之前鱼竿上一直装着 {i:6530:inv_misc_monstertail_03:Nightcrawler}，否则会有几条鱼脱钩。",
  ["Find {n:0::Nat Pagle} and accept the quest {q:6607::Nat Pagle, Angler Extreme}. It requires {b}level 35{/b} and {b}Fishing 225{/b}, and you need it to learn Artisan Fishing."] = "找到 {n:0::Nat Pagle}，接受任务 {q:6607::Nat Pagle, Angler Extreme}。它需要 {b}35 级{/b} 和 {b}钓鱼 225{/b}，学习大师钓鱼必须完成它。",
  ["Tidefury Cove, Dustwallow Marsh"] = "尘泥沼泽，怒潮湾",
  ["To complete the quest you have to catch 4 quest fish in four different zones:"] = "要完成任务，你必须在四个不同区域钓到 4 条任务鱼：",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas (attach the {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor} you kept, or {i:6532:inv_misc_gem_variety_02:Bright Baubles} from {n:0::Sheendra Tallgrass} / {n:0::Vivianna} in Feralas, otherwise most of them get away)"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - 菲拉斯（装上你留着的 {i:6533:inv_misc_food_26:Aquadynamic Fish Attractor}，或者菲拉斯 {n:0::Sheendra Tallgrass} / {n:0::Vivianna} 出售的 {i:6532:inv_misc_gem_variety_02:Bright Baubles}，否则大部分会脱钩）",
  ["{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - Swamp of Sorrows"] = "{i:16970:inv_misc_fish_21:Misty Reed Mahi Mahi} - 悲伤沼泽",
  ["{i:16968:inv_misc_fish_32:Sar'theris Striker} - Desolace"] = "{i:16968:inv_misc_fish_32:Sar'theris Striker} - 凄凉之地",
  ["{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - Stranglethorn Vale"] = "{i:16969:inv_misc_fish_08:Savage Coast Blue Sailfin} - 荆棘谷",
  ["Nat Pagle, Angler Extreme Quest Fishes"] = "“极限钓手纳特·帕格”任务鱼",
  ["Where to catch the four Nat Pagle quest fish"] = "四条纳特·帕格任务鱼的钓取地点",
  ["Leveling Fishing to 255 and Cooking to 225"] = "把钓鱼练到 255，烹饪练到 225",
  ["After you completed the quest, {b}keep fishing in the swamp in Dustwallow Marsh until your Fishing skill reaches 255.{/b} {b}Don't fish in the ocean{/b}, because there you catch Raw Rockscale Cod instead of the Raw Mithril Head Trout you cook next."] = "完成任务后，{b}继续在尘泥沼泽的沼泽里钓鱼，直到钓鱼技能达到 255。{/b}{b}不要在海里钓{/b}，因为在海里钓到的是生石鳞鳕鱼，而不是你接下来要烹饪的生秘银头鳟鱼。",
  ["Go back to Brackenwall Village (Horde) / Theramore Isle (Alliance) to cook your fish, or put down a campfire if you have one."] = "回到蕨墙村（部落）/ 塞拉摩岛（联盟）烹饪你的鱼，如果你有营火也可以就地放一个。",
  ["Cook your {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} into {s:7755:inv_misc_fish_30:Bristle Whisker Catfish} if your Cooking skill is still below 175."] = "如果你的烹饪技能仍低于 175，就把 {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} 烹饪成 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}。",
  ["Learn {i:17062:inv_scroll_03:Recipe: Mithril Head Trout} and cook your {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 225. Keep the rest, you cook them after the Artisan Cooking quest."] = "学会 {i:17062:inv_scroll_03:Recipe: Mithril Head Trout}，把 {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} 烹饪成 {s:20916:inv_misc_fish_02:Mithril Headed Trout} 直到 225。剩下的留着，完成大师烹饪任务后再烹饪。",
  ["Artisan Cooking Quest"] = "大师烹饪任务",
  ["Fly to Gadgetzan in Tanaris and pick up the quest {q:6610::Clamlette Surprise} from {n:0::Dirge Quikcleave}. The reward is Artisan Cooking. The quest requires {b}level 35{/b} and {b}Cooking 225{/b}. You will need these to complete the quest:"] = "飞到塔纳利斯的加基森，从 {n:0::Dirge Quikcleave} 处接任务 {q:6610::Clamlette Surprise}。奖励是大师烹饪。任务需要 {b}35 级{/b} 和 {b}烹饪 225{/b}。完成任务需要以下物品：",
  ["12x {i:12207:inv_egg_03:Giant Egg} - dropped by the {n:5428::Rocs}, {n:5429::Fire Rocs} and {n:5430::Searing Rocs} in Tanaris."] = "12x {i:12207:inv_egg_03:Giant Egg} - 由塔纳利斯的 {n:5428::Rocs}、{n:5429::Fire Rocs} 和 {n:5430::Searing Rocs} 掉落。",
  ["10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - from Big-mouth Clams, dropped by {n:14123::Steeljaw Snappers} and {n:5431::Surf Gliders} in Tanaris."] = "10x {i:7974:inv_misc_food_51:Zesty Clam Meat} - 来自大嘴蚌，由塔纳利斯的 {n:14123::Steeljaw Snappers} 和 {n:5431::Surf Gliders} 掉落。",
  ["20x {i:8932:inv_misc_food_37:Alterac Swiss} - you bought these earlier."] = "20x {i:8932:inv_misc_food_37:Alterac Swiss} - 你之前已经买好了。",
  ["Find {n:0::Gikkix} at Steamwheedle Port in Tanaris and buy {i:13945:inv_scroll_03:Recipe: Nightfin Soup}."] = "在塔纳利斯热砂港找到 {n:0::Gikkix}，购买 {i:13945:inv_scroll_03:Recipe: Nightfin Soup}。",
  ["Fishing to 300 in Feralas"] = "在菲拉斯把钓鱼练到 300",
  ["Fly to Camp Mojache (Horde) / Feathermoon Stronghold (Alliance) in Feralas."] = "飞到菲拉斯的莫沙彻营地（部落）/ 羽月要塞（联盟）。",
  ["Buy 12 {i:6530:inv_misc_monstertail_03:Nightcrawlers} from {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna}."] = "在 {n:0:horde:Sheendra Tallgrass} / {n:0:alliance:Vivianna} 处买 12 个 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。",
  ["Attach a {i:6530:inv_misc_monstertail_03:Nightcrawler} and fish in the marked lake until you reach Fishing 300, use a new one every 10 minutes. Any other lake or river in Feralas works too, {b}except Jademir Lake{/b}."] = "装上 {i:6530:inv_misc_monstertail_03:Nightcrawler}，在标记的湖里钓鱼直到钓鱼 300，每 10 分钟换一个新的。菲拉斯的其他湖泊或河流也可以，{b}加德米尔湖除外{/b}。",
  ["Where to fish in Feralas from 255 to 300"] = "菲拉斯 255 到 300 的钓鱼地点",
  ["Leveling Cooking to 300"] = "把烹饪练到 300",
  ["Cook your remaining {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} into {s:20916:inv_misc_fish_02:Mithril Headed Trout} until 250."] = "把剩下的 {i:8365:inv_misc_fish_02:Raw Mithril Head Trout} 烹饪成 {s:20916:inv_misc_fish_02:Mithril Headed Trout} 直到 250。",
  ["Learn {i:13941:inv_scroll_03:Recipe: Filet of Redgill} and cook your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} until 285."] = "学会 {i:13941:inv_scroll_03:Recipe: Filet of Redgill}，把 {i:13758:inv_misc_fish_06:Raw Redgill} 烹饪成 {s:18241:inv_misc_fish_06:Filet of Redgill} 直到 285。",
  ["Learn {i:13945:inv_scroll_03:Recipe: Nightfin Soup} and cook all your {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} into {s:18243:inv_drink_17:Nightfin Soup}. You also need a {i:159:inv_drink_07:Refreshing Spring Water} for each soup, buy 20 from the innkeeper."] = "学会 {i:13945:inv_scroll_03:Recipe: Nightfin Soup}，把所有 {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} 烹饪成 {s:18243:inv_drink_17:Nightfin Soup}。每份汤还需要一瓶 {i:159:inv_drink_07:Refreshing Spring Water}，从旅店老板那里买 20 瓶。",
  ["{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} don't bite in the afternoon (12:00-18:00 game time). If you fished in the afternoon, you will probably not have enough, so cook the rest of your {i:13758:inv_misc_fish_06:Raw Redgill} into {s:18241:inv_misc_fish_06:Filet of Redgill} too, you might reach 300 with them."] = "{i:13759:inv_misc_fish_23:Raw Nightfin Snapper} 在下午（游戏时间 12:00-18:00）不上钩。如果你是在下午钓的鱼，可能会不够，所以把剩下的 {i:13758:inv_misc_fish_06:Raw Redgill} 也烹饪成 {s:18241:inv_misc_fish_06:Filet of Redgill}，说不定就能到 300。",
  ["If you still don't reach 300, fish a bit more outside the afternoon, or buy a few {i:13759:inv_misc_fish_23:Raw Nightfin Snapper} on the Auction House."] = "如果还是到不了 300，就在下午以外的时间再钓一会儿，或者在拍卖行买几条 {i:13759:inv_misc_fish_23:Raw Nightfin Snapper}。",
  ["This WoW Forever Cooking leveling guide will show you the fastest way to level your Cooking skill from 1 to 300 as cheaply as possible. You will also find every trainer location, how the campfire works in Forever and where to train Cooking past 150 and 225."] = "这份 WoW Forever 烹饪升级指南将告诉你以尽可能低的成本把烹饪技能从 1 升到 300 的最快方法。你还能找到所有训练师的位置、Forever 中营火的使用方式，以及在 150 和 225 之后去哪里继续学习烹饪。",
  ["Cooking doesn't take up one of your two profession slots, so every character can learn it. Most of the recipes below only need the meat or fish that drops while you level, so the guide lists a few recipes for every skill range and you can make the one you have the ingredients for. If you also want to level Fishing but haven't leveled it yet, use my Fishing and Cooking leveling guide instead:"] = "烹饪不占用你的两个专业栏位，所以每个角色都能学。下面的大多数配方只需要你升级时掉落的肉或鱼，所以本指南为每个技能区间列出了几个配方，你有哪个的材料就做哪个。如果你也想练钓鱼但还没练，请改用我的钓鱼和烹饪升级指南：",
  ["You need level 35 to go past 225, so I split the list in two. Buy this part first."] = "超过 225 需要 35 级，所以我把清单分成了两部分。先买这一部分。",
  ["The Giant Eggs and the Zesty Clam Meat are for the Artisan Cooking quest."] = "巨蛋和美味蚌肉是用于大师烹饪任务的。",
  ["Cooking Trainer Locations"] = "烹饪训练师位置",
  ["Apprentice Cooking has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman Cooking, so you don't have to find a different trainer at 50."] = "学徒级烹饪没有等级要求，所以新建的角色也能学。每位训练师也都教熟练烹饪，所以到 50 时不用另找训练师。",
  ["Orgrimmar: {n:0:horde:Zamja}"] = "奥格瑞玛：{n:0:horde:Zamja}",
  ["Undercity: {n:0:horde:Eunice Burch}"] = "幽暗城：{n:0:horde:Eunice Burch}",
  ["Thunder Bluff: {n:0:horde:Aska Mistrunner}"] = "雷霆崖：{n:0:horde:Aska Mistrunner}",
  ["Every starting zone has a Cooking trainer, most of them are inside the inn."] = "每个新手区都有烹饪训练师，大多在旅店里。",
  ["{n:0:horde:Cook Torka} in Razor Hill"] = "剃刀岭的 {n:0:horde:Cook Torka}",
  ["{n:0:horde:Pyall Silentstride} inside the big tent in Bloodhoof Village"] = "血蹄村大帐篷里的 {n:0:horde:Pyall Silentstride}",
  ["{n:0:horde:William Pickman} inside the inn in Brill"] = "布瑞尔旅店里的 {n:0:horde:William Pickman}",
  ["{n:0::Nyalah Brightfire} in Valanaar, {n:0::Zerril Softbreeze} in Shen'dar Village"] = "Valanaar 的 {n:0::Nyalah Brightfire}，Shen'dar Village 的 {n:0::Zerril Softbreeze}",
  ["Stormwind City: {n:0:alliance:Stephen Ryback}"] = "暴风城：{n:0:alliance:Stephen Ryback}",
  ["Ironforge: {n:0:alliance:Daryl Riknussun}"] = "铁炉堡：{n:0:alliance:Daryl Riknussun}",
  ["Darnassus: {n:0:alliance:Alegorn}"] = "达纳苏斯：{n:0:alliance:Alegorn}",
  ["{n:0:alliance:Tomas} in the kitchen of the inn in Goldshire"] = "闪金镇旅店厨房里的 {n:0:alliance:Tomas}",
  ["{n:0:alliance:Gremlock Pilsnor} in the Thunderbrew Distillery in Kharanos"] = "卡拉诺斯雷酒酿制厂里的 {n:0:alliance:Gremlock Pilsnor}",
  ["{n:0:alliance:Zarrin} in Dolanaar"] = "多兰纳尔的 {n:0:alliance:Zarrin}",
  ["You can find every Cooking trainer for Horde and Alliance on my WoW Forever Cooking Trainers page."] = "你可以在我的 WoW Forever 烹饪训练师页面找到部落和联盟的所有烹饪训练师。",
  ["Campfire"] = "营火",
  ["You need a campfire to cook. There is often one burning next to the Cooking trainer, so look around before you make your own."] = "烹饪需要营火。烹饪训练师旁边常常有一堆正在燃烧的火，所以自己生火前先看看周围。",
  ["In Forever the campfire is an item. You learn the {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit} together with Cooking and place the fire from your bags, so you can make a stack of kits in advance. Other players can add their own camp items to your fire, you can read about the whole camping system in my WoW Forever Camping Guide."] = "在 Forever 中营火是一件物品。你学会烹饪时会同时学会 {s:1229737:inv_camelot_camping_welcomingcampfire:Basic Campfire Kit}，并从背包中放置营火，所以你可以提前做好一叠营火包。其他玩家也可以把自己的露营物品加到你的营火上，整个露营系统的介绍请看我的 WoW Forever 露营指南。",
  ["To craft the kits you need {i:4470:inv_tradeskillitem_01:Simple Wood} and a {i:4471:inv_stone_11:Flint and Tinder}. The Flint and Tinder is only for crafting the kits, you don't need it to place the fire. Open your faction below to see who sells them near your trainer:"] = "制作营火包需要 {i:4470:inv_tradeskillitem_01:Simple Wood} 和 {i:4471:inv_stone_11:Flint and Tinder}。火石和火绒只用于制作营火包，放置营火时不需要。展开下面你的阵营，查看训练师附近谁在出售：",
  ["{n:0:horde:Xen'to}, next to the trainer"] = "{n:0:horde:Xen'to}，在训练师旁边",
  ["{n:0:horde:Ronald Burch}, next to the trainer"] = "{n:0:horde:Ronald Burch}，在训练师旁边",
  ["{n:0:horde:Naal Mistrunner}, next to the trainer"] = "{n:0:horde:Naal Mistrunner}，在训练师旁边",
  ["{n:0:horde:Jark} in the Razor Hill barracks"] = "剃刀岭兵营里的 {n:0:horde:Jark}",
  ["{n:0:horde:Moorat Longstride} in Bloodhoof Village"] = "血蹄村的 {n:0:horde:Moorat Longstride}",
  ["{n:0:horde:Mrs. Winters} in Brill"] = "布瑞尔的 {n:0:horde:Mrs. Winters}",
  ["{n:0::Antelariaa Cloudgaze} in Valanaar {n:0::Zerril Softbreeze}, the Cooking trainer in Shen'dar Village"] = "Valanaar 的 {n:0::Antelariaa Cloudgaze} {n:0::Zerril Softbreeze}，Shen'dar Village 的烹饪训练师",
  ["{n:0:alliance:Erika Tate}, next to the trainer"] = "{n:0:alliance:Erika Tate}，在训练师旁边",
  ["{n:0:alliance:Emrul Riknussun}, next to the trainer"] = "{n:0:alliance:Emrul Riknussun}，在训练师旁边",
  ["{n:0:alliance:Fyldan}, next to the trainer"] = "{n:0:alliance:Fyldan}，在训练师旁边",
  ["{n:0:alliance:Brog Hamfist} in Goldshire"] = "闪金镇的 {n:0:alliance:Brog Hamfist}",
  ["{n:0:alliance:Kreg Bilmn} in the Thunderbrew Distillery"] = "雷酒酿制厂里的 {n:0:alliance:Kreg Bilmn}",
  ["{n:0:alliance:Nyoma} in Dolanaar"] = "多兰纳尔的 {n:0:alliance:Nyoma}",
  ["Apprentice Cooking (1-50)"] = "学徒烹饪 (1-50)",
  ["{b}These are sold by Cooking Supply vendors near your trainer, don't buy them from the Auction House:{/b}"] = "{b}这些由训练师附近的烹饪供应商出售，不要在拍卖行买：{/b}",
  ["Make around 55 from one of these recipes. The two fish are usually the cheapest."] = "从以下配方中任选一个，做大约 55 个。两种鱼通常最便宜。",
  ["Food"] = "食物",
  ["Ingredients"] = "原料",
  ["Recipe Source"] = "配方来源",
  ["Mulgore: {n:0:horde:Harn Longcast} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Tirisfal Glades: {n:0:horde:Martine Tramblay} Undercity: {n:0:horde:Lizbeth Cromwell} Dun Morogh: {n:0:alliance:Gretta Ganter} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Loch Modan: {n:0:alliance:Khara Deepwater} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nyoma}"] = "莫高雷：{n:0:horde:Harn Longcast} 雷霆崖：{n:0:horde:Sewa Mistrunner} 提瑞斯法林地：{n:0:horde:Martine Tramblay} 幽暗城：{n:0:horde:Lizbeth Cromwell} 丹莫罗：{n:0:alliance:Gretta Ganter} 艾尔文森林：{n:0:alliance:Tharynn Bouden} 洛克莫丹：{n:0:alliance:Khara Deepwater} 暴风城：{n:0:alliance:Catherine Leland} 泰达希尔：{n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Tirisfal Glades: {n:0:horde:Martine Tramblay} Ironforge: {n:0:alliance:Tansy Puddlefizz} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone}"] = "杜隆塔尔：{n:0:horde:Zansoa} 提瑞斯法林地：{n:0:horde:Martine Tramblay} 铁炉堡：{n:0:alliance:Tansy Puddlefizz} 泰达希尔：{n:0:alliance:Nessa Shadowsong} 西部荒野：{n:0:alliance:Kriggon Talsone}",
  ["Trainer"] = "训练师",
  ["(Horde only) Make {s:15935:inv_misc_food_46:Crispy Bat Wing} if you have some {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}. The recipe is sold by {n:0:horde:Abigail Shiel} in Tirisfal Glades."] = "（仅限部落）如果你有一些 {i:12223:inv_misc_pelt_bear_ruin_05:Meaty Bat Wing}，就做 {s:15935:inv_misc_food_46:Crispy Bat Wing}。配方由提瑞斯法林地的 {n:0:horde:Abigail Shiel} 出售。",
  ["(Horde only) Make {s:6413:inv_misc_food_10:Scorpid Surprise} if you have some {i:5466:spell_nature_nullifypoison:Scorpid Stinger}. The recipe is sold by {n:0:horde:Grimtak} in Durotar."] = "（仅限部落）如果你有一些 {i:5466:spell_nature_nullifypoison:Scorpid Stinger}，就做 {s:6413:inv_misc_food_10:Scorpid Surprise}。配方由杜隆塔尔的 {n:0:horde:Grimtak} 出售。",
  ["(Alliance only) Make {s:6412:inv_misc_food_68:Kaldorei Spider Kabob} if you have some {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}. The recipe is a reward from {q:4161::Recipe of the Kaldorei}. You can get the quest from {n:0:alliance:Zarrin} in Teldrassil."] = "（仅限联盟）如果你有一些 {i:5465:inv_misc_monsterspidercarapace_01:Small Spider Leg}，就做 {s:6412:inv_misc_food_68:Kaldorei Spider Kabob}。配方是 {q:4161::Recipe of the Kaldorei} 任务的奖励。你可以在泰达希尔的 {n:0:alliance:Zarrin} 处接到这个任务。",
  ["Journeyman Cooking (50-150)"] = "熟练烹饪 (50-150)",
  ["{b}Visit your trainer again and learn Journeyman Cooking{/b}, it requires Cooking 50."] = "{b}再去找训练师学习熟练烹饪{/b}，需要烹饪 50。",
  ["{b}Make sure to learn Journeyman Cooking before you start the next part{/b}, especially if you go AFK while cooking. Without it you stop getting skill points at 75 and keep cooking for nothing."] = "{b}开始下一部分之前一定要学会熟练烹饪{/b}，尤其是如果你挂机烹饪的话。没有它，到 75 就不再获得技能点，只会白白烹饪。",
  ["Make around 55 from any of the recipes below. The two fish are usually the cheapest. {s:8607:inv_misc_food_13:Smoked Bear Meat} turns yellow sooner than the rest, so make more of it, or cook it first if you have more than one type of meat."] = "从下面任意配方中做大约 55 个。两种鱼通常最便宜。{s:8607:inv_misc_food_13:Smoked Bear Meat} 比其他的更早变黄，所以要多做一些，或者如果你有不止一种肉，就先烹饪它。",
  ["Mulgore: {n:0:horde:Harn Longcast} Silverpine Forest: {n:0:horde:Killian Sanatha} Thunder Bluff: {n:0:horde:Naal Mistrunner} Undercity: {n:0:horde:Lizbeth Cromwell} Elwynn Forest: {n:0:alliance:Tharynn Bouden} Ironforge: {n:0:alliance:Tansy Puddlefizz} Loch Modan: {n:0:alliance:Khara Deepwater} Teldrassil: {n:0:alliance:Nyoma}"] = "莫高雷：{n:0:horde:Harn Longcast} 银松森林：{n:0:horde:Killian Sanatha} 雷霆崖：{n:0:horde:Naal Mistrunner} 幽暗城：{n:0:horde:Lizbeth Cromwell} 艾尔文森林：{n:0:alliance:Tharynn Bouden} 铁炉堡：{n:0:alliance:Tansy Puddlefizz} 洛克莫丹：{n:0:alliance:Khara Deepwater} 泰达希尔：{n:0:alliance:Nyoma}",
  ["Durotar: {n:0:horde:Zansoa} Orgrimmar: {n:0:horde:Shankys} Silverpine Forest: {n:0:horde:Killian Sanatha} Undercity: {n:0:horde:Ronald Burch} Darkshore: {n:0:alliance:Heldan Galesong} Stormwind City: {n:0:alliance:Catherine Leland} Teldrassil: {n:0:alliance:Nessa Shadowsong} Westfall: {n:0:alliance:Kriggon Talsone} Wetlands: {n:0:alliance:Stuart Fleming} The Barrens: {n:0::Kilxx}"] = "杜隆塔尔：{n:0:horde:Zansoa} 奥格瑞玛：{n:0:horde:Shankys} 银松森林：{n:0:horde:Killian Sanatha} 幽暗城：{n:0:horde:Ronald Burch} 黑海岸：{n:0:alliance:Heldan Galesong} 暴风城：{n:0:alliance:Catherine Leland} 泰达希尔：{n:0:alliance:Nessa Shadowsong} 西部荒野：{n:0:alliance:Kriggon Talsone} 湿地：{n:0:alliance:Stuart Fleming} 贫瘠之地：{n:0::Kilxx}",
  ["Silverpine Forest: {n:0:horde:Andrew Hilbert} Loch Modan: {n:0:alliance:Drac Roughcut}"] = "银松森林：{n:0:horde:Andrew Hilbert} 洛克莫丹：{n:0:alliance:Drac Roughcut}",
  ["55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple} (Vendor)"] = "55x {i:5469:inv_misc_food_16:Strider Meat} 55x {i:4536:inv_misc_food_19:Shiny Red Apple}（商人）",
  ["The Barrens: {n:0:horde:Tari'qa} (Horde only) Reward from {q:2178::Easy Strider Living} (Alliance only)"] = "贫瘠之地：{n:0:horde:Tari'qa}（仅限部落） {q:2178::Easy Strider Living} 任务奖励（仅限联盟）",
  ["Make around 30-35 from one of these two."] = "从这两个中任选一个，做大约 30-35 个。",
  ["30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish} (buy around 55, you will need 25 more at 130-150)"] = "30x {i:6308:inv_misc_fish_30:Raw Bristle Whisker Catfish}（买大约 55 条，130-150 还需要 25 条）",
  ["Hillsbrad Foothills: {n:0:horde:Derak Nightfall} Thunder Bluff: {n:0:horde:Naal Mistrunner} Thunder Bluff: {n:0:horde:Sewa Mistrunner} Undercity: {n:0:horde:Ronald Burch} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne} Stormwind City: {n:0:alliance:Catherine Leland} The Barrens: {n:0::Kilxx}"] = "希尔斯布莱德丘陵：{n:0:horde:Derak Nightfall} 雷霆崖：{n:0:horde:Naal Mistrunner} 雷霆崖：{n:0:horde:Sewa Mistrunner} 幽暗城：{n:0:horde:Ronald Burch} 希尔斯布莱德丘陵：{n:0:alliance:Lindea Rabonne} 暴风城：{n:0:alliance:Catherine Leland} 贫瘠之地：{n:0::Kilxx}",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance only)"] = "暴风城：{n:0:alliance:Kendor Kabonka}（仅限联盟）",
  ["Make around 20-25 from any of the recipes below."] = "从下面任意配方中做大约 20-25 个。",
  ["See above"] = "见上文",
  ["Stormwind City: {n:0:alliance:Kendor Kabonka} (Alliance) Arathi Highlands: {n:0:horde:Keena} (Horde)"] = "暴风城：{n:0:alliance:Kendor Kabonka}（联盟） 阿拉希高地：{n:0:horde:Keena}（部落）",
  ["The Barrens: {n:0:horde:Zargh} (Horde only)"] = "贫瘠之地：{n:0:horde:Zargh}（仅限部落）",
  ["Expert Cooking (150-225)"] = "专家烹饪 (150-225)",
  ["To learn Expert Cooking you need to reach Cooking 125, then buy the {i:16072:inv_misc_book_08:Expert Cookbook} from {n:0:horde:Wulan} (Horde) in Desolace at Shadowprey Village or from {n:0:alliance:Shandrina} (Alliance) in Ashenvale at Mystral Lake."] = "要学习专家烹饪，你需要达到烹饪 125，然后在凄凉之地葬影村的 {n:0:horde:Wulan}（部落）或灰谷密斯特拉湖的 {n:0:alliance:Shandrina}（联盟）处购买 {i:16072:inv_misc_book_08:Expert Cookbook}。",
  ["Make around 25-30 from one of these three."] = "从这三个中任选一个，做大约 25-30 个。",
  ["You can also keep making {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}, but it's green from 160, so you need around 90 of them for these 25 points."] = "你也可以继续做 {s:7755:inv_misc_fish_30:Bristle Whisker Catfish}，但它从 160 开始变绿，所以这 25 点需要大约 90 个。",
  ["Make around 55 from one of these. The Roast Raptor is usually the cheapest."] = "从以下配方中任选一个，做大约 55 个。烤迅猛龙肉通常最便宜。",
  ["Arathi Highlands: {n:0:alliance:Hammon Karwn} Arathi Highlands: {n:0:horde:Keena} Dustwallow Marsh: {n:0:horde:Ogg'marr}"] = "阿拉希高地：{n:0:alliance:Hammon Karwn} 阿拉希高地：{n:0:horde:Keena} 尘泥沼泽：{n:0:horde:Ogg'marr}",
  ["Ashenvale: {n:0:horde:Wik'Tar} Orgrimmar: {n:0:horde:Shankys} Stranglethorn Vale: {n:0::Kelsey Yance} Undercity: {n:0:horde:Lizbeth Cromwell} Ironforge: {n:0:alliance:Tansy Puddlefizz} Wetlands: {n:0:alliance:Stuart Fleming} Desolace: {n:0:horde:Wulan} Darkshore: {n:0:alliance:Heldan Galesong} Hillsbrad Foothills: {n:0:alliance:Lindea Rabonne}"] = "灰谷：{n:0:horde:Wik'Tar} 奥格瑞玛：{n:0:horde:Shankys} 荆棘谷：{n:0::Kelsey Yance} 幽暗城：{n:0:horde:Lizbeth Cromwell} 铁炉堡：{n:0:alliance:Tansy Puddlefizz} 湿地：{n:0:alliance:Stuart Fleming} 凄凉之地：{n:0:horde:Wulan} 黑海岸：{n:0:alliance:Heldan Galesong} 希尔斯布莱德丘陵：{n:0:alliance:Lindea Rabonne}",
  ["Reward from a quest in Hillsbrad Foothills NPC: {n:0:horde:Christoph Jeffcoat}, quest: {q:7321::Soothing Turtle Bisque} NPC: {n:0:alliance:Chef Jessen}, quest: {q:555::Soothing Turtle Bisque}"] = "希尔斯布莱德丘陵任务奖励 NPC：{n:0:horde:Christoph Jeffcoat}，任务：{q:7321::Soothing Turtle Bisque} NPC：{n:0:alliance:Chef Jessen}，任务：{q:555::Soothing Turtle Bisque}",
  ["Artisan Cooking (225-300)"] = "大师烹饪 (225-300)",
  ["Artisan Cooking is the reward of the {q:6610::Clamlette Surprise} quest. You need {b}level 35{/b} and {b}Cooking 225{/b} for it."] = "大师烹饪是 {q:6610::Clamlette Surprise} 任务的奖励。你需要 {b}35 级{/b} 和 {b}烹饪 225{/b}。",
  ["Pick up the quest that sends you to Gadgetzan: Horde players take {q:6611::To Gadgetzan You Go!} from {n:0:horde:Zamja} in Orgrimmar, Alliance players take {q:6612::I Know A Guy...} from {n:0:alliance:Daryl Riknussun} in Ironforge."] = "接取把你派往加基森的任务：部落玩家在奥格瑞玛的 {n:0:horde:Zamja} 处接 {q:6611::To Gadgetzan You Go!}，联盟玩家在铁炉堡的 {n:0:alliance:Daryl Riknussun} 处接 {q:6612::I Know A Guy...}。",
  ["Collect 12x {i:12207:inv_egg_03:Giant Egg}, 10x {i:7974:inv_misc_food_51:Zesty Clam Meat} and 20x {i:8932:inv_misc_food_37:Alterac Swiss}. {b}Don't go to Gadgetzan before you have all of them{/b}, otherwise you make the trip twice."] = "收集 12x {i:12207:inv_egg_03:Giant Egg}、10x {i:7974:inv_misc_food_51:Zesty Clam Meat} 和 20x {i:8932:inv_misc_food_37:Alterac Swiss}。{b}凑齐之前不要去加基森{/b}，否则你得跑两趟。",
  ["Find {n:0::Dirge Quikcleave} in Gadgetzan, take Clamlette Surprise from him and hand in the three items. He teaches you Artisan Cooking on the spot. While you are in Tanaris, go to Steamwheedle Port and {b}buy {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail} from {n:0::Gikkix}{/b}, you need it in the next step."] = "在加基森找到 {n:0::Dirge Quikcleave}，从他那里接“蛤蜊蛋卷惊喜”并交上三样物品。他会当场教你大师烹饪。既然在塔纳利斯，就顺便去热砂港，{b}在 {n:0::Gikkix} 处购买 {i:13939:inv_scroll_03:Recipe: Spotted Yellowtail}{/b}，下一步要用到。",
  ["Make around 140 from one of these two, buy the fish that is cheaper."] = "从这两个中任选一个，做大约 140 个，买更便宜的那种鱼。",
  ["Tanaris: {n:0::Gikkix}"] = "塔纳利斯：{n:0::Gikkix}",
  ["Stranglethorn Vale: {n:0::Kelsey Yance}"] = "荆棘谷：{n:0::Kelsey Yance}",
  ["This WoW Forever First Aid leveling guide will show you the fastest way to level your First Aid skill from 1 to 300. You will also find every trainer location and where to train First Aid past 150 and 225."] = "这份 WoW Forever 急救升级指南将告诉你把急救技能从 1 升到 300 的最快方法。你还能找到所有训练师的位置，以及在 150 和 225 之后去哪里继续学习急救。",
  ["First Aid does not take up one of your two profession slots, so every character can learn it. Bandages heal you between fights, and in Forever First Aid also makes the healing potions that used to be Alchemy recipes, so it's worth leveling on every character. Below you will find the shopping list, the First Aid trainers by starting zone and capital city, and the cheapest recipes for every skill range."] = "急救不占用你的两个专业栏位，所以每个角色都能学。绷带可以在战斗间隙为你治疗，而且在 Forever 中急救还能制作原本属于炼金术配方的治疗药水，所以每个角色都值得练。下面是购物清单、按新手区和主城列出的急救训练师，以及每个技能区间最便宜的配方。",
  ["First Aid Trainer Locations"] = "急救训练师位置",
  ["Apprentice First Aid has no level requirement, so you can learn it on a fresh character. Every trainer also teaches Journeyman First Aid, so you don't have to find a different trainer at 50."] = "学徒级急救没有等级要求，所以新建的角色也能学。每位训练师也都教熟练急救，所以到 50 时不用另找训练师。",
  ["Orgrimmar: {n:0:horde:Arnok}"] = "奥格瑞玛：{n:0:horde:Arnok}",
  ["Undercity: {n:0:horde:Mary Edras}"] = "幽暗城：{n:0:horde:Mary Edras}",
  ["Thunder Bluff: {n:0:horde:Pand Stonebinder}"] = "雷霆崖：{n:0:horde:Pand Stonebinder}",
  ["Every starting zone has a First Aid trainer, most of them are inside the inn."] = "每个新手区都有急救训练师，大多在旅店里。",
  ["{n:0:horde:Rawrk} in the barracks in Razor Hill"] = "剃刀岭兵营里的 {n:0:horde:Rawrk}",
  ["{n:0:horde:Vira Younghoof} inside the inn in Bloodhoof Village"] = "血蹄村旅店里的 {n:0:horde:Vira Younghoof}",
  ["{n:0:horde:Nurse Neela} inside the inn in Brill"] = "布瑞尔旅店里的 {n:0:horde:Nurse Neela}",
  ["{n:0::Melasa Fairmend} in Valanaar, {n:0::Naleeia Tattermend} in Shen'dar Village"] = "Valanaar 的 {n:0::Melasa Fairmend}，Shen'dar Village 的 {n:0::Naleeia Tattermend}",
  ["Stormwind City: {n:0:alliance:Shaina Fuller}"] = "暴风城：{n:0:alliance:Shaina Fuller}",
  ["Ironforge: {n:0:alliance:Nissa Firestone}"] = "铁炉堡：{n:0:alliance:Nissa Firestone}",
  ["Darnassus: {n:0:alliance:Dannelor}"] = "达纳苏斯：{n:0:alliance:Dannelor}",
  ["{n:0:alliance:Michelle Belle} upstairs in the inn in Goldshire"] = "闪金镇旅店楼上的 {n:0:alliance:Michelle Belle}",
  ["{n:0:alliance:Thamner Pol} in the Thunderbrew Distillery in Kharanos"] = "卡拉诺斯雷酒酿制厂里的 {n:0:alliance:Thamner Pol}",
  ["{n:0:alliance:Byancie} in Dolanaar, in the building north of the inn"] = "多兰纳尔旅店北边建筑里的 {n:0:alliance:Byancie}",
  ["You can find every First Aid trainer for Horde and Alliance on my WoW Forever First Aid Trainers page."] = "你可以在我的 WoW Forever 急救训练师页面找到部落和联盟的所有急救训练师。",
  ["Apprentice First Aid (1-75)"] = "学徒急救 (1-75)",
  ["If you have Linen Cloth or bought some, pick the {b}Bandages{/b} tab. If you bought herbs, pick the {b}Healing Potions{/b} tab."] = "如果你有亚麻布或者买了一些，选择 {b}绷带{/b} 标签页。如果你买的是草药，选择 {b}治疗药水{/b} 标签页。",
  ["Bandages"] = "绷带",
  ["Healing Potions"] = "治疗药水",
  ["86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 Peacebloom, 86 Mild Spices, 86 Empty Vial"] = "86x {s:1244431:inv_potion_49:Minor Healing Potion} - 86 宁神花，86 淡味香料，86 空瓶",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} are sold by Cooking supply vendors, {i:3371:inv_potion_84:Empty Vial} by Alchemy supply vendors. Open your faction below to see who sells them near your trainer:"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} 由烹饪供应商出售，{i:3371:inv_potion_84:Empty Vial} 由炼金供应商出售。展开下面你的阵营，查看训练师附近谁在出售：",
  ["spices: {n:0:horde:Xen'to} vials: {n:0:horde:Kor'geld}"] = "香料：{n:0:horde:Xen'to} 空瓶：{n:0:horde:Kor'geld}",
  ["{n:0:horde:Felicia Doan} in the Trade Quarter"] = "商业区的 {n:0:horde:Felicia Doan}",
  ["spices: {n:0:horde:Naal Mistrunner} vials: {n:0:horde:Mani Winterhoof}"] = "香料：{n:0:horde:Naal Mistrunner} 空瓶：{n:0:horde:Mani Winterhoof}",
  ["{n:0:horde:Wunna Darkmane} in Bloodhoof Village"] = "血蹄村的 {n:0:horde:Wunna Darkmane}",
  ["{n:0:horde:Abigail Shiel} in Brill"] = "布瑞尔的 {n:0:horde:Abigail Shiel}",
  ["{n:0::Iallion Featherfall} in Valanaar {n:0::Belandiel Farflight} in Shen'dar Village"] = "Valanaar 的 {n:0::Iallion Featherfall} Shen'dar Village 的 {n:0::Belandiel Farflight}",
  ["{n:0:alliance:Edna Mullby} in the Trade District"] = "贸易区的 {n:0:alliance:Edna Mullby}",
  ["spices: {n:0:alliance:Emrul Riknussun} vials: {n:0:alliance:Gwina Stonebranch}, right next to the trainer"] = "香料：{n:0:alliance:Emrul Riknussun} 空瓶：{n:0:alliance:Gwina Stonebranch}，就在训练师旁边",
  ["{n:0:alliance:Golorn Frostbeard} in Kharanos"] = "卡拉诺斯的 {n:0:alliance:Golorn Frostbeard}",
  ["{n:0:alliance:Narret Shadowgrove} in Dolanaar"] = "多兰纳尔的 {n:0:alliance:Narret Shadowgrove}",
  ["50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 Linen Cloth"] = "50x {s:3275:inv_misc_bandage_15:Linen Bandage} - 50 亚麻布",
  ["49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 Linen Cloth"] = "49x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 98 亚麻布",
  ["Journeyman First Aid (75-150)"] = "熟练急救 (75-150)",
  ["To train past 75, visit your trainer and learn Journeyman First Aid, it requires First Aid 50."] = "要突破 75，请去找训练师学习熟练急救，需要急救 50。",
  ["16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 Linen Cloth"] = "16x {s:3276:inv_misc_bandage_18:Heavy Linen Bandage} - 32 亚麻布",
  ["12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 Wool Cloth"] = "12x {s:3277:inv_misc_bandage_14:Wool Bandage} - 12 毛料",
  ["If you have Wool Cloth, pick the {b}Bandages{/b} tab. If you have to buy everything, the {b}Healing Potions{/b} tab is cheaper."] = "如果你有毛料，选择 {b}绷带{/b} 标签页。如果所有东西都得买，{b}治疗药水{/b} 标签页更便宜。",
  ["43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 Wool Cloth"] = "43x {s:3277:inv_misc_bandage_14:Wool Bandage} - 43 毛料",
  ["54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 Wool Cloth"] = "54x {s:3278:inv_misc_bandage_17:Heavy Wool Bandage} - 108 毛料",
  ["For this tab you need 54 {i:2678:inv_misc_food_wheat_02:Mild Spices}, 31 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}, 31 {i:3372:inv_potion_85:Leaded Vial} and 54 {i:2723:inv_drink_10:Bottle of Dalaran Noir}. Spices are sold by Cooking supply vendors, vials by Alchemy supply vendors and the bottles by barkeeps. The starting zone vendors don't sell Hot Spices or Leaded Vials, so buy them in a capital city. Open your faction below to see who sells them:"] = "这个标签页需要 54 个 {i:2678:inv_misc_food_wheat_02:Mild Spices}、31 个 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}、31 个 {i:3372:inv_potion_85:Leaded Vial} 和 54 瓶 {i:2723:inv_drink_10:Bottle of Dalaran Noir}。香料由烹饪供应商出售，瓶子由炼金供应商出售，酒由酒吧老板出售。新手区的商人不卖辣椒和铅瓶，所以请在主城购买。展开下面你的阵营，查看谁在出售：",
  ["{i:2678:inv_misc_food_wheat_02:Mild Spices} and {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}"] = "{i:2678:inv_misc_food_wheat_02:Mild Spices} 和 {i:2692:inv_misc_food_legion_dalapenopepper:Hot Spices}",
  ["Orgrimmar: {n:0:horde:Xen'to} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Naal Mistrunner}"] = "奥格瑞玛：{n:0:horde:Xen'to} 幽暗城：{n:0:horde:Felicia Doan} 雷霆崖：{n:0:horde:Naal Mistrunner}",
  ["Orgrimmar: {n:0:horde:Kor'geld} Undercity: {n:0:horde:Felicia Doan} Thunder Bluff: {n:0:horde:Mani Winterhoof}"] = "奥格瑞玛：{n:0:horde:Kor'geld} 幽暗城：{n:0:horde:Felicia Doan} 雷霆崖：{n:0:horde:Mani Winterhoof}",
  ["Orgrimmar: {n:5611::Barkeep Morag} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "奥格瑞玛：{n:5611::Barkeep Morag} 藏宝海湾：{n:2832::Nixxrax Fillamug}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Emrul Riknussun} Darnassus: {n:0:alliance:Mythrin'dir}"] = "暴风城：{n:0:alliance:Edna Mullby} 铁炉堡：{n:0:alliance:Emrul Riknussun} 达纳苏斯：{n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:0:alliance:Edna Mullby} Ironforge: {n:0:alliance:Gwina Stonebranch} Darnassus: {n:0:alliance:Mythrin'dir}"] = "暴风城：{n:0:alliance:Edna Mullby} 铁炉堡：{n:0:alliance:Gwina Stonebranch} 达纳苏斯：{n:0:alliance:Mythrin'dir}",
  ["Stormwind City: {n:277::Roberto Pupellyverbos} and {n:1328::Elly Langston} Ironforge: {n:5570::Bruuk Barleybeard} Booty Bay: {n:2832::Nixxrax Fillamug}"] = "暴风城：{n:277::Roberto Pupellyverbos} 和 {n:1328::Elly Langston} 铁炉堡：{n:5570::Bruuk Barleybeard} 藏宝海湾：{n:2832::Nixxrax Fillamug}",
  ["54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 Spider Ichor, 54 Mild Spices, 54 Bottle of Dalaran Noir"] = "54x {s:1259342:inv_10_alchemy2_quenchingfluid_color2:Simple Poultice} - 54 蜘蛛之液，54 淡味香料，54 达拉然黑葡萄酒",
  ["31x {s:1244433:inv_potion_51:Healing Potion} - 31 Bruiseweed, 31 Hot Spices, 31 Leaded Vial"] = "31x {s:1244433:inv_potion_51:Healing Potion} - 31 跌打草，31 辣椒，31 铅瓶",
  ["Expert First Aid (150-225)"] = "专家急救 (150-225)",
  ["{b}Learn {s:7928:inv_misc_bandage_01:Silk Bandage} from your trainer before you leave{/b}, it's the last recipe the trainers teach."] = "{b}离开前先向训练师学会 {s:7928:inv_misc_bandage_01:Silk Bandage}{/b}，这是训练师教的最后一个配方。",
  ["How to learn Expert First Aid"] = "如何学习专家急救",
  ["To train past 150, buy the {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps} book from {n:0:alliance:Deneb Walker} (Alliance) in Arathi Highlands or {n:0:horde:Balai Lok'Wein} (Horde) in Dustwallow Marsh. The book has {b}no level requirement{/b}, you only need First Aid 125."] = "要突破 150，请在阿拉希高地的 {n:0:alliance:Deneb Walker}（联盟）或尘泥沼泽的 {n:0:horde:Balai Lok'Wein}（部落）处购买 {i:16084:inv_misc_book_08:Expert First Aid - Under Wraps}。这本书{b}没有等级要求{/b}，只需要急救 125。",
  ["They also sell the next two manuals, so {b}buy all three{/b} while you are there, or get them from the Auction House if you are low level:"] = "他们也出售接下来的两本手册，所以趁在那里时{b}三本都买{/b}，如果你等级低也可以从拍卖行买：",
  ["47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 Silk Cloth"] = "47x {s:7928:inv_misc_bandage_01:Silk Bandage} - 47 丝绸",
  ["47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 Silk Cloth"] = "47x {s:7929:inv_misc_bandage_02:Heavy Silk Bandage} - 94 丝绸",
  ["Use the Manual: Heavy Silk Bandage first to learn the recipe."] = "先使用“手册：厚丝质绷带”学会配方。",
  ["19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 Mageweave Cloth"] = "19x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 19 魔纹布",
  ["Use the Manual: Mageweave Bandage first to learn the recipe."] = "先使用“手册：魔纹绷带”学会配方。",
  ["Artisan First Aid (225-300)"] = "大师急救 (225-300)",
  ["You can train First Aid past 225 by completing the Triage quest. It requires {b}First Aid 225{/b} and {b}level 35{/b}, even though the quest itself is level 45."] = "完成“紧急救护”任务后，你就能把急救练到 225 以上。它需要 {b}急救 225{/b} 和 {b}35 级{/b}，虽然任务本身是 45 级。",
  ["{b}Bring everything you need in order to skill up to 275{/b}, as you will learn the next two bandages from the same doctor, so bring around 90 Mageweave Cloth and 20 Runecloth with you."] = "{b}把升到 275 所需的东西都带上{/b}，因为接下来的两种绷带也是向同一位医生学习，所以随身带上大约 90 块魔纹布和 20 块符文布。",
  ["The {q:6622::Triage} quest is given by {n:0:horde:Doctor Gregory Victor} in Arathi Highlands at Hammerfall."] = "{q:6622::Triage} 任务由阿拉希高地落锤镇的 {n:0:horde:Doctor Gregory Victor} 发布。",
  ["Hammerfall, Arathi Highlands"] = "阿拉希高地，落锤镇",
  ["The {q:6624::Triage} quest is given by {n:0:alliance:Doctor Gustaf VanHowzen} in Dustwallow Marsh at Theramore."] = "{q:6624::Triage} 任务由尘泥沼泽塞拉摩的 {n:0:alliance:Doctor Gustaf VanHowzen} 发布。",
  ["Foothold Citadel, Dustwallow Marsh"] = "尘泥沼泽，塞拉摩城堡",
  ["You get a stack of triage bandages and have to save 15 patients, heal the critically injured ones first."] = "你会得到一叠急救绷带，必须救活 15 名伤员，先治疗伤势危急的。",
  ["How to complete the Triage quest"] = "如何完成“紧急救护”任务",
  ["Make sure you have about 10 minutes of spare time to do this with no interruptions."] = "确保你有大约 10 分钟不受打扰的空闲时间来完成它。",
  ["Press CTRL + V to show the health bars over the patients, or turn on \"Show NPC names\" in the interface options."] = "按 CTRL + V 显示伤员头上的血条，或者在界面选项中开启“显示 NPC 名字”。",
  ["Zoom the camera out to third person, so you see as much of the room as you can."] = "把镜头拉远到第三人称，尽可能多地看到整个房间。",
  ["Put the Triage Bandages the doctor gave you on your action bar and use those, not your own bandages."] = "把医生给你的急救绷带放到动作条上，使用这些绷带，而不是你自己的绷带。",
  ["Stand in the middle of the room."] = "站在房间中央。",
  ["When you see another patient, left-click on them to pre-select them, and as soon as your current heal has finished click the bandages in your action bar and the pre-selected one will begin to heal. Saves valuable seconds this way."] = "看到另一名伤员时，左键点击预先选中他，当前的治疗一结束就点击动作条上的绷带，预选中的伤员就会开始被治疗。这样可以节省宝贵的几秒钟。",
  ["When you have saved 15 patients, {b}turn in the quest immediately{/b}. I failed it on my druid because I waited, six patients died in the meantime and the quest went from completed to failed."] = "救活 15 名伤员后，{b}立刻交任务{/b}。我的德鲁伊就失败过，因为我等了一会儿，期间有六名伤员死亡，任务从完成变成了失败。",
  ["29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 Mageweave Cloth"] = "29x {s:10840:inv_misc_bandage_19:Mageweave Bandage} - 29 魔纹布",
  ["30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 Mageweave Cloth"] = "30x {s:10841:inv_misc_bandage_20:Heavy Mageweave Bandage} - 60 魔纹布",
  ["The doctor teaches it at 240."] = "医生在 240 时教这个。",
  ["20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 Runecloth"] = "20x {s:18629:inv_misc_bandage_11:Runecloth Bandage} - 20 符文布",
  ["The doctor teaches it at 260."] = "医生在 260 时教这个。",
  ["30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 Golden Sansam, 90 Soothing Spices, 30 Crystal Vial"] = "30x {s:1244436:inv_potion_54:Major Healing Potion} - 30 黄金参，90 舒心香料，30 水晶瓶",
  ["The recipe is {i:255729:inv_misc_book_03:Manual: Major Healing Potion}. Check the Auction House first, and buy it there if it costs less than 8g."] = "配方是 {i:255729:inv_misc_book_03:Manual: Major Healing Potion}。先看看拍卖行，如果低于 8 金就在那里买。",
  ["If it costs more, you can buy it from {n:0::Pexmit} in Mount Hyjal for 8g, but he can be tricky to find."] = "如果更贵，你可以在海加尔山的 {n:0::Pexmit} 处花 8 金购买，但他可能不太好找。",
  ["Horde players can also get it from Ortak Lomgok in Elderwild, Mount Hyjal, as the reward for {q:96622::A Rest Without Pain}. You have to complete his {q:96616::Herbs for the Bruised and Weary} quest first."] = "部落玩家也可以从海加尔山 Elderwild 的 Ortak Lomgok 处获得，作为 {q:96622::A Rest Without Pain} 的奖励。你得先完成他的 {q:96616::Herbs for the Bruised and Weary} 任务。",
  ["This WoW Forever Fishing leveling guide will show you the fastest way to level Fishing from 1 to 300. Fishing takes a lot of patience, you will have to catch a lot of fish to get from start to finish, but you don't need any materials, only a Fishing Pole and a few lures."] = "这份 WoW Forever 钓鱼升级指南将告诉你把钓鱼从 1 升到 300 的最快方法。钓鱼需要很大的耐心，从头到尾要钓很多鱼，但不需要任何材料，只要一根鱼竿和几个鱼饵。",
  ["Below you will find every Fishing trainer by starting zone and capital city, where to fish for each skill range, and how to learn Expert and Artisan Fishing. If you haven't leveled Cooking yet, use my Fishing and Cooking leveling guide instead, because the fish you catch will level your Cooking at the same time:"] = "下面是按新手区和主城列出的所有钓鱼训练师、每个技能区间的钓鱼地点，以及如何学习专家和大师钓鱼。如果你还没练烹饪，请改用我的钓鱼和烹饪升级指南，因为你钓到的鱼同时可以练烹饪：",
  ["Fishing Trainer Locations"] = "钓鱼训练师位置",
  ["Apprentice Fishing has no level requirement in Forever, so you can learn it on a fresh character. Every trainer also teaches Journeyman Fishing, so you don't have to find a different trainer at 50."] = "在 Forever 中学习学徒级钓鱼没有等级要求，所以新建的角色也能学。每位训练师也都教熟练钓鱼，所以到 50 时不用另找训练师。",
  ["Orgrimmar: {n:0:horde:Lumak}"] = "奥格瑞玛：{n:0:horde:Lumak}",
  ["Undercity: {n:0:horde:Armand Cromwell}"] = "幽暗城：{n:0:horde:Armand Cromwell}",
  ["Thunder Bluff: {n:0:horde:Kah Mistrunner}"] = "雷霆崖：{n:0:horde:Kah Mistrunner}",
  ["Every starting zone has a Fishing trainer, and they all stand next to water, so you can start fishing right away."] = "每个新手区都有钓鱼训练师，而且他们都站在水边，所以你可以马上开始钓鱼。",
  ["{n:0:horde:Lau'Tiki} on the coast at Sen'jin Village"] = "森金村海岸边的 {n:0:horde:Lau'Tiki}",
  ["{n:0:horde:Uthan Stillwater} at Stonebull Lake, next to Bloodhoof Village"] = "血蹄村旁石牛湖边的 {n:0:horde:Uthan Stillwater}",
  ["{n:0:horde:Clyde Kellen} at Brightwater Lake, east of Brill"] = "布瑞尔东边明水湖边的 {n:0:horde:Clyde Kellen}",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Fenn Fairweather} in Shen'dar Village"] = "Valanaar 的 {n:0::Baelann Swiftcurrent}，Shen'dar Village 的 {n:0::Fenn Fairweather}",
  ["Stormwind City: {n:0:alliance:Arnold Leland}"] = "暴风城：{n:0:alliance:Arnold Leland}",
  ["Ironforge: {n:0:alliance:Grimnur Stonebrand}"] = "铁炉堡：{n:0:alliance:Grimnur Stonebrand}",
  ["Darnassus: {n:0:alliance:Astaia}"] = "达纳苏斯：{n:0:alliance:Astaia}",
  ["{n:0:alliance:Lee Brown} at Crystal Lake, east of Goldshire"] = "闪金镇东边水晶湖边的 {n:0:alliance:Lee Brown}",
  ["{n:0:alliance:Paxton Ganter} at Iceflow Lake, on the way to Gnomeregan"] = "去诺莫瑞根路上冰流湖边的 {n:0:alliance:Paxton Ganter}",
  ["{n:0:alliance:Androl Oakhand} in Rut'theran Village, on the shore next to the dock"] = "鲁瑟兰村码头旁岸边的 {n:0:alliance:Androl Oakhand}",
  ["You can find every Fishing trainer for Horde and Alliance on my WoW Forever Fishing Trainers page."] = "你可以在我的 WoW Forever 钓鱼训练师页面找到部落和联盟的所有钓鱼训练师。",
  ["How to Fish in WoW Forever (1-75)"] = "如何在 WoW Forever 中钓鱼 (1-75)",
  ["Buy a {i:6256:inv_fishingpole_02:Fishing Pole} and a few {i:6529:inv_misc_orb_03:Shiny Bauble} from a Fishing Supply or Trade Supply vendor. In the capital cities they stand next to the trainer, for every other zone open your faction below:"] = "在钓鱼供应商或商业供应商处买一根 {i:6256:inv_fishingpole_02:Fishing Pole} 和几个 {i:6529:inv_misc_orb_03:Shiny Bauble}。在主城里他们就站在训练师旁边，其他区域请展开下面你的阵营：",
  ["{n:0:horde:Zansoa} in Sen'jin Village"] = "森金村的 {n:0:horde:Zansoa}",
  ["{n:0:horde:Martine Tramblay} at the Death's Watch Waystation, south-east of Brill"] = "布瑞尔东南方 Death's Watch Waystation 的 {n:0:horde:Martine Tramblay}",
  ["{n:0::Baelann Swiftcurrent} in Valanaar, {n:0::Belandiel Farflight} in Shen'dar Village"] = "Valanaar 的 {n:0::Baelann Swiftcurrent}，Shen'dar Village 的 {n:0::Belandiel Farflight}",
  ["{n:0:horde:Shankys}, next to the Fishing trainer"] = "{n:0:horde:Shankys}，在钓鱼训练师旁边",
  ["{n:0:horde:Lizbeth Cromwell}, next to the Fishing trainer"] = "{n:0:horde:Lizbeth Cromwell}，在钓鱼训练师旁边",
  ["{n:0:horde:Sewa Mistrunner}, next to the Fishing trainer"] = "{n:0:horde:Sewa Mistrunner}，在钓鱼训练师旁边",
  ["{n:0:horde:Wik'Tar} in Zoram'gar Outpost"] = "佐拉姆加前哨站的 {n:0:horde:Wik'Tar}",
  ["{n:0:horde:Katoom the Angler}, the Fishing trainer in Revantusk Village"] = "{n:0:horde:Katoom the Angler}，恶齿村的钓鱼训练师",
  ["{n:0:alliance:Gretta Ganter} at Iceflow Lake"] = "冰流湖的 {n:0:alliance:Gretta Ganter}",
  ["{n:0:alliance:Nessa Shadowsong} in Rut'theran Village"] = "鲁瑟兰村的 {n:0:alliance:Nessa Shadowsong}",
  ["{n:0:alliance:Catherine Leland}, next to the Fishing trainer"] = "{n:0:alliance:Catherine Leland}，在钓鱼训练师旁边",
  ["{n:0:alliance:Tansy Puddlefizz}, next to the Fishing trainer"] = "{n:0:alliance:Tansy Puddlefizz}，在钓鱼训练师旁边",
  ["{n:0:alliance:Voloren}, next to the Fishing trainer"] = "{n:0:alliance:Voloren}，在钓鱼训练师旁边",
  ["{n:0:alliance:Khara Deepwater} at the Loch"] = "洛克湖边的 {n:0:alliance:Khara Deepwater}",
  ["{n:0:alliance:Stuart Fleming} in Menethil Harbor"] = "米奈希尔港的 {n:0:alliance:Stuart Fleming}",
  ["Redridge Mountains"] = "赤脊山",
  ["{n:0:alliance:Vernon Hale} at Lake Everstill"] = "永望湖边的 {n:0:alliance:Vernon Hale}",
  ["{n:0:alliance:Lindea Rabonne} in Southshore"] = "南海镇的 {n:0:alliance:Lindea Rabonne}",
  ["Open the Professions window."] = "打开专业窗口。",
  ["Click on the {b}hammer button{/b} in the row of buttons on the right side of your screen, {b}NOT the Fishing tab{/b}."] = "点击屏幕右侧按钮栏中的{b}锤子按钮{/b}，{b}而不是钓鱼标签页{/b}。",
  ["Drag the {s:7731:trade_fishing:Fishing} button from the Fishing box to your action bar."] = "把钓鱼框中的 {s:7731:trade_fishing:Fishing} 按钮拖到你的动作条上。",
  ["Equip your Fishing Pole and apply the {i:6529:inv_misc_orb_03:Shiny Bauble} lure."] = "装备鱼竿，并装上 {i:6529:inv_misc_orb_03:Shiny Bauble} 鱼饵。",
  ["Go to any starting zone and look for a lake, pond or river. Stand in front of the water and press the fishing button."] = "去任意新手区，找一个湖泊、池塘或河流。站在水边，按下钓鱼按钮。",
  ["Mouse over the bobber in the water, and when it splashes, right-click on it."] = "把鼠标移到水中的鱼漂上，当它溅起水花时右键点击。",
  ["Fish until you reach Fishing 75."] = "一直钓到钓鱼 75。",
  ["{b}Starting zones:{/b} Dun Morogh, Durotar, Elwynn Forest, Mulgore, Teldrassil, Tirisfal Glades, Zephras Isle"] = "{b}新手区：{/b}丹莫罗、杜隆塔尔、艾尔文森林、莫高雷、泰达希尔、提瑞斯法林地、Zephras Isle",
  ["{b}Remember, starting zones do not include capital cities!{/b}"] = "{b}记住，新手区不包括主城！{/b}",
  ["If you can't find the Fishing button, I show it with pictures in my how to fish in WoW Forever guide."] = "如果你找不到钓鱼按钮，我在“如何在 WoW Forever 中钓鱼”指南里有图片说明。",
  ["Go back to your trainer and learn Journeyman Fishing. It requires {b}Fishing 50{/b} and {b}level 10{/b}."] = "回到训练师那里学习熟练钓鱼。需要 {b}钓鱼 50{/b} 和 {b}10 级{/b}。",
  ["Fish until 150 in one of the capital cities:"] = "在任意一座主城钓到 150：",
  ["You can fish in any of these zones too: The Barrens, Darkshore, Ironforge, Loch Modan, Silverpine Forest, Westfall."] = "你也可以在以下任意区域钓鱼：贫瘠之地、黑海岸、铁炉堡、洛克莫丹、银松森林、西部荒野。",
  ["If the fish keep getting away, buy {i:6530:inv_misc_monstertail_03:Nightcrawlers} from a Fishing Supply vendor. They need Fishing 50."] = "如果鱼总是脱钩，就在钓鱼供应商处买 {i:6530:inv_misc_monstertail_03:Nightcrawlers}。它需要钓鱼 50。",
  ["You can learn Expert Fishing from the {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} book (requires {b}level 20{/b} and {b}Fishing 125{/b}) sold by {n:0::Old Man Heming} at Booty Bay in Stranglethorn Vale. He is in the middle of Booty Bay at the very bottom, near the fishing sign. You can also buy the book from the Auction House."] = "你可以通过 {i:16083:inv_misc_book_08:Expert Fishing - The Bass and You} 这本书学习专家钓鱼（需要 {b}20 级{/b} 和 {b}钓鱼 125{/b}），它由荆棘谷藏宝海湾的 {n:0::Old Man Heming} 出售。他在藏宝海湾中央的最底层，钓鱼招牌附近。你也可以在拍卖行买这本书。",
  ["Buy a bunch of {i:6532:inv_misc_gem_variety_02:Bright Baubles} from Old Man Heming before you leave."] = "离开前在老汉明处买一堆 {i:6532:inv_misc_gem_variety_02:Bright Baubles}。",
  ["Go to {b}Dustwallow Marsh{/b}, apply {i:6532:inv_misc_gem_variety_02:Bright Baubles} to your Fishing Pole and fish until 225."] = "前往{b}尘泥沼泽{/b}，给鱼竿装上 {i:6532:inv_misc_gem_variety_02:Bright Baubles}，一直钓到 225。",
  ["I recommend fishing in Dustwallow because the Artisan Fishing quest starts there, but you can fish in these zones too: Alterac Mountains, Arathi Highlands, Desolace, Stranglethorn Vale, Swamp of Sorrows, and Thousand Needles."] = "我推荐在尘泥沼泽钓鱼，因为大师钓鱼任务就从那里开始，不过你也可以在以下区域钓：奥特兰克山脉、阿拉希高地、凄凉之地、荆棘谷、悲伤沼泽和千针石林。",
  ["Learning Artisan Fishing"] = "学习大师钓鱼",
  ["To train Fishing past 225, you must complete the quest {q:6607::Nat Pagle, Angler Extreme} from {n:0::Nat Pagle} in Dustwallow Marsh."] = "要把钓鱼练到 225 以上，你必须完成尘泥沼泽 {n:0::Nat Pagle} 的任务 {q:6607::Nat Pagle, Angler Extreme}。",
  ["It requires {b}level 35{/b} and {b}Fishing 225{/b}."] = "它需要 {b}35 级{/b} 和 {b}钓鱼 225{/b}。",
  ["To complete the quest, you have to catch 4 quest fish in four different zones:"] = "要完成任务，你必须在四个不同区域钓到 4 条任务鱼：",
  ["{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - Feralas"] = "{i:16967:inv_misc_monsterhead_02:Feralas Ahi} - 菲拉斯",
  ["Use {i:6532:inv_misc_gem_variety_02:Bright Baubles} when you are fishing in {b}Feralas{/b} to stop the fish from getting away. You don't need any lures in the other zones because your Fishing skill is high enough by then."] = "在{b}菲拉斯{/b}钓鱼时使用 {i:6532:inv_misc_gem_variety_02:Bright Baubles} 防止鱼脱钩。其他区域不需要任何鱼饵，因为那时你的钓鱼技能已经够高了。",
  ["Nat Pagle, Angler Extreme quest"] = "“极限钓手纳特·帕格”任务",
  ["After you completed the quest, fish in any of these zones:"] = "完成任务后，在以下任意区域钓鱼：",
  ["Feralas"] = "菲拉斯",
  ["Western Plaguelands"] = "西瘟疫之地",
  ["You will have to use {i:6532:inv_misc_gem_variety_02:Bright Baubles} in these zones to stop the fish from getting away!"] = "在这些区域你必须使用 {i:6532:inv_misc_gem_variety_02:Bright Baubles} 防止鱼脱钩！",
  ["This WoW Forever Lockpicking leveling guide will show you the fastest way to level Lockpicking from 1 to 300, with the best place to pick locks for each skill range."] = "这份 WoW Forever 开锁升级指南将告诉你把开锁从 1 升到 300 的最快方法，以及每个技能区间最适合开锁的地点。",
  ["Max Lockpicking Skill by Level"] = "各等级的开锁技能上限",
  ["{b}Your Lockpicking skill can't go higher than 5 times your level{/b}, so you have to level your character to level Lockpicking. This is the level you need for each part of the guide:"] = "{b}你的开锁技能不能超过你等级的 5 倍{/b}，所以要练开锁就得先练角色等级。以下是指南各部分所需的等级：",
  ["Your level"] = "你的等级",
  ["Max Lockpicking skill"] = "开锁技能上限",
  ["I originally made this guide with my rogue in Classic. In WoW Forever I'm leveling a hunter, so a friend of mine checks the spots on his rogue, and he confirmed the Horde 1-100 part. Readers told me where they leveled from 150 to 300. I'm assuming the rest is the same as in Classic, but I will confirm it later. If something looks off, send me feedback."] = "这份指南最初是我在经典版用盗贼做的。在 WoW Forever 中我在练猎人，所以由我的一位朋友用他的盗贼检查这些地点，他确认了部落 1-100 的部分。读者告诉了我他们在哪里从 150 练到 300。其余部分我假设和经典版一样，之后会再确认。如果有什么看起来不对，请给我反馈。",
  ["Go to the ship near Ratchet in The Barrens. The Buccaneer's Strongboxes there respawn after a few seconds, so even two rogues can skill up there at the same time. {b}They are inside the ship{/b}, at the spot marked on the map below."] = "前往贫瘠之地棘齿城附近的那艘船。那里的海盗保险箱几秒钟后就会刷新，所以即使两个盗贼也能同时在那里练技能。{b}它们在船舱里{/b}，位置见下面地图上的标记。",
  ["There is another chest at the bottom of the ship called The Jewel of the Southsea. Don't open it if you are low level, because it spawns a mob that will kill you."] = "船底还有一个箱子叫做“南海之宝”。如果你等级低就别打开它，因为它会刷出一只会杀死你的怪物。",
  ["There are a bunch of Practice Lockboxes in Redridge Mountains, north of Lake Everstill. They respawn really fast, so you can get to 100 there easily."] = "赤脊山永望湖北边有一堆练习用锁箱。它们刷新得非常快，所以你可以轻松在那里升到 100。",
  ["Go to Zoram Strand in Ashenvale and look for Waterlogged Footlockers along the shore, on land."] = "前往灰谷的佐拉姆海岸，沿着海岸在陆地上寻找浸水的提箱。",
  ["Go to Angor Fortress in Badlands. There are two kinds of footlockers there, the Battered Footlockers upstairs need 150, and the Dented Footlockers downstairs need {b}175{/b}."] = "前往荒芜之地的安戈尔要塞。那里有两种提箱，楼上的破损的提箱需要 150，楼下的凹陷的提箱需要 {b}175{/b}。",
  ["The footlockers downstairs give a skill point every time until 215, so you can stay here until 225."] = "楼下的提箱在 215 之前每次都能加一点技能，所以你可以在这里待到 225。",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give any skill."] = "不用费心偷那里怪物的东西，因为它们的箱子等级太低，加不了技能。",
  ["Go to The Slag Pit, the cave in the middle of Searing Gorge, and pick the footlockers there. The ones on the upper part give skill points all the way to 300. They stay yellow until 290 and turn green after that, so the last 10 points take longer."] = "前往灼热峡谷中央的山洞熔渣之池，开那里的提箱。上层的提箱一直到 300 都能加技能点。它们到 290 之前都是黄色，之后变绿，所以最后 10 点要花更长时间。",
  ["{b}There are two kinds of Dented Footlockers in the Slag Pit{/b}, with the same name. The ones on the lower part need 200 and the ones on the upper part need 225. Pick both until the lower ones stop giving skill points, then stay on the upper part."] = "{b}熔渣之池里有两种同名的凹陷的提箱{/b}。下层的需要 200，上层的需要 225。两种都开，直到下层的不再加技能点，然后就待在上层。",
  ["Don't bother pickpocketing the mobs there, because their boxes are too low level to give much skill."] = "不用费心偷那里怪物的东西，因为它们的箱子等级太低，加不了多少技能。",
  ["This WoW Forever camping guide will show you how camping works, how to make a campfire and every camp item and buff of every profession."] = "这份 WoW Forever 露营指南将告诉你露营系统如何运作、如何制作营火，以及每个专业的所有营地物品和增益效果。",
  ["Three night elves sitting at a campfire in Dolanaar, Teldrassil, in WoW Forever"] = "WoW Forever 中三个暗夜精灵坐在泰达希尔多兰纳尔的营火旁",
  ["How Camping Works"] = "露营如何运作",
  ["Someone puts down a campfire, and everyone around it can place a camp item of their own profession. {b}Sit (/sit) next to the fire for a minute{/b}, you will see a buff start counting down. Then you get Camp Benefits, one buff with everything the camp items give, for an hour."] = "有人放下一堆营火，周围的每个人都可以放置一件自己专业的营地物品。{b}在火堆旁坐下（/sit）一分钟{/b}，你会看到一个增益效果开始倒计时。之后你会获得“营地增益”，这是一个包含所有营地物品效果的增益，持续一小时。",
  ["{b}Each player can place one camp item{/b}, and it puts all your camp items on a 1 hour cooldown. A campfire holds 3, 5 or 10 camp items, depending on how big it is (see How to Make a Campfire below). The buffs are weaker class buffs and don't stack with them."] = "{b}每位玩家只能放置一件营地物品{/b}，放置后你所有的营地物品都会进入 1 小时冷却。一堆营火能容纳 3、5 或 10 件营地物品，取决于营火大小（见下文“如何制作营火”）。这些增益是职业增益的弱化版，不能与之叠加。",
  ["The intro quests in the starting zones, The Great Outdoors and Camping 101, are optional, the buffs work without them. The quest givers' fires always give the Camp Tent's rested experience."] = "新手区的入门任务 The Great Outdoors 和 Camping 101 是可选的，没有它们增益也照样生效。任务发布者的营火总是提供营帐的休息经验。",
  ["How to Make a Campfire"] = "如何制作营火",
  ["Learn Cooking from any Cooking trainer, the Basic Campfire Kit comes with it at skill 1. {i:4470:inv_tradeskillitem_01:Simple Wood} is sold by the trade and general goods vendors in most towns. Open your Professions window (the hammer and pick button in the menu bar), craft the kit from 1 Simple Wood under Cooking, then use it from your bags to place the campfire."] = "向任意烹饪训练师学习烹饪，技能 1 时就会附带学会基础营火包。{i:4470:inv_tradeskillitem_01:Simple Wood} 在大多数城镇的商业供应商和杂货商处有售。打开专业窗口（菜单栏中的锤子和矿镐按钮），在烹饪下用 1 个简易木材制作营火包，然后从背包中使用它来放置营火。",
  ["{b}Tip:{/b} you don't have to carry Flint and Tinder and wood around any more, craft a stack of Basic Campfire Kits at home and carry only those, they take one bag slot. You can also hand them to others."] = "{b}提示：{/b}你不用再随身带着火石、火绒和木材了，在家里做好一叠基础营火包，只带着它们就行，只占一个背包格子。你也可以把它们送给别人。",
  ["The bigger campfires hold more camp items, but they need a Blueprint."] = "更大的营火能容纳更多营地物品，但需要蓝图。",
  ["The Expert Campfire Kit needs more Cooking to use than to learn (220 against 200). It's usually the other way around, so maybe it's a bug."] = "专家营火包的使用技能要求比学习要求还高（220 对 200）。通常情况恰好相反，所以这可能是个 bug。",
  ["Learn at"] = "学习技能",
  ["Use at"] = "使用技能",
  ["Camp items"] = "营地物品",
  ["Made from"] = "制作材料",
  ["Comes with Cooking"] = "随烹饪附带",
  ["{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} Dropped by: {n:3673::Lord Serpentis} in Wailing Caverns"] = "{i:273087:inv_garrison_blueprints3:Blueprint: Journeyman Campfire} 掉落自：哀嚎洞穴的 {n:3673::Lord Serpentis}",
  ["{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} I don't know yet where it drops"] = "{i:273101:inv_garrison_blueprints3:Blueprint: Expert Campfire} 我还不知道它从哪里掉落",
  ["Camp Items"] = "营地物品",
  ["Every profession has three camp items, at skill 20, 140 and 300 (Cooking has two), and each one replaces the one before. The tier 1 item comes from your profession trainer, {b}tier 2 and 3 need a Blueprint{/b}, a recipe item. The tier 2 and 3 blueprints drop from bosses, most of them in dungeons, the tabs show which one. Only the Herbalism one at 300 is not known yet."] = "每个专业都有三件营地物品，分别在技能 20、140 和 300 时获得（烹饪只有两件），每一件都会取代前一件。第 1 级物品来自你的专业训练师，{b}第 2 和第 3 级需要蓝图{/b}，即一种配方物品。第 2 和第 3 级蓝图由首领掉落，大多在地下城中，标签页里列出了具体是哪个首领。只有草药学 300 的那件目前还不清楚。",
  ["{b}Every item also gives the buff of the tier 1 item of its profession{/b}, so you never have to choose between a buff and a crafting station. A Master Forge still gives the Strength buff of the Sharpening Wheel. Whether a tier 3 item also gives what the tier 2 item gives (an anvil from a Master Forge) is not confirmed yet. The tabs only list what each tier adds."] = "{b}每件物品还会提供同专业第 1 级物品的增益{/b}，所以你永远不必在增益和制造台之间二选一。大师熔炉仍然提供磨刀轮的力量增益。第 3 级物品是否也提供第 2 级物品的功能（例如大师熔炉提供铁砧）还没有确认。标签页只列出了每一级新增的内容。",
  ["Alchemy"] = "炼金术",
  ["Blacksmithing"] = "锻造",
  ["Enchanting"] = "附魔",
  ["Engineering"] = "工程学",
  ["Leatherworking"] = "制皮",
  ["Tailoring"] = "裁缝",
  ["Skinning"] = "剥皮",
  ["First Aid"] = "急救",
  ["Camp Item"] = "营地物品",
  ["What It Does"] = "作用",
  ["Mana regeneration buff, doesn't stack with Blessing of Wisdom"] = "法力恢复增益，不能与智慧祝福叠加",
  ["Trainer or the Camping 101 quest"] = "训练师或 Camping 101 任务",
  ["A Fermenter, needed for a few Alchemy recipes"] = "发酵器，部分炼金术配方需要",
  ["{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "{i:273085:inv_garrison_blueprints3:Blueprint: Fermenter} 掉落自：洛丹伦废墟的 {n:250657::Rath'mael}",
  ["An Alchemy Lab, needed for some Alchemy recipes"] = "炼金实验室，部分炼金术配方需要",
  ["{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "{i:273112:inv_garrison_blueprints3:Blueprint: Alchemy Laboratory} 掉落自：通灵学院的 {n:10508::Ras Frostwhisper}",
  ["Strength buff, doesn't stack with Strength of Earth Totem"] = "力量增益，不能与大地之力图腾叠加",
  ["An anvil"] = "铁砧",
  ["{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} Dropped by: {n:1763::Gilnid} in The Deadmines"] = "{i:273086:inv_garrison_blueprints3:Blueprint: Anvil} 掉落自：死亡矿井的 {n:1763::Gilnid}",
  ["A Master Forge, needed for many Blacksmithing recipes"] = "大师熔炉，许多锻造配方需要",
  ["{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "{i:273113:inv_garrison_blueprints3:Blueprint: Master Forge} 掉落自：黑石深渊的 {n:8983::Golem Lord Argelmach}",
  ["Armor, all stats and resistances buff, doesn't stack with Mark of the Wild"] = "护甲、全属性和抗性增益，不能与野性印记叠加",
  ["Better disenchanting"] = "更好的分解效果",
  ["{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} Dropped by: {n:246020::Shade of the Archmage} in the City of Dalaran"] = "{i:273103:inv_garrison_blueprints3:Blueprint: Arcane Salvager} 掉落自：达拉然城的 {n:246020::Shade of the Archmage}",
  ["An Arcane Forge, needed for some Enchanting recipes"] = "奥术熔炉，部分附魔配方需要",
  ["{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} Dropped by: {n:261809::Nanaya} in Kalimdor"] = "{i:273116:inv_garrison_blueprints3:Blueprint: Arcane Forge} 掉落自：卡利姆多的 {n:261809::Nanaya}",
  ["Summons the {n:242498::Reagent Bot}, a vendor with class reagents and profession supplies for everyone at the camp"] = "召唤 {n:242498::Reagent Bot}，一个为营地所有人出售职业施法材料和专业用品的商人",
  ["Repairs for everyone at the camp"] = "为营地所有人修理装备",
  ["{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} Dropped by: {n:643::Sneed} in The Deadmines"] = "{i:273092:inv_garrison_blueprints3:Blueprint: Repair Bot} 掉落自：死亡矿井的 {n:643::Sneed}",
  ["An Anarchist's Workbench, needed for some Engineering recipes"] = "无政府主义者工作台，部分工程学配方需要",
  ["{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "{i:273117:inv_garrison_blueprints3:Blueprint: Anarchist's Workbench} 掉落自：斯坦索姆的 {n:11058::Ezra Grimm}",
  ["Rested experience up to 5% of a level, once an hour (a debuff blocks it until then)"] = "每小时一次，提供最多一级 5% 的休息经验（在此之前会有减益效果阻止再次获得）",
  ["A Tanning Rack, needed for many Leatherworking recipes"] = "制革架，许多制皮配方需要",
  ["{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "{i:273096:inv_garrison_blueprints3:Blueprint: Tanning Rack} 掉落自：影牙城堡的 {n:3886::Razorclaw the Butcher}",
  ["A Sewing Machine, needed for many Leatherworking recipes"] = "缝纫机，许多制皮配方需要",
  ["{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} Dropped by: {n:10432::Vectus} in Scholomance"] = "{i:273121:inv_garrison_blueprints3:Blueprint: Sewing Machine} 掉落自：通灵学院的 {n:10432::Vectus}",
  ["Spirit buff for players of your faction, doesn't stack with Divine Spirit. Horde and Alliance each have their own banner"] = "为你所在阵营的玩家提供精神增益，不能与神圣之灵叠加。部落和联盟各有自己的旗帜",
  ["A Spinning Wheel, needed for many Tailoring recipes"] = "纺车，许多裁缝配方需要",
  ["{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "{i:273099:inv_garrison_blueprints3:Blueprint: Spinning Wheel} 掉落自：达拉然城的 {n:246017::Unstable Sentinel}",
  ["A Loom, needed for many Tailoring recipes"] = "织布机，许多裁缝配方需要",
  ["{i:273124:inv_garrison_blueprints3:Blueprint: Loom} Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "{i:273124:inv_garrison_blueprints3:Blueprint: Loom} 掉落自：斯坦索姆的 {n:10436::Baroness Anastari}",
  ["Intellect buff, doesn't stack with Arcane Intellect"] = "智力增益，不能与奥术智慧叠加",
  ["A Greenhouse that grows herbs from seeds you plant"] = "温室，能用你种下的种子种出草药",
  ["{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} Dropped by: {n:260325::Shadetooth} in Excavation Site: Wetlands"] = "{i:273106:inv_garrison_blueprints3:Blueprint: Greenhouse} 掉落自：Excavation Site: Wetlands 的 {n:260325::Shadetooth}",
  ["A Seed Hybridizer that multiplies seeds or combines them into rarer ones"] = "种子杂交器，可以让种子增殖或将它们合成更稀有的种子",
  ["Melee Attack Power buff, doesn't stack with Blessing of Might"] = "近战攻击强度增益，不能与力量祝福叠加",
  ["Spawns a common mining node over time, and gives the Lodestone buff too"] = "会随时间刷出普通矿点，同时也提供磁石增益",
  ["{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} Dropped by: {n:260326::Relic Guardian} in Excavation Site: Wetlands"] = "{i:273097:inv_garrison_blueprints3:Blueprint: Rock Garden} 掉落自：Excavation Site: Wetlands 的 {n:260326::Relic Guardian}",
  ["A Molten Foundry, needed for Smelt Heavy Thorium"] = "熔铸炉，熔炼重型瑟银需要",
  ["{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "{i:273122:inv_garrison_blueprints3:Blueprint: Molten Foundry} 掉落自：黑石深渊的 {n:9156::Ambassador Flamelash}",
  ["+2% crit chance, doesn't stack with Moonkin Aura"] = "+2% 暴击几率，不能与枭兽光环叠加",
  ["A book anyone can read to learn Track Beasts"] = "一本任何人都能阅读的书，可以学会追踪野兽",
  ["{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} Dropped by: {n:3671::Lady Anacondra} in Wailing Caverns"] = "{i:273098:inv_garrison_blueprints3:Blueprint: Field Guide} 掉落自：哀嚎洞穴的 {n:3671::Lady Anacondra}",
  ["A workbench with 1 trap"] = "一个带 1 个陷阱的工作台",
  ["{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} Dropped by: {n:10430::The Beast} in Upper Blackrock Spire and {n:3974::Houndmaster Loksey} in Scarlet Monastery"] = "{i:273109:inv_garrison_blueprints3:Blueprint: Trapper's Workbench} 掉落自：黑石塔上层的 {n:10430::The Beast} 和血色修道院的 {n:3974::Houndmaster Loksey}",
  ["Cooking has no tier 1 camp item, its first one is the campfire (see How to Make a Campfire above)."] = "烹饪没有第 1 级营地物品，它的第一件就是营火（见上文“如何制作营火”）。",
  ["Stamina food for everyone at the camp"] = "为营地所有人提供耐力食物",
  ["{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} Dropped by: {n:645::Cookie} in The Deadmines"] = "{i:273102:inv_garrison_blueprints3:Blueprint: Cookie's Feast} 掉落自：死亡矿井的 {n:645::Cookie}",
  ["An Iron Oven, needed for the most advanced Cooking recipes"] = "铁炉灶，最高级的烹饪配方需要",
  ["{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "{i:273115:inv_garrison_blueprints3:Blueprint: Iron Oven} 掉落自：黑石塔下层的 {n:9736::Quartermaster Zigris}",
  ["Stamina buff, doesn't stack with Power Word: Fortitude"] = "耐力增益，不能与真言术：韧叠加",
  ["Healing potions and anti-venom"] = "治疗药水和抗毒药",
  ["{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} Dropped by: {n:4278::Commander Springvale} in Shadowfang Keep"] = "{i:273105:inv_garrison_blueprints3:Blueprint: Toxin Study} 掉落自：影牙城堡的 {n:4278::Commander Springvale}",
  ["Healing potions and poultices"] = "治疗药水和药膏",
  ["{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} Dropped by: {n:11261::Doctor Theolen Krastinov} in Scholomance"] = "{i:273118:inv_garrison_blueprints3:Blueprint: Plague Doctor's Laboratory} 掉落自：通灵学院的 {n:11261::Doctor Theolen Krastinov}",
  ["+8% all stats, doesn't stack with Blessing of Kings"] = "+8% 全属性，不能与王者祝福叠加",
  ["Uncommon fish for 1 hour and Fishing lures"] = "1 小时内可钓到优秀品质的鱼，并提供鱼饵",
  ["{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} Dropped by: {n:6243::Gelihast} in Blackfathom Deeps"] = "{i:273141:inv_garrison_blueprints3:Blueprint: Fishing Rack} 掉落自：黑暗深渊的 {n:6243::Gelihast}",
  ["Rare fish for 1 hour and Fishing lures"] = "1 小时内可钓到稀有品质的鱼，并提供鱼饵",
  ["{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} Dropped by: {n:5710::Jammal'an the Prophet} in the Sunken Temple"] = "{i:273119:inv_garrison_blueprints3:Blueprint: Fishing Hut} 掉落自：沉没的神庙的 {n:5710::Jammal'an the Prophet}",
  ["Crafting Stations: Tanning Rack, Loom and More"] = "制造台：制革架、织布机等",
  ["A lot of recipes in WoW Forever need a crafting station nearby, like a Tanning Rack, a Spinning Wheel or a Loom. {b}I haven't found any of them out in the world{/b}, they only come from camps, so for a lot of higher level crafting you need a camp. The easiest way is a camp that already has the station, anyone at the fire can use it."] = "WoW Forever 中很多配方需要附近有制造台，比如制革架、纺车或织布机。{b}我在野外一个都没找到{/b}，它们只来自营地，所以很多高等级制造都需要营地。最简单的办法是找一个已经有该制造台的营地，火堆旁的任何人都能使用。",
  ["To place one yourself:"] = "要自己放置一个：",
  ["Get your profession to the skill in the table below."] = "把你的专业练到下表中的技能等级。",
  ["Get the station's Blueprint and learn it. The table shows where it drops, if we know it."] = "获取该制造台的蓝图并学会它。如果我们知道掉落地点，表中会列出。",
  ["Craft the station, put down a campfire and use the station from your bags next to it."] = "制作制造台，放下营火，然后在营火旁从背包中使用制造台。",
  ["Station"] = "制造台",
  ["Profession"] = "专业",
  ["Blueprint"] = "蓝图",
  ["Dropped by: {n:250657::Rath'mael} in the Ruins of Lordaeron"] = "掉落自：洛丹伦废墟的 {n:250657::Rath'mael}",
  ["Dropped by: {n:10508::Ras Frostwhisper} in Scholomance"] = "掉落自：通灵学院的 {n:10508::Ras Frostwhisper}",
  ["Dropped by: {n:8983::Golem Lord Argelmach} in Blackrock Depths"] = "掉落自：黑石深渊的 {n:8983::Golem Lord Argelmach}",
  ["Dropped by: {n:261809::Nanaya} in Kalimdor"] = "掉落自：卡利姆多的 {n:261809::Nanaya}",
  ["Dropped by: {n:11058::Ezra Grimm} in Stratholme"] = "掉落自：斯坦索姆的 {n:11058::Ezra Grimm}",
  ["Dropped by: {n:3886::Razorclaw the Butcher} in Shadowfang Keep"] = "掉落自：影牙城堡的 {n:3886::Razorclaw the Butcher}",
  ["Dropped by: {n:10432::Vectus} in Scholomance"] = "掉落自：通灵学院的 {n:10432::Vectus}",
  ["Dropped by: {n:246017::Unstable Sentinel} in the City of Dalaran"] = "掉落自：达拉然城的 {n:246017::Unstable Sentinel}",
  ["Dropped by: {n:10436::Baroness Anastari} in Stratholme"] = "掉落自：斯坦索姆的 {n:10436::Baroness Anastari}",
  ["Dropped by: {n:9156::Ambassador Flamelash} in Blackrock Depths"] = "掉落自：黑石深渊的 {n:9156::Ambassador Flamelash}",
  ["Dropped by: {n:9736::Quartermaster Zigris} in Lower Blackrock Spire"] = "掉落自：黑石塔下层的 {n:9736::Quartermaster Zigris}",
  ["Merchant's Favor is a new currency in WoW Forever. You get it by filling Waylaid Crates with materials and handing them in at your faction's camp, Durotar Supply and Logistics for Horde and the Azeroth Commerce Authority for Alliance, and you spend it on the recipes, mount, pet, tabard and titles the camp vendors sell. Many recipes and the mount, pet and tabard also need reputation with the camp, which you get from Craftsman's Writs. This WoW Forever Merchant's Favor guide will show you where the camps are, how to earn Merchant's Favor and reputation, and every recipe the vendors sell."] = "Merchant's Favor 是 WoW Forever 中的一种新货币。获取方式是把材料装进 Waylaid Crate，然后交到你阵营的营地：部落是 Durotar Supply and Logistics，联盟是 Azeroth Commerce Authority；你可以用它购买营地商人出售的配方、坐骑、宠物、战袍和头衔。许多配方以及坐骑、宠物和战袍还需要营地声望，声望来自工匠令状。这份 WoW Forever Merchant's Favor 指南将告诉你营地在哪里、如何获得 Merchant's Favor 和声望，以及商人出售的所有配方。",
  ["How It Works"] = "运作方式",
  ["Waylaid Crates drop randomly in the open world and in dungeons, and you can also buy them on the Auction House. You fill a crate with the materials it asks for and hand it in at your camp. For that you get Merchant's Favor, the currency you buy the recipes with."] = "Waylaid Crate 会在野外和地下城中随机掉落，你也可以在拍卖行购买。把箱子要求的材料装进去，然后交到你的营地。这样你就能获得 Merchant's Favor，也就是用来购买配方的货币。",
  ["Many recipes also need reputation with the camp. You earn reputation by doing Craftsman's Writs. You get a writ, craft the item it asks for and bring it to the customer."] = "许多配方还需要营地声望。你通过完成工匠令状来获得声望。拿到一份令状，制作它要求的物品，然后交给顾客。",
  ["Where the Camps Are"] = "营地位置",
  ["The Horde camp belongs to Durotar Supply and Logistics, and the Alliance camp belongs to the Azeroth Commerce Authority. Each camp has a recipe vendor for every crafting profession and Cooking, and both camps sell the same recipes (see Recipes by Profession below)."] = "部落营地属于 Durotar Supply and Logistics，联盟营地属于 Azeroth Commerce Authority。每个营地都为每个制造专业和烹饪配备了一名配方商人，两个营地出售的配方相同（见下文“各专业配方”）。",
  ["Three Corners, Redridge Mountains"] = "赤脊山，三角路口",
  ["How to Earn Merchant's Favor"] = "如何获得 Merchant's Favor",
  ["You earn Merchant's Favor by filling Waylaid Crates with materials and bringing them to your camp."] = "你可以通过把材料装进 Waylaid Crate 并带回营地来获得 Merchant's Favor。",
  ["Merchant's Favor is per character, so every character has to earn its own."] = "Merchant's Favor 按角色计算，所以每个角色都得自己赚。",
  ["Filling a Waylaid Crate"] = "装填 Waylaid Crate",
  ["{b}Find a Waylaid Crate.{/b} They drop randomly in the open world and in dungeons, and {b}you can also buy them on the Auction House{/b}. Each one asks for one kind of material, for example {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}."] = "{b}找到一个 Waylaid Crate。{/b}它们会在野外和地下城中随机掉落，{b}你也可以在拍卖行购买{/b}。每个箱子要求一类材料，例如 {i:248684:inv_crate_07:Waylaid Crate: Apprentice Textiles}。",
  ["Right-click it and fill it with one of the bundles it lists, for example 40 Linen Cloth or 20 Light Leather (see Waylaid Crates and Rewards below). You get a Sealed crate, and that one binds to you."] = "右键点击它，用其中列出的任意一组材料装满，例如 40 块亚麻布或 20 张轻皮（见下文“Waylaid Crate 与奖励”）。你会得到一个密封的箱子，它会与你绑定。",
  ["Bring the Sealed crate to {n:0::Dokimi} at the Horde camp or {n:0::Marcy Baker} at the Alliance camp. You get Merchant's Favor and some silver for it."] = "把密封的箱子交给部落营地的 {n:0::Dokimi} 或联盟营地的 {n:0::Marcy Baker}。你会获得 Merchant's Favor 和一些银币。",
  ["Waylaid Crates and Rewards"] = "Waylaid Crate 与奖励",
  ["When you fill a Waylaid Crate, it turns into a Sealed crate of the same rank and color. You hand that one in at your camp for the Merchant's Favor in the last column. There are also blue Sealed crates and a Sealed Elite Crate, but I don't know yet what they give."] = "装满一个 Waylaid Crate 后，它会变成同等级、同颜色的密封箱子。把它交到你的营地，即可获得最后一列所示的 Merchant's Favor。另外还有蓝色的密封箱子和密封的精英箱子，但我还不知道它们给什么。",
  ["The Textiles, Ore, Herbs and Curiosities crates take raw materials, and the Fabrics, Ingots and Parts crates take crafted ones."] = "纺织品、矿石、草药和珍奇物品箱子收的是原材料，而布料、金属锭和零件箱子收的是制成品。",
  ["{b}A crate needs only one of the bundles in its row, not all of them.{/b}"] = "{b}一个箱子只需要其所在行中的任意一组材料，而不是全部。{/b}",
  ["Apprentice"] = "学徒",
  ["Journeyman"] = "熟练",
  ["Expert"] = "专家",
  ["Artisan"] = "大师",
  ["You need level 10 to open these."] = "需要 10 级才能打开这些。",
  ["You also get {m:2:s:} {m:50:c:} for a white crate and {m:5:s:} for a green one."] = "白色箱子还会额外给你 {m:2:s:} {m:50:c:}，绿色箱子给 {m:5:s:}。",
  ["Crate"] = "箱子",
  ["Fill it with one of these"] = "用以下任意一组装满",
  ["Reward"] = "奖励",
  ["You also get {m:5:s:} for a white crate and {m:10:s:} for a green one."] = "白色箱子还会额外给你 {m:5:s:}，绿色箱子给 {m:10:s:}。",
  ["You need level 20 to open these."] = "需要 20 级才能打开这些。",
  ["You also get {m:7:s:} {m:50:c:} for a white crate and {m:15:s:} for a green one."] = "白色箱子还会额外给你 {m:7:s:} {m:50:c:}，绿色箱子给 {m:15:s:}。",
  ["You need level 35 to open these."] = "需要 35 级才能打开这些。",
  ["Not known yet"] = "暂不清楚",
  ["How to Earn Durotar Supply and Azeroth Commerce Authority Reputation"] = "如何获得 Durotar Supply 和 Azeroth Commerce Authority 声望",
  ["{b}Handing in Sealed crates doesn't give reputation.{/b} Reputation with Durotar Supply and Logistics or the Azeroth Commerce Authority comes from Craftsman's Writs, crafting orders that you deliver to a customer somewhere in the world. After reaching Friendly, empty Waylaid Crates give reputation too (see Crate Returns after Friendly below)."] = "{b}上交密封的箱子不会提供声望。{/b}Durotar Supply and Logistics 或 Azeroth Commerce Authority 的声望来自工匠令状，也就是你需要送到世界某处顾客手中的制造订单。达到友善后，空的 Waylaid Crate 也能提供声望（见下文“友善后的箱子回收”）。",
  ["The first time you fill a crate or start a writ, you also get a {i:280180:inv_misc_note_03:Shipping Label}. It starts a quest to your camp, which gives 2,000 reputation and 50 Merchant's Favor."] = "你第一次装填箱子或开始一份令状时，还会获得一个 {i:280180:inv_misc_note_03:Shipping Label}。它会开启一个前往你营地的任务，奖励 2,000 点声望和 50 Merchant's Favor。",
  ["Craftsman's Writs"] = "工匠令状",
  ["A Journeyman writ gives 75 reputation, an Expert writ 125 and an Artisan writ 200. {b}You can do each writ once a day{/b}, and as many different writs a day as you want."] = "一份熟练令状提供 75 点声望，专家令状 125 点，大师令状 200 点。{b}每份令状每天只能做一次{/b}，但每天可以做任意多份不同的令状。",
  ["{b}Get a Craftsman's Writ.{/b} In the open world and in dungeons they drop as a {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}, {i:262889:inv_misc_note_02:Sealed Expert's Writ} or {i:262890:inv_misc_note_02:Sealed Artisan's Writ}, an envelope with a random writ of that rank inside. {b}You can also buy writs on the Auction House.{/b}"] = "{b}获取一份工匠令状。{/b}在野外和地下城中，它们以 {i:262888:inv_misc_note_02:Sealed Journeyman's Writ}、{i:262889:inv_misc_note_02:Sealed Expert's Writ} 或 {i:262890:inv_misc_note_02:Sealed Artisan's Writ} 的形式掉落，这是一个装着该等级随机令状的信封。{b}你也可以在拍卖行购买令状。{/b}",
  ["Right-click the writ to start its quest, for example {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}."] = "右键点击令状开始它的任务，例如 {i:264047:inv_misc_note_01:Craftsman's Writ: Lesser Wizard's Robe}。",
  ["Make the item it asks for or buy it on the Auction House. You don't need the profession yourself."] = "制作它要求的物品，或者在拍卖行购买。你自己不需要拥有该专业。",
  ["Bring the item to the customer, your map shows where. The customer takes the item and the writ, and you get the reputation and a Coin Pouch with some silver. Writs don't give Merchant's Favor. {b}On the beta, the customer had no question mark over their head.{/b} I think it was a bug, so if you don't see one, right-click them anyway and the window to hand in the writ opens."] = "把物品带给顾客，地图上会显示位置。顾客会收下物品和令状，你会获得声望和一个装有一些银币的钱袋。令状不提供 Merchant's Favor。{b}在测试服上，顾客头上没有问号。{/b}我认为这是个 bug，所以如果你没看到问号，也照样右键点击他们，交付令状的窗口就会打开。",
  ["Crate Returns after Friendly"] = "友善后的箱子回收",
  ["At Friendly, you unlock the Uncertified Scribe in your camp, {n:0:horde:Kurvelk Shadowhoof} at the Horde camp and {n:0:alliance:Dianne Softstep} at the Alliance camp. Both sell the same two items:"] = "达到友善后，你会解锁营地中的未认证文书，部落营地是 {n:0:horde:Kurvelk Shadowhoof}，联盟营地是 {n:0:alliance:Dianne Softstep}。两人出售相同的两件物品：",
  ["Reputation"] = "声望",
  ["What it does"] = "作用",
  ["Friendly"] = "友善",
  ["Turns an empty Waylaid Crate into 50 reputation, see the steps below."] = "把一个空的 Waylaid Crate 变成 50 点声望，步骤见下文。",
  ["Honored"] = "尊敬",
  ["Turns a Craftsman's Writ into a random writ of the same rank."] = "把一份工匠令状换成同等级的随机令状。",
  ["{b}Buy a {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b} from the Uncertified Scribe."] = "{b}在未认证文书处购买一张 {i:262902:inv_10_inscription2_repcontracts_scroll_02_uprez_color5:Forged Delivery Receipt}{/b}。",
  ["Buy a Waylaid Crate on the Auction House. The receipt seems to work on any of them, so buy the cheapest one."] = "在拍卖行买一个 Waylaid Crate。收据似乎对任何箱子都有效，所以买最便宜的就行。",
  ["Use the receipt on the crate. You get a {i:262917:inv_crate_01:Notarized Shipping Container}."] = "对箱子使用收据。你会得到一个 {i:262917:inv_crate_01:Notarized Shipping Container}。",
  ["Hand the container to the same NPC who takes your Sealed crates. You get the reputation and 1 silver."] = "把这个集装箱交给收取你密封箱子的同一个 NPC。你会获得声望和 1 银币。",
  ["Recipes by Profession"] = "各专业配方",
  ["Both camps, Durotar Supply and Logistics (Horde) and the Azeroth Commerce Authority (Alliance), sell the same recipes for Merchant's Favor. This is what each profession gets:"] = "两个营地，即 Durotar Supply and Logistics（部落）和 Azeroth Commerce Authority（联盟），用 Merchant's Favor 出售相同的配方。各专业能获得的内容如下：",
  ["{b}Alchemy:{/b} potions and elixirs."] = "{b}炼金术：{/b}药水和药剂。",
  ["{b}Blacksmithing:{/b} mail and plate sets for tanks, melee, healers and paladins, and three weapons."] = "{b}锻造：{/b}适合坦克、近战、治疗和圣骑士的锁甲及板甲套装，以及三把武器。",
  ["{b}Cooking:{/b} six smoothies that give Spirit."] = "{b}烹饪：{/b}六种提供精神的冰沙。",
  ["{b}Enchanting:{/b} necklace, weapon and armor enchants, relics (idols, totems and librams) and caster weapons (staves, off-hands and wands)."] = "{b}附魔：{/b}项链、武器和护甲附魔，圣物（神像、图腾和圣契）以及施法者武器（法杖、副手物品和魔杖）。",
  ["{b}Engineering:{/b} bombs, thrown weapons, goggles, belts, trinkets and gadgets."] = "{b}工程学：{/b}炸弹、投掷武器、护目镜、腰带、饰品和小玩意。",
  ["{b}Leatherworking:{/b} leather and mail sets for every role, and two armor kits."] = "{b}制皮：{/b}适合各种角色的皮甲和锁甲套装，以及两种护甲片。",
  ["{b}Tailoring:{/b} cloth sets for every spell school and for healers, and two reagent bags."] = "{b}裁缝：{/b}适合各个法术系别和治疗者的布甲套装，以及两种材料包。",
  ["{b}The armor and weapons you craft from these recipes bind on pickup{/b}, so you can only make them for yourself."] = "{b}用这些配方制作的护甲和武器是拾取后绑定的{/b}，所以你只能为自己制作。",
  ["{n:0:horde:Apothecary Durelle} at the Horde camp and {n:0:alliance:Nina Surefire} at the Alliance camp sell 28 Alchemy recipes."] = "部落营地的 {n:0:horde:Apothecary Durelle} 和联盟营地的 {n:0:alliance:Nina Surefire} 出售 28 个炼金术配方。",
